COLLDATA("qiraatkhalfur","ur",[[207,"ہمیں یہ روایت ابوعبداللہ الحافظ امام حاکم نے بیان کی، انھوں نے کہا: ہمیں ابوبکر احمد بن اسحاق الفقیہ الصبغی نے بیان کیا، انھوں نے کہا: ہمیں عبداللہ بن محمد نے بیان کیا، انھوں نے کہا: ہمیں محمد بن یحییٰ نے بیان کیا، انھوں نے کہا: ہمیں سعید بن عامر نے بیان کیا، انھوں نے کہا: ہمیں شعبہ بن حجاج نے بیان کیا، انھوں نے مسعر بن کدام سے روایت کیا، انھوں نے اسی طرح حدیث بیان کی۔ (1)\nسیدنا ابودرداء رضی اللہ عنہ کی روایات:\n(سیدنا ابودرداء رضی اللہ عنہ کبار مفتی صحابہ کرام میں شمار ہوتے تھے۔ آپ رضی اللہ عنہ کی اہلیہ بھی امام کے پیچھے قرآت کرنے کے قائل اور اس پر عمل پیرا تھے۔ [العاصم])","",{"f":"§حواشی\n(1) صحیح سنن ابن ماجة: حدیث، 843 السنن الكبرى للبيهقي: 170/2 مصنف ابن أبي شيبة: 263/3، حدیث، 3749 جزء القراءة خلف الإمام، ص، 160، حدیث، 272 حلية الأولياء، لأبي نعيم: 269/7۔"}],[208,"§سیدنا ابودرداء رضی اللہ عنہ کا فتویٰ:\nہمیں احمد بن محمد بن احمد بن حارث الاصبہانی نے بیان کیا، انھوں نے کہا: ہمیں ابو محمد بن حیان نے بیان کیا، انھوں نے کہا: ہمیں ابوبکر بن ابی داؤد نے بیان کیا، انھوں نے کہا: ہمیں احمد بن ابی الحواری، عمرو بن عثمان، محمود بن خالد، کثیر بن عبید اور علی بن سہل نے بیان کیا، ان سب نے کہا: ہمیں ولید بن مسلم قرشی نے بیان کیا، انھوں نے عبدالرحمن بن عمرو الاوزاعی سے، انھوں نے حسان بن عطیہ سے روایت کیا کہ سیدنا ابودرداء رضی اللہ عنہ نے فرمایا: امام کے پیچھے سورۃ فاتحہ پڑھنا مت چھوڑو، چاہے امام جہری قرآت کرے یا جہری نہ کرے (سری کرے)۔ (1)\nرکوع کے لیے جھکتے جھکتے فاتحہ پڑھ لو:\nیہ الفاظ کثیر بن عبید کی روایت کے ہیں۔ اور علی بن سہل اور احمد بن ابی الحواری نے یہ بھی بیان کیا ہے کہ اگر تم رکوع کے لیے جھک بھی رہے ہو (اور ابھی فاتحہ پڑھنی ہو) تو اسے پڑھو۔ صرف عمرو بن عثمان نے یہ اضافہ بھی بیان کیا ہے کہ اگر تمھیں یقین ہو کہ تم رکوع کے آخر تک امام سے مل جاؤ گے تو امام چاہے رکوع میں چلا جائے، پھر بھی تم فاتحہ پڑھو۔","",{"f":"§حواشی\n(1) ولید بن مسلم کثیر التدلیس راوی ہے اور حسان بن عطیہ کی سیدنا ابودرداء رضی اللہ عنہ سے ملاقات نہیں ہے۔ یہ سند ضعیف ہے۔ السنن الكبرى للبيهقي: 170/2۔"}],[209,"§سیدنا ابودرداء رضی اللہ عنہ کا پسندیدہ عمل:\nہمیں ابوعبداللہ الحافظ نے بیان کیا، انھوں نے کہا: ہمیں ابوبکر بن اسحاق الفقیہ الصبغی نے بیان کیا، انھوں نے کہا: ہمیں محمد بن یحییٰ بن سہل نے بیان کیا، انھوں نے کہا: ہمیں محمد بن یحییٰ بن عبداللہ الذہلی نے بیان کیا، انھوں نے کہا: ہمیں محمد بن کثیر نے بیان کیا، انھوں نے کہا: ہمیں عبدالرحمن الاوزاعی نے بیان کیا، انھوں نے حسن بن عطیہ سے، انھوں نے ابودرداء رضی اللہ عنہ سے روایت کیا، انھوں نے کہا: اگر میں امام کو رکوع کے لیے جھکتا ہوا بھی پاؤں تب بھی میں سورۃ فاتحہ پڑھنا پسند کروں گا۔ (1)\nسیدنا انس بن مالک رضی اللہ عنہ کی روایات:\n(سیدنا انس بن مالک رضی اللہ عنہ رسول اللہ صلی اللہ علیہ وسلم کے خادم خاص تھے۔ آپ رضی اللہ عنہ نے تو ہوش ہی قصر نبوت میں سنبھالا تھا۔ آپ رضی اللہ عنہ بھی امام کے پیچھے قرآت کرتے تھے، اور اس کا حکم بھی دیتے تھے۔ [العاصم])","",{"f":"§حواشی\n(1) حسان بن عطیہ کی سیدنا ابودرداء رضی اللہ عنہ سے ملاقات نہیں ہے۔ یہ سند ضعیف ہے۔ (حوالہ سابقہ)"}],[210,"§سیدنا انس بن مالک رضی اللہ عنہ کا حکم اور عمل:\nہمیں ابوعبداللہ الحافظ (امام حاکم) نے بیان کیا، انھوں نے کہا: مجھے محمد بن یعقوب ابوالعباس نے بیان کیا، انھوں نے کہا: ہمیں محمد بن اسحاق بن خزیمہ نے بیان کیا، انھوں نے کہا: ہمیں احمد بن سعید الدارمی نے بیان کیا، انھوں نے کہا: ہمیں نضر بن شمیل نے بیان کیا، انھوں نے کہا: ہمیں عوام بن حمزہ نے بیان کیا، انھوں نے ثابت بن اسلم البنانی سے روایت کیا کہ سیدنا انس بن مالک رضی اللہ عنہ، ہمیں امام کے پیچھے قرآت کرنے کا حکم دیا کرتے تھے۔ کہتے ہیں: میں سیدنا انس رضی اللہ عنہ کے پہلو میں (بالکل قریب، ایک طرف) کھڑا تھا، کہ آپ رضی اللہ عنہ سورۃ فاتحہ اور مفصل سورتوں میں سے ایک سورت پڑھ رہے تھے۔ اور ہمیں سناتے بھی تھے تاکہ ہم آپ رضی اللہ عنہ سے یہ (مسئلہ) سیکھ لیں۔ (1)","",{"f":"§حواشی\n(1) حسن السنن الكبرى للبيهقي: 170/2۔"}],[211,"ہمیں ابوعبداللہ (امام حاکم) نے بیان کیا، انھوں نے کہا: مجھے محمد بن عبداللہ الجوہری نے بیان کیا، انھوں نے کہا: ہمیں محمد بن اسحاق بن خزیمہ نے بیان کیا، انھوں نے کہا: ہمیں محمد بن وجیہ نے بیان کیا، انھوں نے کہا: ہمیں نضر بن شمیل نے بیان کیا، انھوں نے اپنی سند سے اسی طرح حدیث بیان کی۔ البتہ انھوں نے اس سند میں عوام بن حوشب سے روایت کی ہے۔ (1)\nسیدنا عمران بن حصین رضی اللہ عنہ کی روایات:\n(سیدنا عمران بن حصین رضی اللہ عنہ فاتحہ کے بغیر نماز کو درست نہیں سمجھتے تھے۔ [العاصم])","",{"f":"§حواشی\n(1) یہ اثر حسن ہے۔ یہاں امام بیہقی رحمہ اللہ نے جس سند کی طرف اشارہ کیا ہے وہ سند اور اس کا متن اس طرح ہے: «أَخْبَرَنَا أَبُو عَبْدِ اللهِ الْحَافِظُ فِي التَّارِيخِ، أَخْبَرَنِي مُحَمَّدُ بْنُ عَبْدِ اللهِ الْجَوْهَرِيُّ، ثَنَا مُحَمَّدُ بْنُ إِسْحَاقَ بْنِ خُزَيْمَةَ، ثَنَا مُحَمَّدُ بْنُ الْوَجِيهِ يَعْنِي النَّيْسَابُورِيَّ، ثَنَا النَّصْرُ بْنُ شُمَيْلٍ، أَنْبَأَ الْعَوَّامُ بْنُ حَوْشَبٍ، عَنْ ثَابِتٍ، عَنْ أَنَسٍ قَالَ: كَانَ يَأْمُرُنَا بِالْقِرَاءَةِ خَلْفَ الْإِمَامِ۔ قَالَ: وَكُنْتُ أَقُومُ إِلَى جَنْبِ أَنَسٍ فَيَقْرَأُ بِفَاتِحَةِ الْكِتَابِ وَسُورَةٍ مِنَ الْمُفَصَّلِ وَيُسْمِعُنَا قِرَاءَتَهُ لِنَأْخُذَ عَنْهُ» [السنن الکبریٰ للبیہقی: 243/2، حدیث، 2947]۔ اس روایت کی سند میں ایک راوی کا فرق ہے، جبکہ متن و مفہوم وہی ہے۔"}],[212,"§اس شخص کی نماز درست نہیں:\nہمیں ابوعلی الحسین بن محمد بن محمد بن علی الروذباری نے بیان کیا، انھوں نے کہا: ہمیں ابومحمد عبداللہ بن عمر بن شوذب الواسطی نے بیان کیا، انھوں نے کہا: ہمیں محمد بن عبد الملک الدقیقی نے بیان کیا، انھوں نے کہا: ہمیں یزید بن ہارون نے بیان کیا، انھوں نے کہا: ہمیں زیاد بن ابی زیاد الجصاص نے بیان کیا، انھوں نے کہا: ہمیں حسن بن سیار البصری نے بیان کیا، انھوں نے کہا: مجھے سیدنا عمران بن حصین رضی اللہ عنہ نے بیان کیا، انھوں نے فرمایا: مسلمان کی نماز؛ وضو، رکوع، سجود اور سورۃ فاتحہ کے بغیر درست نہیں ہوتی، چاہے وہ امام کے پیچھے ہو یا اکیلا ہو۔ (1)","",{"f":"§حواشی\n(1) زیاد الجصاص ضعیف راوی ہے۔ یہ سند حسن لغیرہ ہے۔ جزء القراءۃ خلف الامام للبخاری: ص، 47، حدیث، 68۔"}],[213,"§فاتحہ کے بغیر نماز ہی نہیں ہوتی (سیدنا عمران رضی اللہ عنہ کا فتویٰ):\nہمیں محمد بن عبداللہ الحافظ (امام حاکم) نے بیان کیا، انھوں نے کہا: ہمیں ابوبکر بن اسحاق الفقیہ الصبغی نے بیان کیا، انھوں نے کہا: ہمیں عبداللہ بن محمد نے بیان کیا، انھوں نے کہا: ہمیں حمید بن مسعدہ نے بیان کیا، انھوں نے کہا: ہمیں بشر بن مفضل الرقاشی نے بیان کیا، انھوں نے سعید بن ایاس الجریری سے، انھوں نے عبداللہ بن بریدہ سے، انھوں نے سیدنا عمران بن حصین رضی اللہ عنہ سے روایت کیا، انھوں نے فرمایا: سورت فاتحہ اور مزید (کم از کم) دو آیات کے بغیر نماز درست نہیں ہے۔ (1)\nسیدنا عبداللہ بن مغفل المزنی رضی اللہ عنہ کی روایت:\n(سیدنا عبداللہ بن مغفل المزنی رضی اللہ عنہ امام کے قرآت کے نہ صرف خود قائل تھے، بلکہ انھوں نے تمام صحابہ کا عمل بھی یہی بیان کیا ہے۔ [العاصم])","",{"f":"§حواشی\n(1) صحیح۔ معجم ابن المقرئ، ص 92، حدیث، 221۔"}],[214,"§سیدنا عبداللہ بن مغفل رضی اللہ عنہ کا عمل اور ترغیب:\nہمیں ابوبکر بن حارث الفقیہ الاصبہانی نے بیان کیا، انھوں نے کہا: ہمیں ابو محمد بن حیان نے بیان کیا، انھوں نے کہا: ہمیں احمد بن محمود نے بیان کیا، انھوں نے کہا: ہمیں علی بن یونس نے بیان کیا، انھوں نے کہا: ہمیں ابو داؤد الطیالسی نے بیان کیا، انھوں نے کہا: ہمیں شعبہ بن حجاج نے بیان کیا، انھوں نے یحییٰ بن ابی اسحاق سے، اور حماد بن سلمہ اور یزید بن زریع نے بھی یحییٰ بن ابی اسحاق سے روایت کیا ہے۔ (1) انھوں نے عمر بن ابی سحیم البصری سے روایت کیا، انھوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم کے صحابی سیدنا عبداللہ بن مغفل المزنی رضی اللہ عنہ ہمیں تعلیم دیا کرتے تھے کہ ہم ظہر و عصر میں امام کے پیچھے پہلی دو رکعات میں سورت فاتحہ اور کوئی دوسری سورت، جبکہ آخری دو رکعات میں سورت فاتحہ پڑھیں۔ (2)","",{"f":"§حواشی\n(1) سید بدیع الدین راشدی رحمہ اللہ کے مخطوطہ میں یہاں: ’’حماد بن سلمہ اور یزید بن زریع نے بھی یحییٰ بن ابی اسحاق سے روایت کیا‘‘ بھی مذکور ہے۔ جو کہ السنن الکبریٰ للبیہقی میں بھی اسی طرح مذکور ہے، جبکہ دیگر مصادر میں سند اس طرح نہیں ہے۔ دیکھئے: السنن الکبریٰ للبیہقی: 244/2، حدیث، 2949۔\n(2) یہ سند ضعیف ہے۔ عمر بن ابی سحیم کو ابن حبان کے علاوہ کسی نے ثقہ نہیں کہا۔ مصنف ابن ابی شیبہ: 263/3، حدیث، 3752۔ یہ حدیث حماد بن سلمہ کی سند کے ساتھ: جزء القراءۃ خلف الامام، للبخاری: ص، 48، حدیث، 70، میں اور یزید بن زریع کی سند کے ساتھ: الاوسط لابن المنذر، 103/3، حدیث، 1316 میں مذکور ہے۔"}],[215,"(گذشتہ روایات میں صحابہ کرام رضی اللہ عنہم کی روایات و آثار سے ثابت کیا تھا کہ رسول اللہ صلی اللہ علیہ وسلم نے امام کے پیچھے قرآت کرنے، بلکہ سورت فاتحہ کی قرآت واجب ہونے کی تعلیم دی۔ اور صحابہ کرام رضی اللہ عنہم کا اسی پر عمل تھا اور وہ فتویٰ بھی یہی دیتے تھے۔ ذیل میں تابعین عظام رحمہم اللہ کا عمل اور ان کے فتاویٰ بیان کیے گئے ہیں، جن سے امام کے پیچھے قرآت کا وجوب ثابت ہوتا ہے۔ اسی طرح اس باب میں بعض صحابہ کی مرویات بھی مذکور ہیں، جن کے نام واضح طور پر بیان نہیں کیے گئے، لیکن ان کی روایات اور عمل سے واضح ہوتا ہے کہ صحابہ کرام رضی اللہ عنہم کا معمول امام کے پیچھے قرآت کرنے کا تھا، اور وہ مقتدی کے لیے قرآت میں سورت فاتحہ کے وجوب کے قائل تھے۔ صحابی کا نام اگرچہ مذکور نہ ہو، لیکن بیان کرنے والا تابعی اور دیگر رواۃ ثقہ و معتبر ہوں تو وہ روایت مقبول ہوتی ہے، کیونکہ تمام صحابہ عدول ہیں۔ [العاصم])\n§صحابہ رضی اللہ عنہم امام کے سکتہ میں قرآت کرتے تھے (روایت عبداللہ بن عمرو رضی اللہ عنہ):\nہمیں ابوعبداللہ الحافظ (امام حاکم) نے بیان کیا، انھوں نے کہا: ہمیں ابوطیب محمد بن عبداللہ الشعیر ی نے بیان کیا، انھوں نے کہا: ہمیں عبداللہ بن محمد بن عبدالعزیز القاضی الجرجانی نے (نیساپور کے) محلہ جنجروذ میں بیان کیا، انھوں نے کہا: ہمیں ابوصلت الہروی نے بیان کیا، انھوں نے کہا: ہمیں ابو معاویہ محمد بن خازم الضریر التیمی نے بیان کیا، انھوں نے عبیداللہ بن عمر سے، انھوں نے عمرو بن شعیب سے، انھوں نے اپنے والد محترم شعیب بن محمد سے، انھوں نے اپنے دادا سیدنا عبداللہ بن عمرو بن عاص رضی اللہ عنہ سے روایت کیا کہ رسول اللہ صلی اللہ علیہ وسلم جب خاموش ہوتے (سکتہ کرتے) تب آپ صلی اللہ علیہ وسلم کے پیچھے صحابہ کرام رضی اللہ عنہم قرآت کیا کرتے تھے۔ اور جب آپ صلی اللہ علیہ وسلم قرآت کرتے، تب صحابہ رضی اللہ عنہم قرآت نہیں کرتے تھے۔ اور جب آپ صلی اللہ علیہ وسلم خاموش ہوتے تب صحابہ رضی اللہ عنہم قرآت کرتے تھے۔ اور رسول اللہ صلی اللہ علیہ وسلم فرمایا کرتے تھے: ہر وہ نماز جس میں سورت فاتحہ نہ پڑھی جائے، وہ نماز ناقص ہے۔ (1)\nفاتحہ پڑھنے کے لیے امام، مہلت دیتا تھا (روایت سعید بن جبیر رحمہ اللہ):\nاس حدیث کو اسی مفہوم میں عبدالحمید بن جعفر نے بھی عمرو بن شعیب سے روایت کیا ہے۔","",{"f":"§حواشی\n(1) یہ سند ضعیف ہے۔ اس میں ابوصلت الہروی متہم راوی ہے۔ اس روایت میں ’’وَكَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: كُلُّ صَلَاةٍ لَا يُقْرَأُ فِيهَا بِأُمِّ الْقُرْآنِ فَهِيَ خِدَاجٌ‘‘ کے الفاظ صحیح ہیں۔"}],[216,"ہمیں ابوبکر بن حارث الفقیہ نے بیان کیا، انھوں نے کہا: ہمیں ابو محمد عبداللہ بن محمد بن جعفر اصبہانی نے بیان کیا، انھوں نے کہا: ہمیں محمد بن عباس نے بیان کیا، انھوں نے کہا: مجھے احمد بن سوید نے بیان کیا، انھوں نے عبدالرزاق بن ہمام سے، انھوں نے معمر بن راشد ازدی اور ابن جریج عبدالملک بن عبدالعزیز سے، انھوں نے عبداللہ بن عثمان بن خثیم سے، انھوں نے سعید بن جبیر سے روایت کیا، انھوں نے کہا: پچھلے لوگ اس طرح کرتے تھے کہ جب وہ تکبیر تحریمہ کہہ لیتے تو امام، قرآت کے بغیر اتنی دیر تک (خاموش) کھڑا رہتا کہ مقتدی سورت فاتحہ پڑھ لیتے۔ (1)\nصحابہ رضی اللہ عنہم مقتدیوں کو مہلت دیتے تھے (روایت سعید بن جبیر رحمہ اللہ)\nامام عبدالرزاق بن ہمام کہتے ہیں: ابن جریج نے اپنی حدیث میں ابن خثیم سے، انھوں نے سعید بن جبیر سے روایت کیا، انھوں نے فرمایا: وہ لوگ (صحابہ کرام رضی اللہ عنہم) جب تکبیر کہتے تو قرآت شروع نہیں کرتے تھے، حتیٰ کہ انھیں معلوم ہو جاتا کہ ان کے پچھلوں (مقتدیوں) نے سورۃ فاتحہ پڑھ لی ہے۔\n(امام بیہقی رحمہ اللہ فرماتے ہیں:) میں نے امام بخاری رحمہ اللہ کی تصنیف ’’قراءۃ خلف الامام‘‘ میں پڑھا ہے، انھوں نے فرمایا: ابن خثیم (یعنی: عبداللہ بن عثمان بن خثیم) کہتے ہیں، میں نے سعید بن جبیر سے پوچھا: کیا میں امام کے پیچھے قرآت کروں؟ انھوں نے فرمایا: جی ہاں۔ چاہے تم امام کی قرآت سن رہے ہو (تب بھی قرآت کرو)۔ ان (آج کے) لوگوں نے انوکھا طریقہ اپنا رکھا ہے حالانکہ ایسا وہ لوگ (صحابہ کرام رضی اللہ عنہم) نہیں کرتے تھے۔ اسلاف (یعنی: صحابہ کرام رضی اللہ عنہم) میں جب کوئی لوگوں کی امامت کرتا تو تکبیر کہتا، پھر خاموش ہو جاتا (سکتہ کرتا)، حتیٰ کہ اسے یقین ہو جاتا کہ جو لوگ اس کے پیچھے (مقتدی) ہیں؛ انھوں نے سورۃ فاتحہ پڑھ لی ہے۔ پھر وہ (امام) قرآت کرتا اور پھر انصات اختیار کرتا (خاموش ہو جاتا، سکتہ کرتا)۔\nاسی مفہوم کی حدیث امام ابن خزیمہ رحمہ اللہ نے بھی اپنی کتاب میں جعفر بن محمد تغلبی سے، انھوں نے یحییٰ بن سلیم سے، انھوں نے ابن خثیم سے روایت کی ہے۔ (2)","",{"f":"§حواشی\n(1) حسن، مقطوع۔ مصنف عبدالرزاق: 134/2، حدیث، 2789۔ السنن الکبریٰ للبیہقی: 171/2۔ جزء القراءۃ خلف الامام، للبخاری: ص، 35، حدیث، 42۔\n(2) اس روایت کی سند حسن ہے۔"}],[217,"§عروہ بن زبیر تابعی رحمہ اللہ کا فتویٰ:\nمجھے ابوعبداللہ الحافظ (امام حاکم) نے بالاجازۃ بیان کیا، انھوں نے کہا: ابوعلی الحسین بن علی الحافظ نیساپوری نے انھیں بتایا کہ ہمیں ابراہیم بن عبداللہ بن احمد بن حفص نے بیان کیا، انھوں نے کہا: ہمیں احمد بن یوسف نے بیان کیا، انھوں نے کہا: ہمیں حجاج بن منہال انماطی نے بیان کیا، انھوں نے کہا: ہمیں حماد بن سلمہ البصری نے بیان کیا۔"],[218,"ہمیں احمد بن محمد الفقیہ نے بیان کیا، انھوں نے کہا: ہمیں ابومحمد بن حیان نے بیان کیا، انھوں نے کہا: ہمیں محمد بن عباس نے بیان کیا، انھوں نے کہا: ہمیں احمد بن سوید نے بیان کیا، انھوں نے حجاج بن منہال سے روایت کیا، انھوں نے کہا: ہمیں حماد بن سلمہ نے بیان کیا، انھوں نے ہشام بن عروہ سے روایت کیا، انھوں نے اپنے والد محترم عروہ بن زبیر (تابعی) رحمہ اللہ سے روایت کیا، انھوں نے فرمایا: اے بیٹے! امام کے سکتہ میں قرآت کیا کرو۔ دراصل سورۃ فاتحہ کے بغیر نماز مکمل نہیں ہوتی۔ (1)\nاور ابوعبداللہ (امام حاکم) کی روایت (یعنی 216 نمبر پر مذکور پہلی سند کے ساتھ مروی روایت) میں ہے: اے بیٹا! جس رکعت میں امام چپ ہو (یعنی، سری رکعت ہو) اس میں قرآت کرو۔ اور جس رکعت میں امام جہری قرآت کرے اس میں تم خاموش رہو۔ اور مزید فرمایا: اے میرے بیٹا! اس انسان کی نماز نامکمل ہوتی ہے جو سورۃ فاتحہ اور مزید نہیں پڑھتا۔\nچاہے نماز فرض ہو یا نفل۔ (2)","",{"f":"§حواشی\n(1) یہ اثر صحیح ہے۔\n(2) صحیح۔ جزء القراءۃ خلف الامام، للبخاری: ص، 151، حدیث، 262۔ السنن الکبریٰ للبیہقی: 171/2"}],[219,"§امام کے سکتہ میں فاتحہ پڑھ لو (ابوسلمہ رحمہ اللہ کا فتویٰ):\nہمیں امام ابو عثمان اسماعیل بن عبدالرحمن الصابونی رحمہ اللہ نے بیان کیا، انھوں نے کہا: ہمیں ابو طاہر بن خزیمہ نے بیان کیا، انھوں نے کہا: ہمیں میری دادا جان محمد بن اسحاق بن خزیمہ نے بیان کیا، انھوں نے کہا: ہمیں محمد بن عبدالاعلیٰ الصنعانی نے بیان کیا، انھوں نے کہا: ہمیں معتمر بن سلیمان نے بیان کیا، انھوں نے کہا: میں نے محمد بن عمرو کو سنا، انھوں نے عبدالملک بن مغیرہ سے روایت کیا، انھوں نے سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت کیا، انھوں نے فرمایا: ہر وہ نماز جس میں سورۃ فاتحہ نہیں پڑھی گئی، وہ نماز ناقص ہے، ناقص ہے۔ کسی نے پوچھا: جب امام قرآت کر رہا ہو، تب کیا کریں؟ ابوسلمہ بن عبدالرحمن (سیدنا ابو ہریرہ رضی اللہ عنہ کے شاگرد) نے کہا: امام دو سکتے کرتا ہے، انھیں (سورت فاتحہ پڑھنے کے لیے) غنیمت سمجھو۔ ایک سکتہ تب ہے، جب امام تکبیر تحریمہ کہہ لیتا ہے، دوسرا سکتہ تب ہے جب امام ’’غَيْرِ الْمَغْضُوبِ عَلَيْهِمْ وَلَا الضَّالِّينَ‘‘ کہتا ہے۔ (1)\nابوسلمہ رحمہ اللہ کے فتویٰ کی سیدنا ابو ہریرہ رضی اللہ عنہ کے فتویٰ سے مطابقت:\nابوسلمہ بن عبدالرحمن کا جواب سیدنا ابو ہریرہ رضی اللہ عنہ کی موجودگی میں تھا۔ اور سیدنا ابو ہریرہ رضی اللہ عنہ نے ان کے جواب پر انکار نہیں کیا (یعنی جواب کی نفی نہیں کی)۔ اور یہ جواب بالکل اسی طرح تھا جس طرح سیدنا ابو ہریرہ رضی اللہ عنہ نے فرمایا تھا۔ علاء بن عبدالرحمن کی روایت اس حدیث کے صحیح ہونے کے لیے شاہد (مؤید) ہے۔\nاور اس حدیث کو محمد بن ابی عدی اور نضر بن شمیل نے محمد بن عمرو سے، انھوں نے عبدالملک بن مغیرہ سے، انھوں نے سیدنا ابو ہریرہ رضی اللہ عنہ سے، انھوں نے نبی کریم صلی اللہ علیہ وسلم سے روایت کیا ہے۔ البتہ اس میں ابوسلمہ عبدالرحمن کی بات (’’امام دو سکتے کرتا ہے‘‘) مذکور نہیں ہے۔","",{"f":"§حواشی\n(1) یہ سند حسن لغیرہ ہے۔ مسند احمد بن حنبل: 290/2، حدیث، 7888۔"}],[220,"§امام مکحول رحمہ اللہ کا فتویٰ:\nہمیں ابوعلی الروذباری نے بیان کیا، انھوں نے کہا: ہمیں ابوبکر بن داسہ نے بیان کیا، انھوں نے کہا: ہمیں ابو داؤد سلیمان بن اشعث السجستانی نے بیان کیا، انھوں نے کہا: ہمیں علی بن سہل الرملی نے بیان کیا، انھوں نے کہا: ہمیں ولید بن مسلم القرشی نے بیان کیا، انھوں نے عبدالرحمن بن یزید بن جابر ازدی، سعید بن عبدالعزیز التنوخی اور عبداللہ بن علاء بن زبر الربعی سے روایت کیا، ان تینوں نے کہا: مکحول الشامی کہتے ہیں: جس نماز میں امام جہری قرآت کرے اس میں سورۃ فاتحہ سِرّی (دل ہی دل میں) پڑھو، جب امام سورۃ فاتحہ پڑھ کر خاموش ہو جائے (یعنی سکتہ کرے)۔ اگر امام سکتہ نہ کرے؛ تو تم اس سے پہلے، اس کے ساتھ ساتھ اور اس کے بعد؛ (ہر طرح) پڑھ لو، لیکن کسی بھی حال میں اسے مت چھوڑو۔ (1)","",{"f":"§حواشی\n(1) (حسن) یہ سند ضعیف ہے، کیونکہ ولید بن مسلم مدلس ہے۔ البتہ یہ اثر اپنے شواہد کی بنا پر حسن درجہ کا ہے۔ سنن ابی داؤد، حدیث: 825۔ السنن الکبریٰ للبیہقی: 171/2"}],[221,"§سیدنا ابوبکر صدیق رضی اللہ عنہ کے پوتے، قاسم رحمہ اللہ کا فتویٰ:\nہمیں ابوعبداللہ الحافظ (امام حاکم) اور محمد بن موسیٰ نے بیان کیا، ان دونوں نے کہا: ہمیں ابوعباس محمد بن یعقوب نے بیان کیا، انھوں نے کہا: ہمیں اسید بن عاصم نے بیان کیا، انھوں نے کہا: ہمیں حسین بن حفص نے بیان کیا، انھوں نے سفیان بن سعید الثوری سے روایت کیا، انھوں نے کہا: ہمیں اسامہ بن زید اللیثی نے بیان کیا، کہ (سیدنا ابوبکر صدیق رضی اللہ عنہ کے پوتے) قاسم بن محمد نے فرمایا: وہ لوگ جو اپنے وقت کے امام تھے، (یعنی، صحابہ کرام رضی اللہ عنہم)، وہ (نماز میں) امام کے پیچھے قرآت کیا کرتے تھے۔ (1)","",{"f":"§حواشی\n(1) حسن۔ جزء القراءۃ خلف الامام، للبخاری: ص، 33، حدیث، 32۔"}],[222,"§حسن بصری رحمہ اللہ کا فتویٰ:\nہمیں احمد بن محمد اصبہانی نے بیان کیا، انھوں نے کہا: ہمیں ابو الشیخ الاصبہانی نے بیان کیا، انھوں نے کہا: ہمیں محمد بن عباس نے بیان کیا، انھوں نے کہا: ہمیں محمد بن حاتم نے بیان کیا، انھوں نے کہا: ہمیں ہشیم بن بشیر نے بیان کیا، انھوں نے کہا: ہمیں یونس بن عبید بن دینار اور منصور بن زاذان نے بیان کیا کہ حسن بصری فرمایا کرتے تھے: ہر نماز میں امام کے پیچھے اپنے دل ہی دل میں سورۃ فاتحہ پڑھا کرو۔ (1)","",{"f":"§حواشی\n(1) صحیح۔ مصنف ابن ابی شیبہ: 270/3، حدیث، 3783۔ السنن الکبریٰ للبیہقی: 171/2۔ مصنف عبدالرزاق: 134/2، حدیث، 2790۔"}],[223,"§امام شعبی رحمہ اللہ کا فتویٰ:\nاپنی سند کے ساتھ ہشیم بن بشیر نے بیان کیا، انھوں نے کہا: ہمیں ابو اسحاق الشیبانی نے بیان کیا کہ عامر بن شراحیل الشعبی فرمایا کرتے تھے: ظہر و عصر کی پہلی دو رکعات میں امام کے پیچھے سورۃ فاتحہ اور کوئی دوسری سورت، اور آخری دو رکعات میں سورۃ فاتحہ پڑھا کرو۔ (1)","",{"f":"§حواشی\n(1) صحیح۔ مصنف ابن ابی شیبہ: 270/3، حدیث، 3784۔ السنن الکبریٰ للبیہقی: 171/2۔"}],[224,"§امام شعبی رحمہ اللہ کا عمل:\nہمیں ابو سعید یحییٰ بن محمد الاسفرایینی الحاکم نے بیان کیا، انھوں نے کہا: ہمیں ابو بحر محمد بن حسن البربہاری نے بیان کیا، انھوں نے کہا: ہمیں بشر بن موسیٰ نے بیان کیا، انھوں نے کہا: ہمیں عبداللہ بن زبیر الحمیدی نے بیان کیا، انھوں نے کہا: ہمیں وکیع بن جراح نے بیان کیا، انھوں نے کہا: ہمیں مالک بن مغول نے بیان کیا، انھوں نے کہا: میں نے امام شعبی رحمہ اللہ کو امام کے پیچھے بہترین قرآت کرتے ہوئے سنا۔ (1)","",{"f":"§حواشی\n(1) (حسن) محمد بن حسن بربہاری ضعیف راوی ہے، البتہ یہ اثر صحیح ہے۔ مصنف ابن ابی شیبہ: 272/3، حدیث، 3794۔ السنن الکبریٰ للبیہقی: 172/2"}],[225,"§امام شعبی رحمہ اللہ کا فتویٰ:\nامام حمیدی رحمہ اللہ کہتے ہیں: ہمیں وکیع بن جراح نے بیان کیا، انھوں نے کہا: ہمیں اسماعیل بن ابی خالد نے بیان کیا کہ عامر بن شراحیل الشعبی نے کہا: پانچوں نمازوں میں قرآت کیا کرو۔ ان کا مطلب ’’تمام نمازیں‘‘ تھا۔ (1)\nاس روایت کو ابن خزیمہ رحمہ اللہ نے سلم بن جنادہ سے، انھوں نے وکیع بن جراح سے روایت کیا، انھوں نے فرمایا: امام کے پیچھے پانچوں نمازوں میں قرآت کرو۔ (2)","",{"f":"§حواشی\n(1) (حسن) اس سند میں ضعف ہے البتہ حدیث صحیح ہے۔ ابن ابی شیبہ نے صحیح سند کے ساتھ روایت کیا ہے۔ مصنف ابن ابی شیبہ: 265/3، حدیث، 3761۔ السنن الکبریٰ للبیہقی: 172/2\n(2) مصنف ابن ابی شیبہ: 267/3، حدیث، 3771۔ السنن الکبریٰ للبیہقی: 169/2۔"}],[226,"§عبیداللہ بن عبداللہ بن عتبہ، تابعی کا عمل:\nہمیں ابو نصر عمر بن عبدالعزیز بن عمر بن قتادہ نے بیان کیا، انھوں نے کہا: ہمیں محمد بن عبداللہ بن خمیرویہ العدل نے بیان کیا، انھوں نے کہا: ہمیں احمد بن نجدہ نے بیان کیا، انھوں نے کہا: ہمیں سعید بن منصور نے بیان کیا، انھوں نے کہا: ہمیں ہشیم بن بشیر نے بیان کیا، انھوں نے کہا: ہمیں حصین بن عبدالرحمن السلمی نے بیان کیا، انھوں نے کہا: میں نے عبیداللہ بن عبداللہ بن عتبہ (تابعی) کے پہلو میں (بالکل قریب کھڑے ہو کر) نماز پڑھی، میں نے آپ کو امام کے پیچھے قرآت کرتے سنا۔ میں مجاہد بن جبر (تابعی) سے ملا، میں نے ان کے سامنے ذکر کیا تو مجاہد نے فرمایا: میں نے سیدنا عبداللہ بن عمرو بن عاص رضی اللہ عنہ کو سنا، وہ ظہر کی نماز میں امام کے پیچھے سورت مریم کی قرآت کر رہے تھے۔ (1)\nمتعدد تابعین رحمہم اللہ کا موقف:\n(امام بیہقی رحمہ اللہ فرماتے ہیں) میں نے امام بخاری کی کتاب ’’القراءۃ خلف الامام‘‘ میں پڑھا ہے: حسن بصری، سعید بن جبیر، میمون بن مہران اور دیگر بے شمار تابعین و اہل علم کے متعلق مذکور ہے کہ وہ امام کے پیچھے قرآت کیا کرتے تھے، اگرچہ امام جہری قرآت ہی کر رہا ہوتا۔ (2)\nامام مجاہد (تابعی) رحمہ اللہ اور سیدنا عبداللہ بن زبیر رضی اللہ عنہ (صحابی) کا فتویٰ:\nامام بخاری رحمہ اللہ نے مزید فرمایا: امام مجاہد بن جبر رحمہ اللہ فرماتے ہیں: جب نمازی، امام کے پیچھے قرآت نہیں کرے گا تو اسے نماز دوبارہ ادا کرنا ہوگی۔ سیدنا عبداللہ بن زبیر رضی اللہ عنہ نے بھی اسی طرح فرمایا ہے۔ (3)","",{"f":"§حواشی\n(1) صحیح۔\n(2) جزء القراءۃ خلف الامام، للبخاری: ص، 33، حدیث، 36۔\n(3) جزء القراءۃ خلف الامام، للبخاری: ص، 34، حدیث، 39، 40۔"}],[227,"§امام مکحول شامی (تابعی) رحمہ اللہ کا عمل:\nہمیں ابوعبداللہ الحافظ (امام حاکم) اور ابومحمد عبدالرحمن بن ابی حامد المقرئی نے بیان کیا، انھوں نے کہا: ہمیں ابوعباس محمد بن یعقوب نے بیان کیا، انھوں نے کہا: ہمیں عباس بن ولید بیروتی نے بیان کیا، انھوں نے کہا: ہمیں عقبہ بن علقمہ نے بیان کیا، انھوں نے کہا: مجھے موسیٰ بن یسار نے بیان کیا، انھوں نے کہا: میں نے امام مکحول کو امام کے پیچھے سورۃ فاتحہ پڑھتے سنا ہے، حالانکہ امام بھی قرآت کر رہا تھا۔ (1)","",{"f":"§حواشی\n(1) حسن۔ مصنف عبدالرزاق: 139/2، حدیث، 2769۔ محمد بن راشد کہتے ہیں کہ امام مکحول جہری و سری، دونوں طرح کی نمازوں میں سورت فاتحہ پڑھا کرتے تھے۔"}],[228,"§امام اوزاعی رحمہ اللہ کا فتویٰ:\nہمیں ابوعبداللہ الحافظ (امام حاکم) نے بیان کیا، انھوں نے کہا: ہمیں ابوعباس محمد بن یعقوب نے بیان کیا، انھوں نے کہا: ہمیں عباس بن ولید بن مزید نے بیان کیا، انھوں نے کہا: مجھے میرے والد محترم ولید بن مزید نے بیان کیا، انھوں نے کہا: امام اوزاعی فرمایا کرتے تھے: امام کے لیے ضروری ہے کہ وہ ایک سکتہ؛ نماز کے آغاز میں تکبیر اولیٰ کے بعد کرے، اور ایک سکتہ سورۃ فاتحہ پڑھنے کے بعد کرے۔ تاکہ جو لوگ اس کے پیچھے ہیں، وہ سورۃ فاتحہ پڑھ سکیں۔ اگر ایسا ممکن نہ ہو تو جب امام سورۃ فاتحہ پڑھے تو (مقتدی) اس کے ساتھ ہی سورۃ فاتحہ پڑھ لے۔ اور جلدی پڑھ لے، پھر (باقی قرآت) غور سے سنے۔ (1)","",{"f":"§حواشی\n(1) یہ روایت صحیح ہے۔"}],[229,"§فصل ۱: امام شافعی رحمہ اللہ کا قدیم قول\nوَهُوَ أَحَدُ قَوْلَىْ أَبِي عَبْدِ اللهِ مُحَمَّدِ بْنِ إِدْرِيسَ الشَّافِعِيِّ الْمُطَّلِبِيِّ رَحِمَهُ اللهُ، وَفِيهِ ...... إِنْ صَحَّ وَجْهُ الْاِحْتِجَاجِ بِمَا وَرَدَ فِيهِ ...... تَثْبِيتُ الْقِرَاءَةِ فِي الظُّهْرِ وَالْعَصْرِ، وَفِي الرَّكْعَةِ الْآخِرَةِ وَالرَّكْعَتَيْنِ الْأُخْرَيَيْنِ مِنَ الْعِشَاءِ عَلَى الْمَأْمُومِ، خِلَافَ مَا ذَهَبَ إِلَيْهِ بَعْضُ الْعِرَاقِيِّينَ، قَالَ اللهُ تَبَارَكَ وَتَعَالَى: ﴿وَإِذَا قُرِئَ الْقُرْآنُ فَاسْتَمِعُوا لَهُ وَأَنْصِتُوا لَعَلَّكُمْ تُرْحَمُونَ﴾ [الأعراف: 204]\nامام ابوعبداللہ محمد بن ادریس الشافعی رحمہ اللہ کے دو اقوال میں سے ایک یہ ہے (کہ سرّی نماز میں امام کے پیچھے قرآت واجب ہے اور جہری نماز میں واجب نہیں)۔ اگر ان کے دلائل سے ایسا استدلال صحیح بھی ہو تو اس سے ظہر و عصر (کی چاروں رکعات) اور (مغرب کی) آخری رکعت اور عشاء کی آخری دو رکعات میں مقتدی کا قرآت کرنا ثابت ہوتا ہے ...... جو بعض عراقی (یعنی احناف بھائیوں) کے موقف کے برعکس ہے۔ (ان دلائل میں سے اولیٰ دلیل) اللہ تعالیٰ کا فرمان ہے: ’’جب قرآن پڑھا جائے تو اسے توجہ سے سنو، اور خاموش رہو، تاکہ تم پر رحم کیا جائے۔‘‘ [الأعراف: 204]\n§جہری نماز میں مقتدی کو قرآت سے منع کرنے کے دلائل اور ان کا جائزہ:\n(امام شافعی رحمہ اللہ کا قول یہ تھا کہ جہری نماز میں مقتدی قرآت نہیں کرے گا، البتہ سرّی نماز میں قرآت کرے گا۔ اس باب میں ان دلائل کا جائزہ لیا جائے گا، جن کے تحت مقتدی کو جہری نماز میں قرآت سے ممانعت کا استدلال، کیا گیا۔ [العاصم])\n§پہلی دلیل (بروایت، امام مجاہد تابعی رحمہ اللہ):\nہمیں ابوعبداللہ محمد بن عبداللہ الحافظ نے بیان کیا، انھوں نے کہا: ہمیں عبدالرحمن بن حسن القاضی نے بیان کیا، انھوں نے کہا: ہمیں ابراہیم بن حسین نے بیان کیا، انھوں نے کہا: ہمیں آدم بن ابی ایاس نے بیان کیا، انھوں نے کہا: ہمیں ورقاء بن عمر الیشکری نے بیان کیا، انھوں نے عبداللہ بن ابی نجیح سے، انھوں نے مجاہد بن جبر (تابعی) سے روایت کیا، انھوں نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم نماز میں قرآت کر رہے تھے کہ آپ صلی اللہ علیہ وسلم نے ایک انصاری نوجوان کی قرآت سنی۔ تب یہ آیت نازل ہوئی: ’’جب قرآن پڑھا جائے تو اسے توجہ سے سنو اور خاموش رہو، تاکہ تم پر رحم کیا جائے۔‘‘ [الأعراف: 204] (1)\nاس روایت کے راوی کا موقف:\nجبکہ (اس روایت کے راوی) امام مجاہد بن جبر رحمہ اللہ (قرآن کی قرآت کے دوران) ذکر کرنے میں کوئی حرج نہیں سمجھتے تھے۔ (2)\nیہ روایت مرسل ہے:\nیہ روایت (حدیث نمبر: 228) منقطع ہے۔ (امام بیہقی رحمہ اللہ مرسل کو منقطع کہہ دیتے ہیں، یہاں بھی منقطع سے مراد، مرسل ہی ہے۔) (3)","",{"f":"§حواشی\n(1) اسنادہ ضعیف۔ عبدالرحمن بن حسن القاضی ضعیف راوی ہے۔ عبداللہ بن ابی نجیح مدلس راوی ہے، اور اس نے یہ روایت ’’عن‘‘ کے صیغہ کے ساتھ روایت کی ہے۔\n(2) تفسیر ابن ابی حاتم: 1646/5۔ تفسیر مجاہد بن جبر: 155/2۔ السنن الکبریٰ للبیہقی: 155/2۔\n(3) ایک طرف امام مجاہد رحمہ اللہ یہ روایت بیان کریں کہ قرآن کی قرآت کے وقت خاموشی اختیار کرو۔ اور دوسری طرف خود قرآت قرآن کے دوران ذکر کرنے کو جائز سمجھتے ہوں تو کس بات کا اعتبار کیا جائے گا؟ حقیقت یہی ہے کہ امام مجاہد، جو کہ مفسر قرآن بھی ہیں، وہ اپنی بیان کردہ روایت کے مفہوم کو زیادہ جانتے اور سمجھتے تھے، اسی لیے انھوں نے قرآت کے دوران ذکر کرنے کو جائز سمجھا، کہ ان کے ہاں روایت میں مذکور قرآنی آیت میں جس انصات کا حکم ہے، اس سے مراد یہ ہے کہ زبان بالکل بند نہ ہو، بلکہ زبان حرکت کر رہی ہو؛ کچھ پڑھ رہی ہو البتہ آواز بلند نہ ہو۔"}],[230,"§دوسری دلیل (بروایت، ابوالعالیہ تابعی رحمہ اللہ):\nہمیں ابوعبداللہ الحافظ نے بیان کیا، انھوں نے کہا: ہمیں ابوعلی حسین بن علی الحافظ نے بیان کیا، انھوں نے کہا: ہمیں ابویعلیٰ الموصلی نے بیان کیا، انھوں نے کہا: ہمیں محمد بن ابی بکر المقدمی نے بیان کیا، انھوں نے کہا: ہمیں عبدالوہاب بن عبدالمجید ثقفی نے بیان کیا، انھوں نے مہاجر بن مخلد سے، انھوں نے ابوالعالیہ رفیع بن مہران الریاحی (1) سے روایت کیا، انھوں نے فرمایا: نبی کریم صلی اللہ علیہ وسلم جب نماز پڑھتے تو قرآت کیا کرتے تھے۔ آپ صلی اللہ علیہ وسلم کے اصحاب رضی اللہ عنہم بھی قرآت کرنے لگے، تو یہ آیت مبارکہ نازل ہوئی: ’’جب قرآن پڑھا جائے تو اسے توجہ سے سنو، اور خاموش رہو، تاکہ تم پر رحم کیا جائے۔‘‘ پھر لوگ خاموش رہتے اور نبی کریم صلی اللہ علیہ وسلم قرآت کرتے تھے۔ (2)\nیہ روایت مرسل ہے:\nیہ روایت بھی منقطع ہے۔ (یہاں منقطع سے مراد مرسل ہے)","",{"f":"§حواشی\n(1) ابوالعالیہ رفیع بن مہران الریاحی رحمہ اللہ بلند پایہ تابعی ہیں۔ انھوں نے دور جاہلیت بھی پایا البتہ مسلمان ہونے کی سعادت، رسول اللہ صلی اللہ علیہ وسلم کی وفات کے دو سال بعد نصیب ہوئی۔ ابن ابی داؤد کہتے ہیں: صحابہ کرام رضی اللہ عنہم کے بعد ابوالعالیہ سے بڑھ کر قرآن کا کوئی عالم نہیں۔ سیدنا علی رضی اللہ عنہ سے احادیث مبارکہ سننے کی سعادت حاصل کی۔ ان کی وفات 94 ہجری میں ہوئی۔\n(2) یہ سند ضعیف ہے۔ الاعتبار في الناسخ والمنسوخ من الآثار، للحازمي: ص، 98۔"}],[231,"§تیسری دلیل (بروایت، سیدنا عبداللہ بن مغفل رضی اللہ عنہ):\nہمیں ابو عبداللہ الحافظ نے بیان کیا، انھوں نے کہا: ہمیں ابو علی الحافظ نے بیان کیا، انھوں نے کہا: ہمیں محمد بن علی بن حسن بن حرب الرقی نے بیان کیا، انھوں نے کہا: ہمیں محمد بن عمرو بن عباس نے بیان کیا، انھوں نے کہا: ہمیں زکریا بن یحییٰ بن عمارہ الذارع الانصاری نے بیان کیا، انھوں نے کہا: ہمیں ہشام بن زیاد نے بیان کیا، انھوں نے حسن بصری سے، انھوں نے سیدنا عبداللہ بن مغفل رضی اللہ عنہ سے اس آیت مبارکہ ﴿وَإِذَا قُرِئَ الْقُرْآنُ فَاسْتَمِعُوا لَهُ وَأَنْصِتُوا﴾ کے متعلق روایت کیا کہ انھوں نے فرمایا: (یہ آیت) نماز کے بارے میں ہے۔ (1)\nتیسری دلیل، دوسری سند کے ساتھ:\n(امام بیہقی رحمہ اللہ فرماتے ہیں:) اس حدیث کا مدار و انحصار ہشام بن زیاد ابوالمقدام پر ہے۔ اپنی اسناد میں یہ مختلف فیہ راوی ہے۔ قوی (معتبر) نہیں ہے۔ اس سے ابو اسامہ نے بھی یہ روایت نقل کی ہے۔ [جو حسب ذیل ہے:]","",{"f":"§حواشی\n(1) یہ سند ضعیف ہے۔ ہشام بن زیاد متروک راوی ہے۔ تفسير ابن أبي حاتم: 1646/5 - الكنى والأسماء، للدولابي: 1056/3۔"}],[232,"ہمیں ابو عبداللہ الحافظ (امام حاکم) اور ابو بکر احمد بن حسن القاضی نے بیان کیا ہے، ان دونوں نے کہا: ہمیں ابو عباس محمد بن یعقوب نے بیان کیا، انھوں نے کہا: ہمیں حسن بن علی بن عفان نے بیان کیا، انھوں نے کہا: ہمیں ابو اسامہ حماد بن اسامہ القرشی نے بیان کیا، انھوں نے کہا: مجھے ابوالمقدام ہشام بن زیاد نے بیان کیا، انھوں نے معاویہ بن قرہ المزنی سے روایت کیا، انھوں نے کہا: میں نے رسول اللہ صلی اللہ علیہ وسلم کے اصحاب میں سے کسی بزرگ سے پوچھا، ابوالمقدام ہشام بن زیاد کہتے ہیں: میرا خیال ہے کہ معاویہ بن قرہ نے سیدنا عبداللہ بن مغفل رضی اللہ عنہ کا نام لیا تھا۔ البتہ وہ کہتے ہیں کہ میں نے ان (صحابی) سے پوچھا: کیا قرآن کی قرآت (تلاوت) سننے والے ہر شخص پر استماع و امساک (غور سے سننا اور خود قرآت نہ کرنا) واجب ہے؟ انھوں نے فرمایا: یہ آیت مبارکہ ﴿وَإِذَا قُرِئَ الْقُرْآنُ فَاسْتَمِعُوا لَهُ وَأَنْصِتُوا لَعَلَّكُمْ تُرْحَمُونَ﴾ امام کی قرآت کے بارے میں ہے۔ جب امام قرآت کرے تب تم غور سے سنو اور خاموش رہو۔ (1)\nتیسری دلیل، تیسری سند کے ساتھ:\nاس روایت کو کثیر بن ہشام نے بھی بیان کیا ہے۔ [جو حسب ذیل ہے:]","",{"f":"§حواشی\n(1) شدید ضعیف سند ہے۔ ابوالمقدام ہشام بن زیاد متروک راوی ہے۔ تفسير ابن أبي حاتم: 1646/5 - الكنى والأسماء، للدولابي: 1056/3۔"}],[233,"ہمیں احمد بن حسن بن احمد الحیری نے بیان کیا ہے، انھوں نے کہا: ہمیں ابو عباس اموی نے بیان کیا، انھوں نے کہا: ہمیں یحییٰ بن ابی طالب نے بیان کیا، انھوں نے کہا: ہمیں کثیر بن ہشام نے بیان کیا، انھوں نے کہا: ہمیں ہشام بن زیاد ابو مقدام نے بیان کیا، انھوں نے معاویہ بن قرہ سے روایت کیا، انھوں نے کہا: ہم نے سیدنا عبداللہ بن مغفل رضی اللہ عنہ یا سیدنا عائذ بن عمرو المزنی رضی اللہ عنہ سے پوچھا: کیا قرآن کی قرآت سننے والے ہر شخص پر استماع و انصات (غور سے سننا اور خاموش رہنا) واجب ہے؟ انھوں نے فرمایا: یہ آیت مبارکہ ﴿وَإِذَا قُرِئَ الْقُرْآنُ فَاسْتَمِعُوا لَهُ وَأَنْصِتُوا﴾ امام کی قرآت کے بارے میں ہے۔ لہذا جب امام قرآت کرے؛ تب تم توجہ سے سنو اور خاموش رہو۔ (1)","",{"f":"§حواشی\n(1) ہشام بن زیاد متروک راوی ہے۔ یہ سند ضعیف ہے۔"}],[234,"§چوتھی دلیل (بروایت، سیدنا عبداللہ بن عباس رضی اللہ عنہ):\nہمیں ابو حسین علی بن محمد بن عبداللہ بن بشران نے بغداد میں بیان کیا، انھوں نے کہا: ہمیں ابو جعفر محمد بن عمرو الرزاز نے بیان کیا، انھوں نے کہا: ہمیں سعدان بن نصر نے بیان کیا، انھوں نے کہا: ہمیں مسکین بن بکیر الحرانی نے بیان کیا، انھوں نے ثابت بن عجلان سے، انھوں نے سعید بن جبیر سے، انھوں نے سیدنا عبداللہ بن عباس رضی اللہ عنہ سے روایت کیا، انھوں نے فرمایا: مومن کو استماع (یعنی قرآت بغور سننے) میں اختیار و وسعت حاصل ہے۔ (یعنی چاہے تو غور سے سنے یا نہ سنے)۔ ماسوائے فرض نماز یا نماز جمعہ، یا نماز عید الفطر یا نماز عید الاضحی کے۔ یعنی (ان میں) ﴿وَإِذَا قُرِئَ الْقُرْآنُ فَاسْتَمِعُوا لَهُ وَأَنْصِتُوا﴾ کے مطابق استماع کرے گا۔ (1)","",{"f":"§حواشی\n(1) حسن - تفسير ابن أبي حاتم: 1646/5 - السنن الكبرى للبيهقي: 155/2۔"}],[235,"§پانچویں دلیل (بروایت عبداللہ بن عباس رضی اللہ عنہ):\nہمیں ابو زکریا بن ابی اسحاق المزکی نے بیان کیا، انھوں نے کہا: ہمیں ابو الحسن احمد بن محمد بن عبدوس نے بیان کیا، انھوں نے کہا: ہمیں عثمان بن سعید الدارمی نے بیان کیا، انھوں نے کہا: ہمیں عبداللہ بن صالح بن مسلم نے بیان کیا، انھوں نے کہا: مجھے معاویہ بن صالح نے بیان کیا، انھوں نے علی بن ابی طلحہ الہاشمی سے، انھوں نے سیدنا عبداللہ بن عباس رضی اللہ عنہ سے اللہ تعالیٰ کے فرمان: ﴿وَإِذَا قُرِئَ الْقُرْآنُ فَاسْتَمِعُوا لَهُ وَأَنْصِتُوا﴾ کے بارے میں روایت کیا کہ انھوں نے فرمایا: یہ فرض نماز کے بارے میں ہے۔ (1)","",{"f":"§حواشی\n(1) حسن لغیرہ۔ علی بن ابی طلحہ نے سیدنا ابن عباس سے ارسال کیا ہے، البتہ اس اثر کے شواہد موجود ہیں۔ تفسير الطبري: 349/13 - الأوسط، لابن المنذر: 105/3، حديث، 1317 - علی بن ابی طلحہ نے سیدنا ابن عباس رضی اللہ عنہ سے کچھ بھی نہیں سنا۔ [الجرح والتعديل: 188/6۔"}],[236,"§چھٹی دلیل (بروایت، عبداللہ بن عباس رضی اللہ عنہ):\nہمیں ابو الحسن علی بن احمد بن عبدان نے بیان کیا، انھوں نے کہا: ہمیں احمد بن عبید الصفار نے بیان کیا، انھوں نے کہا: ہمیں عبید بن شریک البغدادی نے بیان کیا، انھوں نے کہا: ہمیں ابن ابی مریم (سعید بن حکم) نے بیان کیا، انھوں نے کہا: ہمیں عبداللہ بن لہیعہ المصری نے بیان کیا، انھوں نے عبداللہ بن ہبیرہ سے، انھوں نے سیدنا عبداللہ بن عباس رضی اللہ عنہ سے روایت کیا کہ رسول اللہ صلی اللہ علیہ وسلم نے نماز میں قرآت کی تو آپ صلی اللہ علیہ وسلم کے اصحاب رضی اللہ عنہم نے بھی قرآت کی۔ صحابہ کی آواز آپ صلی اللہ علیہ وسلم کی آواز سے ٹکرانے لگ گئی۔ تب یہ آیت نازل ہوئی: ﴿وَإِذَا قُرِئَ الْقُرْآنُ فَاسْتَمِعُوا لَهُ وَأَنْصِتُوا﴾ لہذا یہ آیت فرض نماز کے بارے میں ہے۔ پھر سیدنا عبداللہ بن عباس رضی اللہ عنہ نے فرمایا: اگر ہم قرآت (تلاوت) کرنے والے کو بغور نہیں سنتے تو ہم گدھوں سے بھی کم تر ہیں۔ (1)\nیہ سند ضعیف ہے:\nامام بیہقی رحمہ اللہ فرماتے ہیں: اس سند میں ضعف ہے۔ (2)","",{"f":"§حواشی\n(1) یہ سند حسن لغیرہ ہے۔ البتہ اس روایت کے شواہد موجود ہیں۔ تفسير الطبري: 350/13 - الاعتبار في الناسخ والمنسوخ من الآثار، للحازمي ص 98۔\n(2) ابن لہیعہ سیئ الحفظ راوی ہے بلکہ اس پر مستزاد یہ کہ وہ اختلاط کا شکار ہو گیا تھا۔ یہ فرق ممکن نہیں کہ کس راوی نے اس سے اختلاط سے پہلے روایت لی تھی اور نے اختلاط کے بعد۔"}],[237,"§ساتویں دلیل (بروایت، سیدنا عبداللہ بن عباس رضی اللہ عنہ):\nہمیں ابو علی حسین بن محمد الروذباری نے بیان کیا، انھوں نے کہا: ہمیں ابو طاہر المحمداباذی (1) نے بیان کیا، انھوں نے کہا: ہمیں فضل بن عبداللہ الیشکری نے ہراۃ (شہر) (2) میں بیان کیا، انھوں نے کہا: ہمیں مالک بن سلیمان نے بیان کیا، انھوں نے کہا: ہمیں داؤد بن عبدالرحمن المکی نے بیان کیا، انھوں نے ابن جریج (عبدالملک بن عبدالعزیز) اموی سے، انھوں نے عطاء بن ابی رباح سے روایت کیا، انھوں نے کہا: میں نے سیدنا عبداللہ بن عباس رضی اللہ عنہ سے اللہ تعالیٰ کے فرمان: ﴿وَإِذَا قُرِئَ الْقُرْآنُ فَاسْتَمِعُوا لَهُ وَأَنْصِتُوا﴾ کے بارے میں پوچھا، کہ کیا یہ قرآن پڑھنے والے ہر شخص کے بارے میں ہے؟ تو انھوں نے فرمایا: نہیں، بلکہ یہ نماز کے بارے میں ہے۔ (3)\nیہ سند نا قابل حجت ہے:\nیہاں سیدنا عبداللہ بن عباس رضی اللہ عنہ کا قول بیان کیا گیا ہے۔ جبکہ درست یہ ہے کہ ابن جریج نے عطاء بن ابی رباح سے روایت کیا ہے۔ (ابن عباس رضی اللہ عنہ کا نام ذکر کرنا درست نہیں کیونکہ) اس قول کی سند سیدنا عبداللہ بن عباس رضی اللہ عنہ تک نہیں پہنچتی۔","",{"f":"§حواشی\n(1) محمداباذ، (خراسان میں) نیساپور سے ایک فرسخ (تقریباً آٹھ کلومیٹر) کے فاصلے پر ایک گاؤں کا نام ہے۔ [المعجم البلدان، للحموي: 64/5]\n(2) ہراۃ، خراسان کے بڑے شہروں میں سے ایک شہر ہے۔ [المعجم البلدان، للحموي: 396/5]\n(3) حسن لغیرہ۔ السنن الكبرى، للبيهقي: 155/2 - امام بیہقی رحمہ اللہ نے اس روایت کو معلول قرار دیا ہے۔"}],[238,"§آٹھویں دلیل (بروایت، سیدنا عبداللہ بن مسعود رضی اللہ عنہ):\nہمیں ابو الحسن محمد بن حسین بن داؤد العلوی نے بیان کیا، انھوں نے کہا: ہمیں ابو الحسن علی بن محمد بن حمشاذ العدل نے بیان کیا، انھوں نے کہا: مجھے محمد بن حسین انماطی بغدادی نے بیان کیا، انھوں نے کہا: ہمیں یحییٰ بن ایوب المقابری نے بیان کیا، کیا، انھوں نے کہا: عبدالوہاب بن عبدالمجید ثقفی نے بیان کیا، انھوں نے کہا: ہمیں ایوب سختیانی نے بیان کیا، انھوں نے منصور بن معتمر سلمی کے واسطے سے روایت کیا، عبدالوہاب کہتے ہیں: پھر میں منصور بن معتمر سے ملا تو انھوں نے مجھے ابو وائل (شقیق بن سلمہ الکوفی، مخضرم) کے واسطے سے بیان کیا کہ سیدنا عبداللہ بن مسعود رضی اللہ عنہ نے امام کے پیچھے قرآت کرنے کے بارے میں فرمایا: قرآن کے لیے خاموشی اختیار کرو، جیسا کہ حکم ہوا ہے۔ کیونکہ قرآت ایک ایسا عمل ہے جس میں امام ہی کافی ہے۔ (1)","",{"f":"§حواشی\n(1) یہ سند حسن درجہ کی ہے، البتہ یہ اثر صحیح ہے۔ موطأ مالك: (بروایت محمد بن حسن، المعروف: موطأ امام محمد): حدیث، 122 - مصنف عبدالرزاق: 138/2، حدیث، 2803 - المعجم الكبير، للطبراني: 664/9، حدیث، 9311 - مصنف ابن أبي شيبة: 278/3، حدیث، 3801 - الأوسط، لابن المنذر: 87/8 - شرح معانی الآثار، للطحاوي: 219/1۔"}],[239,"§نویں دلیل (بروایت، سیدنا عبداللہ بن مسعود رضی اللہ عنہ):\nہمیں ابو عبداللہ الحافظ (امام حاکم) نے بیان کیا، انھوں نے کہا: ہمیں ابو علی حسین بن علی الحافظ نے بیان کیا، انھوں نے کہا: ہمیں ابو یعلی الموصلی نے بیان کیا، انھوں نے کہا: ہمیں محمد بن ابی بکر المقدمی نے بیان کیا، انھوں نے کہا: ہمیں عبدالاعلیٰ السامی البصری نے بیان کیا، انھوں نے داؤد بن ابی ہند القشیری سے، انھوں نے ابو نضرہ منذر بن مالک العبدی سے، انھوں نے ایک شخص سے روایت کیا کہ سیدنا عبداللہ بن مسعود رضی اللہ عنہ نے اپنے ساتھیوں کو نماز پڑھائی؛ لوگوں نے آپ کے پیچھے قرآت کی۔ جب آپ رضی اللہ عنہ نماز سے فارغ ہوئے تو فرمایا: کیا ابھی تک تم سمجھ نہیں سکے: ﴿وَإِذَا قُرِئَ الْقُرْآنُ فَاسْتَمِعُوا لَهُ وَأَنْصِتُوا﴾ یعنی: جب قرآن پڑھا جائے تو توجہ سے سنو اور خاموش رہو۔ (1)","",{"f":"§حواشی\n(1) صحیح۔ اس سند میں سیدنا عبداللہ بن مسعود رضی اللہ عنہ سے روایت کرنے والے کا نام واضح نہیں ہے۔ البتہ امام طبری نے تصریح کے ساتھ اس راوی کا نام بشیر بن جابر بیان کیا ہے۔ تفسير الطبري: [346/13 اور ابن ابی حاتم نے اپنی تفسیر میں اس راوی کا نام اسیر بن جابر المحاربی بیان کیا ہے۔ طبری اور ابن ابی حاتم کے بیان کردہ ناموں میں فرق اس لیے ہے کہ اس راوی کے نام میں ہی اختلاف پایا جاتا ہے۔"}],[240,"§دسویں دلیل (بروایت، محمد بن کعب القرظی تابعی رحمہ اللہ):\nہمیں ابو نصر عمر بن عبدالعزیز بن عمر بن قتادہ نے بیان کیا، انھوں نے کہا: ہمیں ابو منصور عباس بن فضل النضروی نے بیان کیا، انھوں نے کہا: ہمیں احمد بن نجدہ نے بیان کیا، انھوں نے کہا: ہمیں سعید بن منصور نے بیان کیا، انھوں نے کہا: ہمیں ابو معشر نجیح بن عبدالرحمن السندی نے بیان کیا، انھوں نے محمد بن کعب القرظی (تابعی) سے روایت کیا، انھوں نے فرمایا: لوگ رسول اللہ صلی اللہ علیہ وسلم سے سن کر قرآن یاد کیا کرتے تھے۔ لہذا جب آپ صلی اللہ علیہ وسلم پڑھتے تب لوگ بھی آپ کے ساتھ پڑھتے۔ حتیٰ کہ آیت نازل ہوگئی، جو سورۃ اعراف میں ہے: ﴿وَإِذَا قُرِئَ الْقُرْآنُ فَاسْتَمِعُوا لَهُ وَأَنْصِتُوا﴾ (جب قرآن پڑھا جائے تو غور سے سنو اور خاموشی اختیار کرو) (1)","",{"f":"§حواشی\n(1) مرسل ہونے کی وجہ سے یہ سند ضعیف ہے۔ تفسير ابن أبي حاتم: 1645/5 - تفسير سعيد بن منصور: 181/5، حديث، 978۔"}],[241,"§گیارھویں دلیل (بروایت، مجاہد بن جبر تابعی رحمہ اللہ):\nہمیں ابو عبداللہ الحافظ (امام حاکم) نے بیان کیا، انھوں نے کہا: ہمیں ابو علی حسین بن علی الحافظ نے بیان کیا، انھوں نے کہا: ہمیں ابو یعلی الموصلی نے بیان کیا، انھوں نے کہا: ہمیں محمد بن ابی بکر المقدمی نے بیان کیا، انھوں نے کہا: ہمیں یحییٰ بن سعید القطان نے بیان کیا، انھوں نے سفیان ثوری سے روایت کیا، انھوں نے کہا: مجھے ابو ہاشم اسماعیل بن کثیر المکی الحجازی نے بیان کیا، انھوں نے مجاہد بن جبر (تابعی) سے ﴿وَإِذَا قُرِئَ الْقُرْآنُ فَاسْتَمِعُوا لَهُ﴾ کے بارے میں روایت کیا، کہ انھوں نے فرمایا: یہ نماز کے بارے میں ہے۔ (1)","",{"f":"§حواشی\n(1) اسنادہ صحیح۔ مصنف عبدالرزاق: 453/2، حدیث، 4056 - تفسير الطبري: 347/13، حدیث، 15587۔"}],[242,"§بارھویں دلیل (بروایت، مجاہد بن جبر تابعی رحمہ اللہ):\nاسی سند کے ساتھ مذکور ہے کہ ابو یعلی الموصلی نے کہا: ہمیں محمد بن ابی بکر المقدمی نے بیان کیا، انھوں نے کہا: ہمیں اشعث بن عبداللہ نے بیان کیا، انھوں نے کہا: ہمیں شعبہ بن حجاج نے بیان کیا، انھوں نے حمید بن قیس الاعرج سے، انھوں نے مجاہد بن جبر سے روایت کیا کہ انھوں نے ﴿فَاسْتَمِعُوا لَهُ وَأَنْصِتُوا﴾ کے بارے میں فرمایا: یہ نماز کے بارے میں ہے۔ (1)","",{"f":"§حواشی\n(1) اسنادہ صحیح - تفسير الطبري: 347/13۔"}],[243,"§تیرھویں دلیل (بروایت، مجاہد بن جبر تابعی رحمہ اللہ):\nاسی سند کے ساتھ مذکور ہے کہ ابو یعلی موصلی نے کہا: ہمیں محمد بن ابی بکر المقدمی نے بیان کیا، انھوں نے کہا: ہمیں (سفیان بن عیینہ کے بھائی) عمران بن عیینہ نے بیان کیا، انھوں نے لیث بن ابی سلیم سے روایت کیا کہ مجاہد بن جبر نے فرمایا: یہ آیت فرض نماز کے بارے میں ہے۔ (1)","",{"f":"§حواشی\n(1) یہ سند حسن لغیرہ ہے۔ البتہ سابقہ اثر اس کا شاہد ہے۔ مصنف ابن أبي شيبة: 448/5، حديث، 8469 - تفسير الطبري: 347/13۔"}],[244,"§چودھویں دلیل (بروایت، مجاہد بن جبر تابعی رحمہ اللہ):\nہمیں ابو عبداللہ الحافظ (امام حاکم) نے بیان کیا، انھوں نے کہا: ہمیں ابو علی الحافظ نے بیان کیا، انھوں نے کہا: ہمیں ابو یعلی الموصلی نے بیان کیا، انھوں نے کہا: ہمیں محمد بن ابی بکر المقدمی نے بیان کیا، انھوں نے کہا: ہمیں اشعث بن عبداللہ نے بیان کیا، انھوں نے کہا: ہمیں شعبہ بن حجاج نے بیان کیا، انھوں نے منصور بن معتمر اسلمی الکوفی سے، انھوں نے ابراہیم بن ابی حرہ النصیبی سے روایت کیا کہ مجاہد بن جبر نے فرمایا: ﴿فَاسْتَمِعُوا لَهُ وَأَنْصِتُوا﴾ نماز اور خطبہ (جمعہ) کے لیے ہے۔ (1)\nامام بیہقی رحمہ اللہ کا تبصرہ:\nامام بیہقی رحمہ اللہ فرماتے ہیں: میں نے یہ قول اسی طرح سنا ہے۔ اور اسی طرح ہی تفسیر روح بن عبادہ میں دیکھا ہے کہ شعبہ بن حجاج کہتے ہیں: میں نے منصور بن معتمر کو سنا؛ وہ ابراہیم بن ابی حرہ کے واسطے سے بیان کر رہے تھے کہ مجاہد بن جبر نے فرمایا: یہ آیت نماز اور خطبہ کے لیے ہے۔ [اسی روایت کی اسناد حسب ذیل ہیں:]","",{"f":"§حواشی\n(1) اسنادہ صحیح۔ مصنف ابن أبي شيبة: 448/5، حديث، 8468 - تفسير سعيد بن منصور: 180/5، حديث، 977 - تفسير الطبري: 351/13۔"}],[245,"(پہلی سند) یہ روایت ہمیں امام ابو عثمان نے بیان کی، انھوں نے کہا: ہمیں ابو بکر الشیبانی اور ابو صالح البیہقی نے بیان کیا، ان دونوں نے کہا: ہمیں مکی بن عبدان نے بیان کیا، انھوں نے کہا: ہمیں ابو الازہر احمد بن ازہر العبدی نے بیان کیا، انھوں نے کہا: ہمیں روح بن عبادہ نے بیان کیا..... (ح)\nقَالَ: وَأنا أَبُو طَاهِرِ بْنِ خُزَيْمَةَ، أنا جَدِّي، نا مُحَمَّدُ بْنُ مَعْمَرٍ، نا رَوْحٌ، نا شُعْبَةُ، فَذَكَرَهُ،\n(دوسری سند) ابو عثمان نے کہا: ہمیں ابو طاہر بن خزیمہ نے بیان کیا، انھوں نے کہا: ہمیں میرے دادا جان محمد بن اسحاق بن خزیمہ (معروف امام ابن خزیمہ) نے بیان کیا، انھوں نے کہا: ہمیں محمد بن معمر بن ربعی القیسی نے بیان کیا، انھوں نے کہا: ہمیں روح بن عبادہ نے بیان کیا، انھوں نے کہا: ہمیں شعبہ بن حجاج نے بیان کیا، انھوں نے یہی روایت بیان کی۔ (1)\nپندرھویں دلیل:\nاسی طرح روح بن عبادہ کے علاوہ دیگر راویوں کی شعبہ بن حجاج سے بیان کردہ روایت میں اسی طرح مذکور ہے۔","",{"f":"§حواشی\n(1) یہ سند حسن ہے۔ البتہ اثر صحیح ہے۔"}],[246,"ہمیں ابو نصر بن قتادہ نے بیان کیا، انھوں نے کہا: ہمیں ابو منصور النضروی عباس بن فضل نے بیان کیا، انھوں نے کہا: ہمیں احمد بن نجدہ نے بیان کیا، انھوں نے کہا: ہمیں سعید بن منصور نے بیان کیا، انھوں نے کہا: ہمیں عبدالرحمن بن زیاد نے بیان کیا، انھوں نے شعبہ بن حجاج سے، انھوں نے منصور بن معتمر سے، انھوں نے ابراہیم (نخعی) اور ابراہیم بن ابی حرہ سے روایت کیا، ان دونوں نے مجاہد بن جبر سے روایت کیا کہ انھوں نے فرمایا یہ آیت نماز اور خطبہ کے بارے میں ہے۔ (1)\nسعید بن منصور نے اپنی تفسیر میں اسی طرح بیان کیا ہے۔ البتہ منصور بن معتمر کا بھی مجاہد بن جبر سے سماع درست ہے۔ (2) اور شعبہ بن حجاج کا ابراہیم بن ابی حرہ سے سماع درست ہے۔ (3) ممکن ہے کہ یہ سند اسی طرح ہی ہو، جس طرح سعید بن منصور کی روایت میں ہے۔ واللہ اعلم۔","",{"f":"§حواشی\n(1) صحیح۔\n(2) تفسير سعيد بن منصور: 181,180/5، حديث، 977۔\n(3) امام بیہقی رحمہ اللہ کا اس بات سے مقصد یہ ہے کہ جب منصور بن معتمر کا مجاہد بن جبر سے سماع صحیح و ثابت ہے تو پھر منصور، مجاہد سے روایت؛ بالواسطہ کیوں کریں گے؟ اور شعبہ بن حجاج کا ابراہیم بن ابی حرہ سے سماع صحیح و ثابت ہے تو شعبہ، ابراہیم سے روایت؛ بالواسطہ کیوں کریں گے؟ ان دو اسباب کی وجہ سے یہ روایت (نمبر: 243) معلول قرار پاتی ہے۔ اور صحیح روایت وہ ہے جو اس کے بعد مذکور ہے۔ مخطوطہ میں اس سند کے بعد حاشیہ میں اس روایت کی سند اس طرح لکھی ہے: ’’ثنا شعبة، عن منصور و ابراهيم بن أبي حرة، قال منصور: ثنا إبراهيم النخعي، وقال ابن أبى حرة: ثنا مجاهد - قالا . . . ’’۔"}],[247,"§سولھویں دلیل:\nہمیں ابو نصر عمر بن عبدالعزیز بن عمر بن قتادہ نے بیان کیا، انھوں نے کہا: ہمیں ابو منصور عباس بن فضل النضروی نے بیان کیا، انھوں نے کہا: ہمیں احمد بن نجدہ نے بیان کیا، انھوں نے کہا: ہمیں ہشیم بن بشیر نے بیان کیا، انھوں نے عوام بن حوشب نے بیان کیا، انھوں نے مجاہد بن جبر سے، اللہ تعالیٰ کے فرمان: ﴿وَإِذَا قُرِئَ الْقُرْآنُ فَاسْتَمِعُوا لَهُ وَأَنْصِتُوا﴾ (جب قرآن پڑھا جائے تو توجہ سے سنو اور خاموش رہو) کے بارے میں روایت کیا ہے کہ انھوں نے فرمایا: یہ جمعہ کے روز خطبہ کے بارے میں ہے۔ (1)","",{"f":"§حواشی\n(1) یہ اثر صحیح ہے۔ تفسير سعيد بن منصور: 179/5، حديث، 976 - ابن العربی نے اس روایت کو ضعیف قرار دیا ہے۔ أحكام القرآن، لابن العربي: 817/2۔"}],[248,"§سترھویں دلیل:\nہمیں ابو عبداللہ الحافظ (امام حاکم) نے بیان کیا، انھوں نے کہا: ہمیں ابو علی الحافظ نے بیان کیا، انھوں نے کہا: ہمیں ابو یعلی الموصلی نے بیان کیا، انھوں نے کہا: ہمیں محمد بن ابی بکر المقدمی نے بیان کیا، انھوں نے کہا: ہمیں عبدالرحمن بن مہدی نے بیان کیا، انھوں نے کہا: ہمیں ہشیم بن بشیر نے بیان کیا، انھوں نے عوام بن حوشب سے روایت کیا کہ مجاہد بن جبر نے ﴿فَاسْتَمِعُوا لَهُ وَأَنْصِتُوا﴾ کے بارے میں فرمایا: یہ جمعہ کے دن، خطبہ کے بارے میں ہے۔ (1)","",{"f":"§حواشی\n(1) اسنادہ صحیح۔"}],[249,"§اٹھارویں دلیل (بروایت، سعید بن مسیب تابعی رحمہ اللہ):\nاسی سند کے ساتھ عبدالرحمن بن مہدی نے حماد بن سلمہ سے روایت کیا، انھوں نے قتادہ بن دعامہ سے روایت کیا کہ سعید بن مسیب (تابعی) نے ﴿فَاسْتَمِعُوا لَهُ وَأَنْصِتُوا﴾ کے متعلق فرمایا: یہ نماز کے بارے میں ہے۔ (1)","",{"f":"§حواشی\n(1) قتادہ مدلس کی تدلیس کے باعث یہ سند ضعیف ہے۔ تفسير الطبري: 347/13، حديث، 15588۔ تفسير طبری میں اس روایت کی سند اس طرح ہے: حدثنا ابن المثنى قال: حدثنا عبد الرحمن بن مهدى عن رجل عن قتادة عن سعيد بن المسيب ﴿وَإِذَا قُرِئَ الْقُرْآنُ فَاسْتَمِعُوا لَهُ وَأَنْصِتُوا﴾ قال فی الصلاة۔ اس سند میں ’’رجل‘‘ سے مراد، حماد بن سلمہ ہیں۔"}],[250,"§انیسویں دلیل (بروایت، ابراہیم نخعی رحمہ اللہ):\nاور اسی سند کے ساتھ عبدالرحمن بن مہدی نے ہمیں ابو عوانہ کے واسطے سے روایت کیا، انھوں نے مغیرہ بن مقسم الضبی سے، انھوں نے اپنے ساتھیوں سے روایت کیا کہ ابراہیم بن یزید نخعی نے ﴿وَإِذَا قُرِئَ الْقُرْآنُ فَاسْتَمِعُوا لَهُ وَأَنْصِتُوا﴾ (یعنی: جب قرآن پڑھا جائے تو توجہ سے سنو اور خاموش رہو) کے متعلق فرمایا: یہ نماز کے بارے میں ہے۔ (1)","",{"f":"§حواشی\n(1) مغیرہ کے شیوخ کے مبہم ہونے کے باعث یہ سند ضعیف ہے۔ مصنف ابن أبي شيبة: 446/5، حديث، 8461۔"}],[251,"§بیسویں دلیل (بروایت، حسن بصری رحمہ اللہ):\nہمیں ابو عبداللہ الحافظ (امام حاکم) نے بیان کیا، انھوں نے کہا: ہمیں ابو علی الحافظ نے بیان کیا، انھوں نے کہا: ہمیں ابو یعلی الموصلی نے بیان کیا، انھوں نے کہا: ہمیں محمد بن ابی بکر المقدمی نے بیان کیا، انھوں نے کہا: ہمیں یوسف بن یعقوب (ابن الماجشون) نے بیان کیا، انھوں نے شعبہ بن حجاج سے، انھوں نے منصور بن معتمر سے، انھوں نے حسن بصری سے روایت کیا کہ انھوں نے ﴿فَاسْتَمِعُوا لَهُ وَأَنْصِتُوا﴾ (یعنی: توجہ سے سنو اور خاموش رہو) کے متعلق فرمایا کہ یہ نماز کے بارے میں ہے۔ (1)","",{"f":"§حواشی\n(1) اسنادہ صحیح۔"}],[252,"§اکیسویں دلیل (بروایت، شعبی رحمہ اللہ):\nہمیں ابو عبداللہ الحافظ (امام حاکم) نے بیان کیا، انھوں نے کہا: ہمیں ابو علی الحافظ نے بیان کیا، انھوں نے کہا: ہمیں حامد بن شعیب نے بیان کیا، انھوں نے کہا: ہمیں سریج بن یونس نے بیان کیا، انھوں نے کہا: ہمیں عنبسہ بن عبدالواحد نے بیان کیا، انھوں نے کہا: ہمیں زکریا بن حکیم نے بیان کیا، انھوں نے کہا: امام عامر بن شراحیل الشعبی نے فرمایا: جب امام جہری (بلند آواز سے) قرآت کرے تو خاموش رہو، جیسا کہ اللہ تعالیٰ نے حکم دیا ہے: ﴿وَإِذَا قُرِئَ الْقُرْآنُ فَاسْتَمِعُوا لَهُ وَأَنْصِتُوا﴾ (یعنی: جب قرآن پڑھا جائے تو توجہ سے سنو اور خاموش رہو)۔ (1)","",{"f":"§حواشی\n(1) یہ سند ضعیف جدًا ہے۔ زکریا بن حکیم ضعیف راوی ہے۔"}],[253,"§بائیسویں دلیل (ابن شہاب زہری رحمہ اللہ کا قول):\nہمیں ابو عبداللہ الحافظ نے بیان کیا، انھوں نے کہا: ہمیں ابو علی الحافظ نے بیان کیا، انھوں نے کہا: ہمیں حسن بن سفیان نے بیان کیا، انھوں نے کہا: ہمیں حبان بن موسیٰ نے بیان کیا، انھوں نے کہا: ہمیں عبداللہ بن مبارک نے بیان کیا، انھوں نے کہا: ہمیں یونس بن یزید ایلی نے بیان کیا، انھوں نے ابن شہاب الزہری سے روایت کیا، انھوں نے فرمایا: جو شخص امام کے پیچھے ہے وہ ان نمازوں میں قرآت مت کرے جن میں امام جہری قرآت کرتا ہے۔ مقتدی کے لیے امام کی قرآت ہی کافی ہے چاہے امام انھیں اپنی قرآت نہ سنائے (یعنی، چاہے امام سری قرآت کر رہا ہو)۔ البتہ مقتدی ان نمازوں میں اپنے دل میں آہستہ آواز سے ہی قرآت کریں جن نمازوں میں امام جہری قرآت نہیں کرتا۔ اور کسی مقتدی کے لیے جائز نہیں کہ وہ جہری نماز میں امام کے ساتھ ساتھ بلند یا مدہم آواز میں قرآت کرے۔ اللہ تعالیٰ نے فرمایا ہے: ﴿وَإِذَا قُرِئَ الْقُرْآنُ فَاسْتَمِعُوا لَهُ وَأَنْصِتُوا﴾ (یعنی: جب قرآن پڑھا جائے تو توجہ سے سنو اور خاموش رہو)۔ (1)\nامام بیہقی رحمہ اللہ کہتے ہیں: بعض لوگوں نے ہماری بیان کردہ روایات کے علاوہ بھی اسی معانی و مفہوم کی مرفوع و موقوف روایات بیان کی ہیں۔ لیکن میں انھیں ثبوت کے طور پیش کرنے کی غرض سے اپنی کتاب کو غیر معیاری نہیں کرنا چاہتا۔\nامام شافعی رحمہ اللہ کے قدیم قول سے استدلال کی حقیقت:\nجو شخص امام شافعی رحمہ اللہ کے قدیم قول کو بنیاد بنا کر کہتا ہے کہ انھوں نے بھی اس آیت ﴿وَإِذَا قُرِئَ الْقُرْآنُ فَاسْتَمِعُوا لَهُ وَأَنْصِتُوا﴾ سے استدلال کیا ہے۔ اس کی بات اگر درست بھی مان لی جائے تو یہ آیت جہری نماز میں امام کی قرآت کو بغور سننے کے بارے میں ہے، سری نماز کے بارے میں نہیں۔ کیونکہ امام شافعی رحمہ اللہ نے تو قدیم قول میں یہ فرمایا تھا کہ ’’ہمارے نزدیک یہ آیت اس قرآت کے لیے خاص ہے جو قرآت سنی جائے۔‘‘ (2) (امام بیہقی رحمہ اللہ فرماتے ہیں:) تو جو قرآت سنی ہی نہیں جارہی (جیسا کہ ظہر و عصر کی چاروں، مغرب کی تیسری اور عشاء کی آخری دو رکعات ہیں) اس کے لیے خاموش کیسے رہا جائے؟ (3)\nاس آیت مبارکہ سے ابو عبید قاسم بن سلام (امام بخاری رحمہ اللہ کے استاذ) اور دیگر اہل علم و ادب نے اسی موقف کا استدلال کیا ہے۔ امام محمد بن اسماعیل البخاری رحمہ اللہ اپنی کتاب میں فرماتے ہیں: استماع تو اس قرآت (آواز) کے لیے ہے (یعنی سنی تو وہ بات جاتی ہے) جو جہری (بآواز بلند) ہو۔ (4)\nخاموشی کا حکم کس قرآت کے لیے ہے؟ (ماہرین لغت کا تجزیہ)\nامام بیہقی رحمہ اللہ فرماتے ہیں: اس شخص کی بات کا کوئی اعتبار (حیثیت) نہیں ہے، جو کہتا ہے کہ مقتدی قرآن کو بغور سننے اور اس کے لیے خاموش رہنے کا پابند ہے، اگرچہ امام بلند آواز سے (جہری) قرآت نہ بھی کر رہا ہو (یعنی سری قرآت کر رہا ہو)۔ (یہ بات قابل اعتبار نہیں) کیونکہ اہل زبان (ماہرین لغت) کے ہاں لغت میں معروف ہے کہ کسی بات کے استماع (سننے) کا حکم تب ہوتا ہے جب وہ بات سنی جائے۔ جب کوئی بات سنی ہی نہ جائے تو اس کے استماع (یعنی سننے) اور اس کے لیے خاموش رہنے کا حکم نہیں دیا جاسکتا۔ اسی وجہ سے بعض صحابہ کرام رضی اللہ عنہم اور تابعین عظام رحمہم اللہ؛ امام کے پیچھے ان نمازوں میں قرآت ترک کرنے کے قائل ہیں جن میں امام جہری قرآت کرتا ہے۔ جن نمازوں میں امام مخفی قرآت کرتا ہے ان میں (ترک قرآت کے قائل) نہیں ہیں۔ اور یہ موقف رکھنے والے اہل زبان (ماہرین لغت) ہیں۔\nمسئلہ کی تفہیم کے لیے ایک مثال:\nجو سیدنا عبداللہ بن عباس رضی اللہ عنہ کی حدیث ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جس شخص نے لوگوں کی بات کان لگا کر سنی، حالانکہ وہ لوگ اس بات کا (دوسرے کے کانوں تک پہنچنا) برا سمجھتے ہوں، قیامت کے روز اس شخص کے کان میں پگھلا ہوا سیسہ ڈالا جائے گا۔‘‘ (5)\nیہ وعید اس بات کے متعلق ہے جو کان لگائے (چوری چھپے) سننے والے کو سنائی دے، جبکہ بات کرنے والے کو علم نہ ہو۔ اور اگر اس نے کوشش تو کی لیکن کچھ سن نہ سکا تو ہم اسے سننے والا قرار نہیں دے سکتے اور نہ ہی وہ شخص اس وعید کا مستحق قرار پاتا ہے۔ اگرچہ سننے کی کوشش کے باعث وہ گنہگار تصور کیا جائے گا۔\nاس کا معاملہ اسی طرح ہے کہ کسی شخص نے گناہ کا ارادہ تو کیا لیکن اس میں کامیاب نہ ہوسکا۔ تو ایسے شخص کو اس گناہ کا مرتکب قرار نہیں دیا جاتا اور نہ ہی وہ اس گناہ کے مرتکب کے لیے مذکور وعید کا مستحق بنتا ہے۔\nجو نمازی قرآت سن ہی نہ سکتا ہو...!\nجو نمازی بہرہ ہونے یا امام سے دور کھڑا ہونے کے باعث قرآت نہ سن سکے تو وہ بھی استماع (قرآت سننے) اور انصات (خاموش رہنے) کا پابند ہے، کیونکہ وہ حکماً اور شرعاً سامع ہی ہے۔ البتہ لغت کے اعتبار سے وہی سامع ہے جو ہم نے (سابقہ سطور میں) بیان کر دیا ہے۔ ..... واللہ اعلم (6)\nصحیح موقف کیا ہے؟\nامام بیہقی رحمہ اللہ فرماتے ہیں: جس نے صحیح بات کہی ہے، وہ یہ ہے کہ امام جہری قرآت کرے یا مخفی؛ امام کے پیچھے قرآت کرنا واجب ہے۔ ان کا یہی کہنا ہے کہ ہم اس آیت مبارکہ ﴿وَإِذَا قُرِئَ الْقُرْآنُ فَاسْتَمِعُوا لَهُ وَأَنْصِتُوا﴾ کے نماز کے متعلق یا نماز اور خطبہ کے متعلق ہونے کے انکاری نہیں ہیں۔ جیسا کہ ان اسلاف امت کا موقف ہے جن کے اقوال ہم نے (گذشتہ صفحات میں) بیان کیے ہیں۔ البتہ انھوں نے اور ان کے علاوہ بھی بعض اسلاف نے حدیث کو اختصار سے بیان کرتے ہوئے محض یہ کہہ دیا ہے کہ یہ آیت نماز کے بارے میں ہے۔\nیہ روایت، در حقیقت؛ طویل حدیث کا اختصار ہے:\nایک حدیث سیدنا ابو ہریرہ رضی اللہ عنہ نے روایت کی ہے۔ آپ رضی اللہ عنہ اپنے دور کے حدیث روایت کرنے والوں میں سب سے بڑھ کر حافظ الحدیث تھے۔ پھر بعض صحابہ کرام رضی اللہ عنہم اور تابعین عظام رحمہم اللہ نے سیدنا ابو ہریرہ رضی اللہ عنہ کی متابعت میں وہی حدیث مکمل بیان کی ہے۔ جس میں مفصل و بالصراحت بیان کیا گیا ہے کہ اس آیت مبارکہ کے نازل ہونے سے پہلے صحابہ کرام رضی اللہ عنہم نماز میں کیا کرتے تھے۔ پھر اس آیت میں اس عمل کی ممانعت نازل ہوگئی۔ لہذا اسی حدیث کی طرف رجوع کرنا اور اسی پر اکتفا کرنا واجب ہے۔ (7) بجائے اس کے کہ اس قرآت سے خاموشی اختیار کر لی جائے جو قرآت نماز میں بالاصل (بنیادی طور پر، حقیقتاً) مشروع (واجب) ہے۔ البتہ (اگر ان کی بات تسلیم کر بھی لی جائے تو مقتدی کا) قرآت کرنا اور امام کی قرآت کو سننا اکٹھا (بیک وقت) ہو جانا بھی ممکن ہے۔ جیسا کہ ہم آئندہ بیان کریں گے۔ ان شاء اللہ۔\n’’وَإِذَا قُرِئَ الْقُرْآنُ...‘‘ کی شان نزول سے متعلق مفصل روایات:\n(ذیل میں وہ روایات بیان کی گئی ہیں، جن میں قرآن مجید کی آیت ﴿وَإِذَا قُرِئَ الْقُرْآنُ فَاسْتَمِعُوا لَهُ﴾ کے متعلق تفصیل اور صراحت سے مذکور ہے کہ اس کی حقیقی شان نزول کیا ہے؟ [العاصم])","",{"f":"§حواشی\n(1) اسنادہ حسن۔ تفسير الطبري 250/13، حديث، 15607۔\n(2) امام بیہقی رحمہ اللہ نے ’’معرفۃ السنن والآثار‘‘ میں بھی امام شافعی رحمہ اللہ کا یہ قدیم قول صراحت کے ساتھ ذکر کیا ہے: ’’قَالَ الشَّافِعِيُّ رَحِمَهُ اللهُ فِي الْقَدِيمِ: فَهَذَا عِنْدَنَا عَلَى الْقِرَاءَةِ الَّتِي تُسْمَعُ خَاصَّةً۔ [معرفة السنن والآثار، للبيهقي: 74/3، حديث، 3738]\n(3) احكام القرآن للشافعي: 77/1۔\n(4) جزء القراءة خلف الامام، للبخاري: ص، 34۔\n(5) صحيح البخارى كتاب التعبير باب من كذب في حلمه، حدیث، 7042 - سنن أبي داؤد، كتاب الأدب، باب ماجاء في الرؤيا، حدیث، 5024۔\n(6) یعنی جو آواز سنی ہی نہ جائے اس کے متعلق کوئی حکم کس طرح لاگو ہو سکتا ہے؟ حکم اسی آواز کے متعلق نافذ ہوگا جو سنائی دیتی ہو۔ رسول اللہ صلی اللہ علیہ وسلم نے مقتدیوں کو اسی قرآت سے منع فرمایا تھا جو دوسروں کو سنائی دیتی ہو، کیونکہ اس سے امام کو قرآت میں الجھن ہوتی ہے۔ آپ صلی اللہ علیہ وسلم نے منع بھی اس لیے فرمایا تھا کہ صحابی کی آواز بلند ہو کر آپ صلی اللہ علیہ وسلم کو سنائی دے کر آپ صلی اللہ علیہ وسلم کے لیے الجھن کا باعث بن رہی تھی۔ اور آپ صلی اللہ علیہ وسلم نے ممانعت سے سورت فاتحہ کو مستثنیٰ کرتے ہوئے، فاتحہ کو ایسے انداز سے پڑھنے کا حکم دیا تھا، جس کی آواز دوسروں تک نہ پہنچے۔ واللہ اعلم [العاصم]\n(7) یہاں حدیث نمبر: 253 اور اس کے بعد والی احادیث کی طرف اشارہ ہے۔"}],[254,"§(پہلی حدیث):\n(پہلی سند) ہمیں علی بن احمد بن عبدان نے بیان کیا، انھوں نے کہا: ہمیں احمد بن عبید الصفار نے بیان کیا، انھوں نے کہا: ہمیں اسماعیل بن اسحاق نے بیان کیا، انھوں نے کہا: ہمیں محمد بن ابی بکر المقدمی نے بیان کیا.....\nوَأَخْبَرَنَا أَبُو عَبْدِ اللَّهِ الْحَافِظُ، أنا أَبُو عَلِيٍّ الْحُسَيْنُ بْنُ عَلِيٍّ الْحَافِظُ، نا أَبُو يَعْلَى الْمَوْصِلِيُّ، نا مُحَمَّدُ بْنُ أَبِي بَكْرٍ الْمُقَدَّمِيُّ، نا مُحَمَّدُ بْنُ دِينَارٍ، نا إِبْرَاهِيمُ الْهَجَرِيُّ، عَنْ أَبِي عِيَاضٍ، عَنْ أَبِي هُرَيْرَةَ، قَالَ: كَانُوا يَتَكَلَّمُونَ فِي الصَّلَاةِ فَنَزَلَتْ ﴿وَإِذَا قُرِئَ الْقُرْآنُ فَاسْتَمِعُوا لَهُ وَأَنْصِتُوا لَعَلَّكُمْ تُرْحَمُونَ﴾ [الأعراف: 204]\n(دوسری سند) ہمیں ابوعبداللہ الحافظ (امام حاکم) نے بیان کیا، انھوں نے کہا: ہمیں ابو علی حسین بن علی الحافظ نے بیان کیا، انھوں نے کہا: ہمیں ابو یعلی الموصلی نے بیان کیا، انھوں نے کہا: ہمیں محمد بن ابی بکر المقدمی نے بیان کیا، انھوں نے کہا: ہمیں محمد بن دینار الازدی نے بیان کیا، انھوں نے کہا: ہمیں ابراہیم بن مسلم الہجری نے بیان کیا، انھوں نے ابو عیاض عمرو بن اسود العنسی (مخضرم) سے روایت کیا کہ سیدنا ابو ہریرہ رضی اللہ عنہ نے فرمایا: صحابہ کرام رضی اللہ عنہم نماز میں بات چیت (کلام، گفتگو) کیا کرتے تھے۔ تو یہ آیت نازل ہو گئی: ’’جب قرآن پڑھا جائے تو غور سے سنو اور خاموشی اختیار کرو، تاکہ تم پر رحم کیا جائے۔‘‘ (1)","",{"f":"§حواشی\n(1) اسناده حسن لغيره۔ الأوسط، لابن المنذر: 105/3، حدیث، 1318 السنن الكبرى للبيهقي: 155/2۔"}],[255,"§دوسری حدیث:\nہمیں ابوعبداللہ الحافظ (امام حاکم) نے بیان کیا، انھوں نے کہا: ہمیں ابوعلی الحافظ نے بیان کیا، انھوں نے کہا: ہمیں ابراہیم بن محمد المروزی نے بیان کیا، انھوں نے کہا: ہمیں علی بن حجر بن ایاس البغدادی نے بیان کیا، انھوں نے کہا: ہمیں علی بن مسہر نے بیان کیا، انھوں نے ابواسحاق ابراہیم بن مسلم الہجری سے، انھوں نے ابوعیاض عمرو بن اسود العنسی سے، انھوں نے سیدنا ابو ہریرہ رضی اللہ عنہ سے آیت: ﴿وَإِذَا قُرِئَ الْقُرْآنُ فَاسْتَمِعُوا لَهُ وَأَنْصِتُوا﴾ کے بارے میں روایت کیا کہ انھوں نے فرمایا: صحابہ کرام رضی اللہ عنہم نماز میں کلام (بات چیت) کر لیا کرتے تھے۔ حتی کہ یہ آیت نازل ہو گئی۔ (1)","",{"f":"§حواشی\n(1) اسناده حسن لغيره۔"}],[256,"§تیسری حدیث:\nہمیں ابوالحسین بن عبدان نے بیان کیا، انھوں نے کہا: ہمیں احمد بن عبید الصفار نے بیان کیا، انھوں نے کہا: ہمیں اسماعیل بن اسحاق نے بیان کیا، انھوں نے کہا: ہمیں شیبان بن فروخ نے بیان کیا، انھوں نے کہا: ہمیں عبدالعزیز بن مسلم القسملی نے بیان کیا، انھوں نے کہا: ہمیں ابراہیم بن مسلم الہجری نے بیان کیا، انھوں نے ابو عیاض عمرو بن اسود العنسی سے روایت کیا کہ سیدنا ابو ہریرہ رضی اللہ عنہ نے فرمایا: صحابہ کرام رضی اللہ عنہم نماز میں کلام (بات چیت) کر لیا کرتے تھے۔ حتی کہ یہ آیت مبارکہ: ﴿وَإِذَا قُرِئَ الْقُرْآنُ فَاسْتَمِعُوا لَهُ وَأَنْصِتُوا﴾ نازل ہو گئی۔ یعنی یہ نماز کے بارے میں ہے۔ (1)","",{"f":"§حواشی\n(1) اسناده حسن لغيره۔ السنن الكبرى للبيهقي: 155/2۔"}],[257,"§چوتھی حدیث:\nہمیں محمد بن عبداللہ الحافظ نے بیان کیا، انھوں نے کہا: ہمیں ابو علی حسین بن علی الحافظ نے بیان کیا، انھوں نے کہا: ہمیں عبداللہ بن محمد بن بشر بن صالح الحافظ نے بیان کیا، انھوں نے کہا: ہمیں ابو عمیر بن نحاس الرملی نے بیان کیا، انھوں نے کہا: ہمیں مؤمل بن اسماعیل نے بیان کیا، انھوں نے کہا: ہمیں عبدالعزیز بن مسلم القسملی نے بیان کیا، انھوں نے کہا: ہمیں محمد بن زیاد نے بیان کیا، انھوں نے سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت کیا، آپ نے فرمایا: صحابہ کرام رضی اللہ عنہم نماز میں کلام (بات چیت) کر لیا کرتے تھے۔ پھر اللہ تعالیٰ نے یہ آیت مبارکہ نازل کر دی: ﴿وَإِذَا قُرِئَ الْقُرْآنُ فَاسْتَمِعُوا لَهُ وَأَنْصِتُوا لَعَلَّكُمْ تُرْحَمُونَ﴾ (یعنی: جب قرآن پڑھا جائے تو توجہ سے سنو اور خاموشی اختیار کرو تاکہ تم پر رحم کیا جائے) تب صحابہ کرام رضی اللہ عنہم کو نماز میں خشوع کا حکم دیا گیا اور باتیں کرنے سے منع کر دیا گیا۔ (1)","",{"f":"§حواشی\n(1) اسناده حسن لغيره۔"}],[258,"§پانچویں حدیث:\nہمیں ابوعبداللہ الحافظ اور ابو عبداللہ اسحاق بن محمد بن یوسف السوسی نے بیان کیا، ان دونوں نے کہا: ہمیں ابو عباس محمد بن یعقوب نے بیان کیا، انھوں نے کہا: ہمیں عباس بن ولید بن مزید نے بیان کیا، انھوں نے کہا: مجھے میرے والد محترم ولید بن مزید نے بیان کیا، انھوں نے کہا: میں نے اوزاعی کو کہتے ہوئے سنا کہ مجھے عبداللہ بن عامر نے بیان کیا، انھوں نے کہا: مجھے زید بن اسلم نے بیان کیا، انھوں نے اپنے والد اسلم العدوی سے، انھوں نے اس آیت: ﴿وَإِذَا قُرِئَ الْقُرْآنُ فَاسْتَمِعُوا لَهُ وَأَنْصِتُوا﴾ کے بارے میں سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت کیا، آپ نے فرمایا: یہ آیت تب نازل ہوئی جب صحابہ کرام رضی اللہ عنہم رسول اللہ صلی اللہ علیہ وسلم کے پیچھے نماز میں (قرآت کرتے ہوئے) آواز بلند کرتے تھے۔ (1)","",{"f":"§حواشی\n(1) اسناده حسن لغيره۔ سنن الدارقطني: 326/1 تفسير الطبري: 346/13، حدیث، 15586 تفسير ابن أبي حاتم: 1645/5، حدیث، 8726 أسباب النزول، للواحدي: ص 233، حدیث، 463 الفوائد، لتمام الرازي: 72/1، حدیث، 156، 157 تاريخ دمشق لابن عساكر: 70/31 عبداللہ بن عامر، ضعیف راوی ہے۔ البتہ یہ حدیث صحیح ہے۔"}],[259,"§چھٹی حدیث:\nہمیں ابوعبداللہ الحافظ نے بیان کیا، انھوں نے کہا: ہمیں حسین بن علی الحافظ نے بیان کیا، انھوں نے کہا: ہمیں عبداللہ بن محمد بن بشر بن صالح الدینوری الحافظ نے بیان کیا، انھوں نے کہا: ہمیں عبداللہ بن مصعب الزبیری نے بیان کیا، انھوں نے کہا: ہمیں عیسیٰ بن مغیرہ نے بیان کیا، انھوں نے کہا: ہمیں عاصم بن عمر نے بیان کیا، انھوں نے حمید بن قیس سے، انھوں نے قاسم بن ابی بزہ سے، انھوں نے سعید بن جبیر سے، انھوں نے سیدنا عبداللہ بن عباس رضی اللہ عنہما سے اس آیت: ﴿وَإِذَا قُرِئَ الْقُرْآنُ فَاسْتَمِعُوا لَهُ وَأَنْصِتُوا﴾ کے بارے میں روایت کیا، آپ رضی اللہ عنہ نے فرمایا: یہ آیت؛ رسول اللہ صلی اللہ علیہ وسلم کے پیچھے دوران نماز صحابہ کرام رضی اللہ عنہم کی بلند آوازوں (میں باہمی گفتگو کے معمول)، جمعہ کے خطبہ اور عیدین کے بارے میں نازل ہوئی، تو نماز میں بات کرنے سے صحابہ کرام رضی اللہ عنہم کو منع کر دیا گیا۔ (1)","",{"f":"§حواشی\n(1) اسناده حسن لغيره۔"}],[260,"§ساتویں حدیث:\nہمیں ابوبکر بن حارث الفقیہ نے بیان کیا، انھوں نے کہا: ہمیں ابومحمد بن حیان نے بیان کیا، انھوں نے کہا: ہمیں عبداللہ بن محمد بن عباس نے بیان کیا، انھوں نے کہا: ہمیں سہل بن عثمان الکندی نے بیان کیا، انھوں نے کہا: ہمیں ابن ابی زائدہ (یحییٰ بن زکریا) نے بیان کیا، انھوں نے کہا: مجھے اشعث بن سوار الکندی نے بیان کیا، انھوں نے ابن شہاب زہری سے روایت کیا، انھوں نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم کے پیچھے ایک انصاری نوجوان (نماز پڑھ رہا) تھا۔ جب نبی کریم صلی اللہ علیہ وسلم کوئی آیت پڑھتے تو وہ نوجوان بھی پڑھتا۔ تب یہ آیت: ﴿وَإِذَا قُرِئَ الْقُرْآنُ فَاسْتَمِعُوا لَهُ وَأَنْصِتُوا﴾ نازل ہوئی۔ (1)","",{"f":"§حواشی\n(1) اشعث بن سوار ضعیف راوی ہے۔ یہ سند ضعیف ہے۔ تفسير الطبري: 346/13، حدیث، 15583۔"}],[261,"§آٹھویں حدیث:\nہمیں ابوعبداللہ الحافظ نے بیان کیا، انھوں نے کہا: ہمیں ابوعلی الحافظ نے بیان کیا، انھوں نے کہا: ہمیں ابراہیم بن محمد المروزی نے بیان کیا، انھوں نے کہا: ہمیں محمد بن رافع القشیری نے بیان کیا، انھوں نے کہا: ہمیں عبدالرزاق بن ہمام الصنعانی نے بیان کیا، انھوں نے کہا: ہمیں معمر بن راشد نے بیان کیا، انھوں نے قتادہ بن دعامہ السدوسی سے روایت کیا کہ انھوں نے اللہ تعالیٰ کے فرمان: ﴿وَإِذَا قُرِئَ الْقُرْآنُ فَاسْتَمِعُوا لَهُ وَأَنْصِتُوا لَعَلَّكُمْ تُرْحَمُونَ﴾ کے بارے میں بیان کیا، انھوں نے فرمایا: کوئی صحابی آتا، اور دیگر صحابہ نماز میں ہوتے تو وہ ان سے پوچھ لیتا کہ کتنی (رکعات) نماز پڑھ چکے ہو؟ اور کتنی باقی ہے؟ تو اللہ عزوجل نے یہ آیت: ﴿وَإِذَا قُرِئَ الْقُرْآنُ فَاسْتَمِعُوا لَهُ﴾ ... نازل کر دی۔ (1)","",{"f":"§حواشی\n(1) اسناده ضعیف۔ تفسير عبدالرزاق: 107/2، حدیث، 977 تفسير الطبري: 347/13، حدیث، 15599۔"}],[262,"§نویں حدیث:\nہمیں ابونصر عمر بن عبدالعزیز بن عمر بن قتادہ نے بیان کیا، انھوں نے کہا: ہمیں عباس بن فضل نضروی نے بیان کیا، انھوں نے کہا: ہمیں احمد بن نجدہ نے بیان کیا، انھوں نے کہا: ہمیں سعید بن منصور نے بیان کیا، انھوں نے کہا: ہمیں عون بن موسیٰ نے بیان کیا، انھوں نے کہا: میں نے معاویہ بن قرہ کو سنا، وہ فرما رہے تھے: اللہ عزوجل نے یہ آیت: ﴿وَإِذَا قُرِئَ الْقُرْآنُ فَاسْتَمِعُوا لَهُ وَأَنْصِتُوا﴾ نماز کے بارے میں نازل فرمائی۔ لوگ نماز میں ہی کلام (بات چیت) کر لیا کرتے تھے۔ (1)\nخلاصہ کلام:\nیہ روایات اس بات کی دلیل ہیں کہ اللہ تعالیٰ نے اس آیت مبارکہ ﴿وَإِذَا قُرِئَ الْقُرْآنُ فَاسْتَمِعُوا لَهُ وَأَنْصِتُوا﴾ میں جس انصات (خاموشی اختیار کرنے) کا حکم دیا ہے، وہ بات چیت (باہمی گفتگو) سے خاموشی ہے، جو گفتگو صحابہ کرام رضی اللہ عنہم دوران نماز کر لیا کرتے تھے۔ اسی طرح امام کے پیچھے قرآت کرتے وقت ’’آوازیں بلند کرنے‘‘ سے خاموشی اختیار کرنے کا حکم دیا گیا ہے؛ دل میں ’’قرآت اور ذکر‘‘ کرنے سے خاموش رہنے کا حکم نہیں دیا گیا۔\n’’قُومُوا لِلَّهِ قَانِتِينَ‘‘ اور نماز میں انصات کا حکم:\nاس حدیث جیسی احادیث سیدنا زید بن ارقم اور سیدنا عبداللہ بن مسعود رضی اللہ عنہما کی بھی ہیں۔","",{"f":"§حواشی\n(1) ارسال کے باعث یہ روایت ضعیف ہے۔ تفسير سعيد بن منصور: 182/5، حدیث، 979 السنن الكبرى للبيهقي: 155/2۔"}],[263,"§نماز میں گفتگو سے ممانعت (روایت، سیدنا زید بن ارقم رضی اللہ عنہ):\n(پہلی سند) ہمیں ابوعبداللہ محمد بن عبداللہ الحافظ نے بیان کیا، انھوں نے کہا: ہمیں ابوعبداللہ محمد بن یعقوب نے بیان کیا، انھوں نے کہا: ہمیں محمد بن عبدالوہاب الفراء اور علی بن حسن نے بیان کیا، ان دونوں نے کہا: ہمیں یعلیٰ بن عبید نے بیان کیا، انھوں نے کہا: ہمیں اسماعیل بن ابی خالد نے بیان کیا .... (ح)\nوَأَخْبَرَنَا أَبُو عَبْدِ اللَّهِ، أَخْبَرَنِي أَبُو النَّضْرِ، نا مُحَمَّدُ بْنُ نَصْرٍ، نا يَحْيَى بْنُ يَحْيَى، أنا هُشَيْمٌ، أنا إِسْمَاعِيلُ بْنُ أَبِي خَالِدٍ، عَنِ الْحَارِثِ بْنِ شُبَيْلٍ، عَنْ أَبِي عَمْرٍو الشَّيْبَانِيِّ، عَنْ زَيْدِ بْنِ أَرْقَمَ، قَالَ: كَانَ أَحَدُنَا يُكَلِّمُ يَعْنِي صَاحِبَهُ إِلَى جَنْبِهِ فِي الصَّلَاةِ، حَتَّى نَزَلَتْ ﴿وَقُومُوا لِلَّهِ قَانِتِينَ﴾ فَأُمِرْنَا بِالسُّكُوتِ وَنُهِينَا عَنِ الْكَلَامِ۔\n(دوسری سند) ہمیں ابوعبداللہ نے بیان کیا، انھوں نے کہا: مجھے ابونضر نے بیان کیا، انھوں نے کہا: ہمیں محمد بن نصر المروزی نے بیان کیا، انھوں نے کہا: ہمیں یحییٰ بن یحییٰ نے بیان کیا، انھوں نے کہا: ہمیں ہشیم بن بشیر نے بیان کیا، انھوں نے کہا: ہمیں اسماعیل بن ابی خالد نے بیان کیا، انھوں نے حارث بن شبیل سے، انھوں نے ابو عمرو سعد بن ایاس الشیبانی سے، انھوں نے سیدنا زید بن ارقم رضی اللہ عنہ سے روایت کیا، انھوں نے فرمایا: ہم میں سے کوئی بھی شخص اپنے ایک طرف کھڑے شخص سے دوران نماز بات چیت کر لیتا تھا۔ حتی کہ یہ آیت نازل ہو گئی: ﴿وَقُومُوا لِلَّهِ قَانِتِينَ﴾ [البقرۃ: 238] (یعنی: اللہ کے لیے باادب کھڑے رہو)۔ پھر ہمیں خاموشی اختیار کرنے کا حکم دیا گیا اور بات چیت کرنے سے منع کر دیا گیا۔ (1)\nاس حدیث کو امام مسلم رحمہ اللہ نے ’’صحیح مسلم‘‘ میں یحییٰ بن یحییٰ سے روایت کیا ہے۔ (2) اور امام بخاری رحمہ اللہ نے یحییٰ بن سعید القطان اور دیگر (یعنی عیسیٰ بن یونس) کی سند کے ساتھ اسماعیل بن ابی خالد سے روایت کیا ہے۔ (3)","",{"f":"§حواشی\n(1) اسناده صحيح۔\n(2) صحيح مسلم: حدیث، 539۔\n(3) صحيح البخاري: حدیث، 1200، 4534۔"}],[264,"§دوران نماز سلام کا جواب دینا چھوڑ دیا (ابن مسعود رضی اللہ عنہ کی روایت):\nہمیں ابومحمد عبداللہ بن یوسف الاصبہانی نے بیان کیا، انھوں نے کہا: ہمیں ابوسعید بن الاعرابی نے بیان کیا، انھوں نے کہا:\nہمیں سعدان بن نصر نے بیان کیا، انھوں نے کہا: ہمیں ابوبدر شجاع بن ولید السکونی الکوفی نے بیان کیا، انھوں نے سلیمان بن مہران الاعمش سے، انھوں نے ابراہیم نخعی سے، انھوں نے علقمہ بن قیس سے، انھوں نے سیدنا عبداللہ بن مسعود رضی اللہ عنہ سے روایت کیا، انھوں نے فرمایا: ہم دوران نماز، نبی کریم صلی اللہ علیہ وسلم کو سلام کہہ لیتے اور آپ صلی اللہ علیہ وسلم ہمیں سلام کا جواب دے دیا کرتے تھے۔ جب ہم نجاشی کے ہاں سے واپس آئے تو ہم نے آپ صلی اللہ علیہ وسلم کو دوران نماز سلام کہا تو آپ صلی اللہ علیہ وسلم نے جواب نہ دیا۔ ہم نے عرض کیا: اللہ کے رسول! آپ ہمیں سلام کا جواب دے دیا کرتے تھے، لیکن آج کیا ہوا؟ آپ صلی اللہ علیہ وسلم نے فرمایا: ’’نماز میں اہم ترین مصروفیت ہوتی ہے۔‘‘ (1)\nیہ حدیث امام بخاری اور امام مسلم رحمہما اللہ نے ’’محمد بن فضیل بن غزوان عن اعمش‘‘ کی سند سے بیان کی ہے۔ (2)","",{"f":"§حواشی\n(1) یہ سند صحیح لغیرہ ہے۔ اور حدیث صحیح ہے۔ سیدنا عبداللہ بن مسعود رضی اللہ عنہ نے فرمایا: ’’جب ہم نجاشی کے ہاں سے واپس آئے‘‘۔ اس کی وضاحت یہ ہے کہ سیدنا عبداللہ بن مسعود رضی اللہ عنہ دوری ہجرت حبشہ میں مکہ سے حبشہ کی طرف ہجرت کر گئے تھے۔ جب حبشہ میں مقیم مہاجرین کو اطلاع ملی کہ رسول اللہ صلی اللہ علیہ وسلم مکہ سے مدینہ ہجرت کر گئے ہیں۔ تو حبشہ سے مدینہ ہجرت کر کے نبی کریم صلی اللہ علیہ وسلم کے پاس آنے والوں میں سیدنا عبداللہ بن مسعود رضی اللہ عنہ بھی تھے۔\n(2) صحيح البخاري، حدیث: 1199 صحيح مسلم، حدیث: 538۔"}],[265,"ہمیں ابوالحسن علی بن محمد بن علی المقرئ نے بیان کیا، انھوں نے کہا: ہمیں حسن بن محمد بن اسحاق نے بیان کیا، انھوں نے کہا: ہمیں یوسف بن یعقوب القاضی نے بیان کیا، انھوں نے کہا: ہمیں عمرو بن مرزوق نے بیان کیا، انھوں نے کہا: ہمیں زائدہ بن قدامہ نے بیان کیا، انھوں نے عاصم بن بہدلہ بن ابی النجود سے، انھوں نے شقیق بن سلمہ اسدی سے، انھوں نے سیدنا عبداللہ بن مسعود رضی اللہ عنہ سے روایت کیا، انھوں نے فرمایا: ہم دوران نماز بات چیت کر لیا کرتے تھے۔ ایک دوسرے کو سلام بھی کہہ لیتے، ایک دوسرے کو کام بھی کہہ لیا کرتے تھے۔ آپ رضی اللہ عنہ نے فرمایا: ایک روز میں نبی کریم صلی اللہ علیہ وسلم کے ہاں آیا، اور آپ صلی اللہ علیہ وسلم نماز پڑھ رہے تھے۔ میں نے آپ کو سلام کہا، لیکن آپ صلی اللہ علیہ وسلم نے جواب نہ دیا۔ پہلے کے حالات (یعنی آپ صلی اللہ علیہ وسلم کا جواب دے دینا) اور نئے حالات (جواب نہ دینا) نے مجھے سوچ میں ڈال دیا۔ جب آپ صلی اللہ علیہ وسلم فارغ ہوئے تو فرمایا: اللہ تعالیٰ جب چاہیں نیا حکم جاری فرما دیتے ہیں۔ اب نیا حکم یہ ہے کہ نماز کے دوران بات نہ کیا کرو۔‘‘ (1)\nگفتگو سے ممانعت تھی، قرآت سے نہیں:\nامام بیہقی رحمہ اللہ فرماتے ہیں: صحابہ کرام رضی اللہ عنہم کو جس سکوت (خاموشی) کا حکم سیدنا زید بن ارقم رضی اللہ عنہ کی حدیث میں ﴿وَقُومُوا لِلَّهِ قَانِتِينَ﴾ کو نازل کر کے دیا ہے، یہ وہی انصات (خاموشی) ہے جس کا صحابہ کرام رضی اللہ عنہم کو سیدنا ابو ہریرہ رضی اللہ عنہ اور دیگر کی حدیث میں ﴿وَإِذَا قُرِئَ الْقُرْآنُ فَاسْتَمِعُوا لَهُ وَأَنْصِتُوا﴾ نازل کر کے دیا تھا۔ اور سیدنا عبداللہ بن مسعود رضی اللہ عنہ کی حدیث میں جس نئے حکم کا ذکر ہے وہ: دوران نماز بات چیت کرنے، اپنی ضرورت کے لیے ایک دوسرے کو دوران نماز کوئی کام کہنے، اور دوران نماز ایک دوسرے کو سلام کہنے سے خاموشی اختیار کرنا ہے۔ یہ بھی وہی انصات (خاموشی) ہے جس کا حکم سیدنا ابو ہریرہ رضی اللہ عنہ کی حدیث میں اللہ تعالیٰ کے فرمان: ﴿وَإِذَا قُرِئَ الْقُرْآنُ فَاسْتَمِعُوا لَهُ وَأَنْصِتُوا﴾ کے تحت دیا گیا ہے۔ البتہ ذکر (تسبیحات)، اور نمازی کے لیے ضروری قرآت، یعنی سورت فاتحہ پڑھنے، سے خاموشی کا حکم نہیں دیا گیا۔ اس بات کی وضاحت سیدنا عبداللہ بن مسعود رضی اللہ عنہ کی دوسری صحیح حدیث میں بیان ہوئی ہے۔ (یعنی جس حدیث میں بات چیت سے منع کیا اور ذکر کرنے کا تذکرہ کیا گیا ہے)۔ حدیث حسب ذیل ہے:","",{"f":"§حواشی\n(1) یہ سند صحیح لغیرہ ہے، اور حدیث صحیح ہے۔ یہ حدیث عاصم بن ابی النجود نے شقیق سے، انھوں نے سیدنا عبداللہ بن مسعود رضی اللہ عنہ سے روایت کی ہے۔ اور عاصم بن ابی النجود سے متعدد ائمہ نے یہ حدیث روایت کی ہے۔ جن میں سے چند یہ ہیں: زائدہ بن قدامہ کی روایت: مسند أحمد بن حنبل: 435/1 المعجم الكبير للطبراني: 109/10، حدیث، 10141 حديث السراج: حدیث، 945 سفیان بن عیینہ کی روایت: سنن النسائی، حدیث: 1221 مصنف عبدالرزاق: 335/2، حدیث، 3594 معرفة السنن والآثار للبيهقي: 170/3، حدیث، 4156 ابان بن سعید کی روایت: سنن أبی داؤد، حدیث: 924 السنن الكبرى للبيهقي: 260/2 شعبہ بن حجاج کی روایت: مسند أحمد بن حنبل: 463/1 المعجم الكبير للطبراني: 109/10، حدیث، 10140 حماد بن سلمہ کی روایت: شرح معاني الآثار، للطحاوي: 451/1 جعفر بن حارث کی روایت: المعجم الكبير للطبراني: 110/10، حدیث، 10143۔"}],[266,"§اللہ کا ذکر کرو، باہمی گفتگو مت کرو:\nیہ روایت ہمیں امام ابو عثمان نے قرآت کے ذریعے بیان کی، انھوں نے کہا: ہمیں ابو عباس احمد بن محمد بن اسحاق الصندوقی نے قرآت کے ذریعے بیان کیا، انھوں نے کہا: ہمیں ابو قریش محمد بن جمعہ بن خلف الحافظ نے بیان کیا، انھوں نے کہا: ہمیں ابو صالح احمد بن خلف بن زید اور ابراہیم بن مسعود نے بیان کیا، ان دونوں نے کہا: ہمیں قاسم بن حکم العرنی نے بیان کیا، انھوں نے کہا: ہمیں سفیان ثوری نے بیان کیا، انھوں نے زبیر بن عدی سے، انھوں نے کلثوم بن علقمہ الخزاعی سے روایت کیا، انھوں نے کہا: میں نے سیدنا عبداللہ بن مسعود رضی اللہ عنہ کو سنا، آپ نے فرمایا: میں نبی کریم صلی اللہ علیہ وسلم کے ہاں آتا، آپ صلی اللہ علیہ وسلم نماز میں مصروف ہوتے، میں آپ صلی اللہ علیہ وسلم کو سلام کہتا، آپ صلی اللہ علیہ وسلم مجھے (دوران نماز ہی) سلام کا جواب دیتے۔ (سیدنا عبداللہ بن مسعود رضی اللہ عنہ) فرماتے ہیں: میں ایک مرتبہ آپ صلی اللہ علیہ وسلم کے پاس آیا، آپ صلی اللہ علیہ وسلم کو سلام کہا، لیکن آپ صلی اللہ علیہ وسلم نے جواب نہ دیا۔ تو (آپ صلی اللہ علیہ وسلم کے جواب نہ دینے کی وجہ معلوم کرنے کے لیے شدت انتظار کے باعث) آپ صلی اللہ علیہ وسلم کی وہ نماز میرے لیے سب سے زیادہ بوجھل تھی۔ جب آپ صلی اللہ علیہ وسلم نے سلام پھیرا تو اپنے ہاتھ سے لوگوں کی طرف اشارہ کرتے ہوئے فرمایا: ’’اللہ عزوجل جو چاہیں نیا حکم جاری فرما دیں۔ اللہ تعالیٰ نے نماز کے متعلق ایک نیا حکم جاری فرمایا ہے کہ تم دوران نماز؛ اللہ کے ذکر اور جو ضروری (قرآت) ہے؛ اس کے علاوہ کوئی بات (کلام) نہ کیا کرو۔ اور اللہ کے لیے باادب کھڑے رہا کرو۔ (1)","",{"f":"§حواشی\n(1) الحديث صحيح۔ سنن النسائی: حدیث، 1221 السنن الكبرى للنسائی: 199/1، حدیث، 558۔"}],[267,"(پہلی سند) ہمیں ابوعبداللہ الحافظ (امام حاکم) نے بیان کیا، انھوں نے کہا: ہمیں ابوالحسن علی بن احمد بن قرقوب التمار نے ہمذان میں بیان کیا، انھوں نے کہا: ہمیں ابو عمران موسیٰ بن محمد الاثط نے دمشق میں بیان کیا، انھوں نے کہا: ہمیں محمد بن عمار الموصلی نے بیان کیا، انھوں نے کہا: ہمیں قاسم بن یزید الجرمی نے بیان کیا، انھوں نے سفیان ثوری سے روایت کیا .... (ح)\nوَأَخْبَرَنَا أَبُو عَبْدِ اللَّهِ الْحَافِظُ، أنا أَبُو عَلِيٍّ الْحُسَيْنُ بْنُ عَلِيٍّ الْحَافِظُ، أنا إِبْرَاهِيمُ بْنُ يُوسُفَ الْهِسِنْجَانِيُّ، نا مُحَمَّدُ بْنُ عَبْدِ اللَّهِ بْنِ عَمَّارٍ الْمَوْصِلِيُّ، نا قَاسِمٌ الْجَرِمِيُّ، عَنْ سُفْيَانَ الثَّوْرِيِّ، عَنِ الزُّبَيْرِ بْنِ عَدِيٍّ، عَنْ كُلْثُومَ بْنِ الْمُصْطَلِقِ، قَالَ: سَمِعْتُ عَبْدَ اللَّهِ بْنَ مَسْعُودٍ رَضِيَ اللَّهُ عَنْهُ، فَذَكَرَ هَذَا الْحَدِيثَ۔ وَقَالَ فِي رِوَايَتِهِ عَنِ التَّمَّارِ: فَقَالَ: إِنَّ اللَّهَ عَزَّ وَجَلَّ أَحْدَثَ فِي الصَّلَاةِ أَنْ لَا تَكَلَّمُوا إِلَّا بِذِكْرِ اللَّهِ وَبِمَا يَنْبَغِي لَكُمْ وَأَنْ تَقُومُوا لِلَّهِ قَانِتِينَ۔\n(دوسری سند) ہمیں ابوعبداللہ الحافظ (امام حاکم) نے بیان کیا، انھوں نے کہا: ہمیں ابوعلی الحسین بن علی الحافظ نے بیان کیا، انھوں نے کہا: ہمیں ابراہیم بن یوسف الہسنجانی نے بیان کیا، انھوں نے کہا: ہمیں محمد بن عبداللہ بن عمار الموصلی نے بیان کیا، انھوں نے کہا: ہمیں قاسم بن یزید الجرمی نے بیان کیا، انھوں نے سفیان ثوری سے، انھوں نے زبیر بن عدی سے، انھوں نے کلثوم بن علقمہ بن ناجیہ بن مصطلق سے روایت کیا، انھوں نے کہا: میں نے سیدنا عبداللہ بن مسعود رضی اللہ عنہ کو فرماتے ہوئے سنا، .... پھر یہی (گزشتہ) حدیث بیان کی۔ اور جو حدیث (ابوعبداللہ الحافظ، امام حاکم نے، پہلی سند کے ساتھ) ابوالحسن علی بن احمد التمار سے روایت کی ہے اس میں مذکور ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: اللہ تعالیٰ نے نماز کے بارے میں نیا حکم جاری فرمایا ہے کہ تم لوگ اللہ کے ذکر اور جو (قرآت) تمھارے لیے ضروری ہے اس کے علاوہ کوئی بات نہ کرو۔ اور اللہ کے لیے باادب کھڑے رہو۔ (1)\nامام ابن خزیمہ رحمہ اللہ کی وضاحت:\nیہی حدیث امام محمد بن اسحاق بن خزیمہ (امام ابن خزیمہ رحمہ اللہ) نے ابراہیم بن مسعود بن عبدالحمید الہمدانی سے روایت کی ہے، انھوں نے قاسم بن حکم العرنی سے، انھوں نے سفیان ثوری سے روایت کی ہے۔ اور امام ابن خزیمہ رحمہ اللہ نے اس حدیث سے استدلال کرتے ہوئے فرمایا ہے: یہ حدیث صراحت و وضاحت سے بیان کر رہی ہے کہ نمازیوں کو دوران نماز اللہ تعالیٰ کے ذکر اور جو (قرآت) نمازیوں کے لیے ضروری ہے، اس کے علاوہ کلام (آپسی بات چیت) کرنے سے منع کیا گیا ہے۔ تو جو قرآت نمازی کے لیے ضروری ہے اسے نماز میں ضرور پڑھے۔ پھر انھوں نے صحیح و ثابت حدیث سے استدلال کیا ہے کہ یہ حدیث صراحت سے بیان کرتی ہے کہ نبی کریم صلی اللہ علیہ وسلم نے نمازیوں کو لوگوں کی باتوں (آپسی گفتگو) سے سختی سے منع کیا تھا۔ اور انھیں دوران نماز، تکبیر تسبیح اور قرآن کی قرآت کا حکم دیا تھا، چاہے وہ نمازی؛ امام کے پیچھے (بحیثیت مقتدی) ہوں۔ [حدیث حسب ذیل ہے:]","",{"f":"§حواشی\n(1) اسناده صحيح۔ الاعتبار في الناسخ والمنسوخ من الآثار، للحازمي: ص 70۔"}],[268,"§نماز تو نام ہی تکبیر، تسبیح اور قرآت کا ہے:\n(پہلی سند) یہ روایت ہمیں ابوبکر محمد بن حسن بن فورک نے بیان کی، انھوں نے کہا: ہمیں عبداللہ بن جعفر نے بیان کیا، انھوں نے کہا: ہمیں یونس بن حبیب نے بیان کیا، انھوں نے کہا: ہمیں ابوداؤد الطیالسی نے بیان کیا، انھوں نے کہا: ہمیں حرب بن شداد اور ابان بن یزید نے بیان کیا، ان دونوں نے یحییٰ بن ابی کثیر سے روایت کیا .... (ح)\nوَأَخْبَرَنَا أَبُو عَبْدِ اللَّهِ الْحَافِظُ، وَأَبُو بَكْرٍ أَحْمَدُ بْنُ الْحَسَنِ وَأَبُو عَبْدِ اللَّهِ إِسْحَاقُ بْنُ مُحَمَّدِ بْنِ يُوسُفَ السُّوسِيُّ قَالُوا: نا أَبُو الْعَبَّاسِ مُحَمَّدُ بْنُ يَعْقُوبَ نا أَبُو عُتْبَةَ أَحْمَدُ بْنُ الْفَرَجِ الْحِجَازِيُّ، نا مُحَمَّدُ بْنُ حُمَيْرٍ، نا الْأَوْزَاعِيُّ، عَنْ يَحْيَى بْنِ أَبِي كَثِيرٍ، عَنْ هِلَالِ بْنِ أَبِي مَيْمُونَةَ، عَنْ عَطَاءِ بْنِ يَسَارٍ، قَالَ: حَدَّثَنِي مُعَاوِيَةُ بْنُ الْحَكَمِ السُّلَمِيُّ، قَالَ: بَيْنَا أَنَا مَعَ رَسُولِ اللَّهِ صلی اللہ علیہ وسلم فِي الصَّلَاةِ، إِذْ عَطَسَ رَجُلٌ مِنَ الْقَوْمِ، فَقُلْتُ: يَرْحَمُكَ اللَّهُ، فَحَدَّقَنِي الْقَوْمُ بِأَبْصَارِهِمْ، فَقُلْتُ: وَاثْكَلَ أُمِّيَاهُ، مَا لَكُمْ تَنْظُرُونَ إِلَيَّ؟ قَالَ: فَضَرَبُوا بِأَيْدِيهِمْ عَلَى أَفْخَاذِهِمْ، قَالَ: فَلَمَّا رَأَيْتُهُمْ يُسَكِّتُونِي لَكِنِّي سَكَتُّ، فَلَمَّا فَرَغَ رَسُولُ اللَّهِ صلی اللہ علیہ وسلم مِنَ الصَّلَاةِ دَعَانِي ...... فَبِأَبِي وَأُمِّي رَسُولَ اللَّهِ صلی اللہ علیہ وسلم، مَا رَأَيْتُ مُعَلِّمًا قَبْلَهُ وَلَا بَعْدَهُ أَحْسَنَ تَعْلِيمًا مِنْهُ...... وَاللَّهِ مَا كَهَرَنِي وَلَا ضَرَبَنِي وَلَا سَبَّنِي، قَالَ: إِنَّ صَلَاتَنَا لَا يَصْلُحُ فِيهَا شَيْءٌ مِنْ كَلَامِ النَّاسِ، إِنَّمَا هِيَ التَّكْبِيرُ وَالتَّسْبِيحُ وَتِلَاوَةُ الْقُرْآنِ۔\n(دوسری سند) ہمیں ابوعبداللہ الحافظ (امام حاکم)، ابوبکر احمد بن حسن اور ابوعبداللہ اسحاق بن محمد بن یوسف السوسی نے بیان کیا، ان تینوں نے کہا: ہمیں ابو عباس محمد بن یعقوب نے بیان کیا، انھوں نے کہا: ہمیں ابو عتبہ احمد بن فرج الحجازی نے بیان کیا، انھوں نے کہا: ہمیں محمد بن حمیر نے بیان کیا، انھوں نے کہا: ہمیں اوزاعی نے بیان کیا، انھوں نے یحییٰ بن ابی کثیر سے، انھوں نے ہلال بن ابی میمونہ سے، انھوں نے عطا بن یسار سے روایت کیا، انھوں نے کہا: مجھے سیدنا معاویہ بن حکم السلمی رضی اللہ عنہ نے بیان کیا، انھوں نے فرمایا: میں رسول اللہ صلی اللہ علیہ وسلم کے ساتھ نماز پڑھ رہا تھا کہ ایک شخص نے چھینک مار دی۔ میں نے ’’يَرْحَمُكَ الله‘‘ کہہ دیا۔ لوگ مجھے غصیل آنکھوں سے دیکھنے لگے۔ میں نے کہا: تمھارا بھلا ہو، تم لوگ اس طرح سے میری طرف کیوں دیکھ رہے ہو؟ آپ رضی اللہ عنہ فرماتے ہیں کہ پھر لوگوں نے اپنی رانوں پر ہاتھ مارنا شروع کر دیے۔ میں سمجھ گیا کہ وہ مجھے چپ کرا رہے ہیں، جبکہ میں چپ ہو گیا تھا۔ جب رسول اللہ صلی اللہ علیہ وسلم نماز سے فارغ ہوئے تو آپ صلی اللہ علیہ وسلم نے مجھے بلایا ...... میرے ماں باپ؛ رسول اللہ صلی اللہ علیہ وسلم پر قربان، میں نے آپ سے بڑھ اچھا معلم نہیں دیکھا...... اللہ کی قسم! آپ صلی اللہ علیہ وسلم نے مجھے نہ ڈانٹا، نہ مارا اور نہ ہی برا بھلا کہا۔ بلکہ آپ صلی اللہ علیہ وسلم نے فرمایا: ہماری نماز میں لوگوں کی کوئی بھی گفتگو (بات چیت) جائز نہیں۔ یہ نماز تو تکبیر، تسبیح اور قرآن مجید کی قرآت (سے مرکب) ہے۔ (1)\nیہ الفاظ اوزاعی کی بیان کردہ حدیث کے ہیں۔\nاور اسی حدیث کو فلیح بن سلیمان نے بھی ہلال بن ابی میمونہ سے روایت کیا ہے۔ اور اس حدیث میں یہ الفاظ بیان کیے ہیں کہ ’’نماز تو قرآن کی قرآت اور اللہ تعالیٰ کے ذکر کے لیے ہے۔ جب تم نماز میں ہو تو تمھاری کیفیت ایسی ہی ہونی چاہیے۔‘‘ [اس حدیث کی سند حسب ذیل ہے:]","",{"f":"§حواشی\n(1) اسناده صحيح۔"}],[269,"ہمیں ابوعلی الروذباری نے بیان کیا، انھوں نے کہا: ہمیں ابوبکر بن داسہ نے بیان کیا، انھوں نے کہا: ہمیں ابوداؤد سلیمان بن اشعث السجستانی نے بیان کیا، انھوں نے کہا: ہمیں محمد بن یونس النسائی نے بیان کیا، انھوں نے کہا: ہمیں عبدالملک بن عمرو نے بیان کیا، انھوں نے کہا: ہمیں فلیح بن سلیمان نے بیان کیا، انھوں نے ہلال بن ابی میمونہ سے روایت کیا ..... پھر وہی حدیث بیان کی۔ (1)\nاسی حدیث کو امام مسلم رحمہ اللہ نے صحیح مسلم میں اوزاعی اور حجاج بن ابی عثمان الصواف کی یحییٰ بن ابی کثیر سے بیان کردہ سند کے ساتھ ذکر کیا ہے۔ (2)\nمقتدی نے قرآت نہ کی تو نماز کیسی؟\nاس حدیث میں واضح دلیل ہے کہ مقتدی کی نماز تلاوت قرآن، تکبیر اور تسبیح پر مشتمل ہوتی ہے۔ جیسا کہ انھیں چیزوں پر امام اور منفرد کی نماز مشتمل ہوتی ہے۔ نبی کریم صلی اللہ علیہ وسلم نے جب سیدنا معاویہ بن حکم رضی اللہ عنہ کو یہ تعلیم دی تھی کہ ......\nان کی نماز میں لوگوں کی بات چیت جائز نہیں، یہ تو تکبیر، تسبیح اور قرآت قرآن کا مرکب ہے ...... تب سیدنا معاویہ بن حکم رضی اللہ عنہ اس نماز میں مقتدی ہی تھے، امام یا منفرد نہیں تھے۔ لہذا اس حدیث میں وضاحت ہو گئی کہ جس کلام (بات) سے آپ صلی اللہ علیہ وسلم نے سختی سے منع کیا تھا، وہ لوگوں کا آپس میں گفتگو کرنا ہے، نہ کہ ذکر اور تلاوت۔ ان دونوں کو تو نبی کریم صلی اللہ علیہ وسلم نے نماز کا نام دیا ہے۔\n﴿وَإِذَا قُرِئَ الْقُرْآنُ ...﴾ کا نماز اور خطبہ سے تعلق؟\n(امام بیہقی رحمہ اللہ فرماتے ہیں:) اس شخص کا دعویٰ بھی بے بنیاد ہے جو یہ کہتا ہے کہ یہ آیت ﴿وَإِذَا قُرِئَ الْقُرْآنُ ...﴾ کسی بھی کلام کے لیے عام ہے۔ حالانکہ یہ آیت نماز و غیر نماز اور خطبہ و غیر خطبہ (یعنی نماز و خطبہ اور ان کے علاوہ حالات و اوقات) کے لیے عام ہے۔ ہم نے صحابہ و تابعین کے اقوال کی روشنی میں اس آیت کی تخصیص کی ہے کہ یہ آیت نماز اور خطبہ کے بارے میں نازل ہوئی ہے۔ نماز اور خطبہ کے علاوہ اوقات میں (قرآن کی قرآت ہونے پر) مومن کو استماع و انصات (توجہ سے سننا اور خاموشی اختیار کرنا) ترک کرنے کا اختیار حاصل ہے۔ اسی طرح ہم نے ان اصحاب کے اقوال کی روشنی میں بھی اس آیت کی تخصیص کی ہے؛ جنھوں نے بیان کیا ہے کہ یہ آیت نبی کریم صلی اللہ علیہ وسلم کے پیچھے (دوران نماز) لوگوں کی باہمی گفتگو اور قرآن کی قرآت کرتے ہوئے؛ آواز بلند کرنے سے خاموشی اختیار کرنے کے بارے میں نازل ہوئی ہے۔\nصحیح استدلال وہی ہے جو صحابہ رضی اللہ عنہم نے کیا:\nکیونکہ انھوں نے (نبی کریم صلی اللہ علیہ وسلم کی) بات (خود) سننے اور صورت حال کا (خود) مشاہدہ کرنے کی بنیاد پر اس آیت (کے حکم) کو غیر نماز کی بجائے؛ نماز اور غیر خطبہ کی بجائے؛ خطبہ جمعہ کی طرف منسوب کرنے کا استدلال کیا ہے۔ اسی طرح انھوں نے لوگوں کی گفتگو اور بلند آواز کے علاوہ حالات کی بجائے لوگوں کی گفتگو اور بلند آواز ہی کی طرف اس آیت کو منسوب کرنے کا استدلال کیا ہے۔ (3) اور انھوں نے واضح کیا ہے کہ اللہ تعالیٰ کا ذکر اور مزید جو نماز میں نمازی کے لیے ضروری ہے وہ اس آیت کے حکم میں نہیں آتے۔ اور نہ ہی نماز میں بات چیت کرنا اس آیت کے حکم میں آتا ہے۔\nیا جس نے یہ بیان کیا ہے کہ یہ آیت ذکر، اور نمازی کے لیے نماز میں ضروری الفاظ (قرآت قرآن) پر لاگو نہیں ہوتی۔ اور نہ ہی نماز میں کلام کرنے کی ممانعت ثابت کرتی ہے۔ سیدنا معاویہ بن حکم السلمی رضی اللہ عنہ کی حدیث میں صاحب شریعت (رسول اللہ) صلی اللہ علیہ وسلم کا واضح فرمان موجود ہے کہ کس چیز سے خاموشی اختیار کرنی ہے اور کس کو ادا کرنا ہے، حتی کہ (جس کو ادا کرنا ہے) وہی عمل نماز قرار پایا۔ سیدنا عبادہ بن صامت رضی اللہ عنہ وغیرہ کی حدیث میں وضاحت موجود ہے کہ آپ صلی اللہ علیہ وسلم نے (مقتدی کے لیے) جہری قرآت کو ناپسند کیا اور سورۃ فاتحہ پست آواز میں پڑھنے کا حکم دیا ہے۔ ان تمام (وضاحتی احادیث) کو اپنانا واجب ہے، تا کہ نمازی؛ اللہ کے حکم کی اطاعت کرتے ہوئے (دوران نماز) لوگوں سے گفتگو کرنا اور قرآت میں آواز بلند کرنا ترک کر دے۔ اور وہ رسول اللہ صلی اللہ علیہ وسلم کا بھی فرمان بردار بن جائے کہ جنھوں نے اللہ تعالیٰ کے اس فرمان کی وضاحت فرمائی ہے کہ اس آیت ﴿وَإِذَا قُرِئَ الْقُرْآنُ ...﴾ سے اللہ تعالیٰ کی مراد و مقصود دل ہی دل میں سورۃ فاتحہ پڑھنا ہے، چاہے نمازی؛ مقتدی کی حیثیت سے ہو۔\n﴿وَإِذَا قُرِئَ الْقُرْآنُ ...﴾ سے اگلی آیت پر بھی غور کر لیں:\nپھر جو اللہ تعالیٰ کے فرمان: ﴿وَإِذَا قُرِئَ الْقُرْآنُ فَاسْتَمِعُوا لَهُ وَأَنْصِتُوا﴾ کے بعد ہے، وہ بھی اسی مفہوم پر دلالت کرتی ہے جو سنت (حدیث) میں مذکور ہے۔ اللہ عزوجل نے فرمایا:\n﴿ وَاذْكُرْ رَبَّكَ فِي نَفْسِكَ تَضَرُّعًا وَخِيفَةً وَدُونَ الْجَهْرِ مِنَ الْقَوْلِ بِالْغُدُوِّ وَالْآصَالِ وَلَا تَكُنْ مِنَ الْغَافِلِينَ ﴾ [الاعراف: 205]\n’’اپنے رب کو اپنے دل ہی دل میں عاجزی اور خوف کے ساتھ اور پست آواز سے صبح و شام یاد کرتے رہو، اور غافل نہ ہو جانا۔‘‘\nاگرچہ اس آیت مبارکہ میں، خطاب؛ نبی کریم صلی اللہ علیہ وسلم کے لیے خاص ہے، تب بھی یہاں اس بات کا احتمال موجود ہے کہ اس خطاب کی مخاطب آپ صلی اللہ علیہ وسلم کی امت ہو۔ کیونکہ اس طرح کی بہت سی مثالیں قرآن مجید میں موجود ہیں کہ اللہ تعالیٰ نے مخاطب تو نبی کریم صلی اللہ علیہ وسلم کو کیا ہے لیکن اس سے مراد آپ صلی اللہ علیہ وسلم کی امت ہے۔\nدونوں آیات پر عمل ہونا چاہیے:\nپہلی آیت یعنی: ﴿وَإِذَا قُرِئَ الْقُرْآنُ ...﴾ میں مقتدی کو، قرآن توجہ سے سننے اور خاموشی اختیار کرنے یعنی قرآت میں آواز بلند نہ کرنے کا حکم ہے، اور دوسری آیت ﴿وَاذْكُرْ رَبَّكَ فِي نَفْسِكَ ...﴾ میں دل ہی دل میں، پست آواز کے ساتھ یعنی آواز بلند کیے بغیر فاتحہ و دیگر اذکار کو پڑھنے کا حکم دیا گیا ہے۔ جب مقتدی سورت فاتحہ پڑھتے ہوئے آواز بلند نہیں کرے گا بلکہ اسے پست آواز سے پڑھے گا تو یقیناً وہ ان دونوں آیات میں مذکور، اللہ تعالیٰ کے حکم پر عمل کر لے گا۔\nزید بن اسلم تابعی رحمہ اللہ کی بیان کردہ تفسیر:\nان آیات کا جو معنی و مفہوم ہم نے بیان کیا ہے، تابعی مفسر، امام زید بن اسلم رحمہ اللہ نے بھی اسی طرف اشارہ کیا ہے: [ملاحظہ فرمائیں]","",{"f":"§حواشی\n(1) یہ سند حسن لغیرہ ہے۔ البتہ حدیث صحیح ہے۔\n(2) امام مسلم نے دو الگ الگ اسناد کے ساتھ اس حدیث کو بیان کیا ہے۔ پہلی سند میں حجاج بن ابی عثمان نے یحییٰ بن ابی کثیر سے روایت کیا ہے۔ جو سند اس طرح ہے: ’’حَدَّثَنَا أَبُو جَعْفَرٍ مُحَمَّدُ بْنُ الصَّبَّاحِ وَأَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ........ عَنْ حَجَّاجٍ الصَّوَّافِ عَنْ يَحْيَى بْنِ أَبِي كَثِيرٍ عَنْ هِلَالِ بْنِ أَبِي مَيْمُونَةَ عَنْ عَطَاءِ بْنِ يَسَارٍ عَنْ مُعَاوِيَةَ بْنِ الْحَكَمِ السُّلَمِيِّ قَالَ: بَيْنَا أَنَا أُصَلِّي مَعَ رَسُولِ اللَّهِ صلی اللہ علیہ وسلم ....‘‘ اور دوسری سند ذکر کر کے اسی حدیث کی طرف اشارہ کر دیا ہے۔ اس دوسری سند میں امام اوزاعی نے یحییٰ بن ابی کثیر سے یہی حدیث اسی سند کے ساتھ روایت کی ہے۔ سند اس طرح ہے: ’’حَدَّثَنَا إِسْحَاقُ بْنُ إِبْرَاهِيمَ أَخْبَرَنَا عِيسَى بْنُ يُونُسَ حَدَّثَنَا الْأَوْزَاعِيُّ عَنْ يَحْيَى بْنِ أَبِي كَثِيرٍ بِهَذَا الْإِسْنَادِ نَحْوَهُ‘‘ [صحيح مسلم، كتاب الصلاة، باب تحريم الكلام في الصلاة، حدیث، 33 (537)]\n(3) یعنی صحابہ کرام رضی اللہ عنہم نے ان حالات کو خود دیکھا اور نبی کریم صلی اللہ علیہ وسلم کے فرمان کو خود سنا ہے کہ جن حالات میں اس آیت مبارکہ ﴿وَإِذَا قُرِئَ الْقُرْآنُ ...﴾ کی روشنی میں لوگوں کو نماز میں بولنے سے منع کیا گیا تھا۔ ان صحابہ کرام رضی اللہ عنہم نے اس آیت کو نماز اور خطبہ کے لیے خاص قرار دیا ہے تو انھی صحابہ کرام رضی اللہ عنہم نے نماز اور خطبہ میں محض لوگوں کی گفتگو اور بلند آواز سے ممانعت کے لیے اس آیت کو خاص قرار دیا ہے۔ یعنی جس طرح اس آیت میں خاموشی اختیار کرنے کا حکم اس شخص پر لاگو نہیں ہوتا جو نماز میں نہیں بلکہ اس شخص پر لاگو ہوتا ہے جو نماز میں قرآت سن رہا ہے، تو اسی طرح اس آیت کا حکم دوران نماز قرآت کرنے پر نہیں بلکہ گفتگو کرنے اور آواز بلند کرنے پر لاگو ہوتا ہے۔"}],[270,"ہمیں ابوعبداللہ الحافظ (امام حاکم) نے بیان کیا، انھوں نے کہا: ہمیں ابوعلی الحافظ نے بیان کیا، انھوں نے کہا: ہمیں ابو عمرو الحرشی نے بیان کیا، انھوں نے کہا: ہمیں فضل بن محمد الشعرانی نے بیان کیا، انھوں نے کہا: ہمیں ابراہیم بن حمزہ نے بیان کیا، انھوں نے کہا: ہمیں عبدالعزیز بن محمد نے بیان کیا، انھوں نے کہا: میں نے اللہ تعالیٰ کے فرمان ﴿وَإِذَا قُرِئَ الْقُرْآنُ فَاسْتَمِعُوا لَهُ وَأَنْصِتُوا﴾ کے متعلق امام زید بن اسلم رحمہ اللہ کو فرماتے ہوئے سنا کہ (اس میں مخاطب) وہ شخص ہے جو امام کے پیچھے (بحیثیت مقتدی) ہوتا ہے۔ اور اللہ تعالیٰ کے فرمان: ﴿وَاذْكُرْ رَبِّكَ فِي نَفْسِكَ﴾ .. کے متعلق زید بن اسلم رحمہ اللہ نے کہا: اپنے رب کا ذکر کرو اور اپنے دل میں پست آواز سے کرو۔\nمقتدی کو بتایا جا رہا ہے کہ اسے انصات اور ذکر، دونوں کا بیک وقت حکم ہے۔ تو انصات کا حکم بلند آواز سے قرآت کرنے کے ساتھ تعلق رکھتا ہے، اس سے مراد دل میں پست آواز کے ساتھ ذکر کرنے کو ترک کر دینا نہیں ہے۔\nانصات کا مطلب ’’زبان بندی‘‘ نہیں:\nاس شخص کی بات کی بھی کوئی حیثیت نہیں؛ جو سمجھتا ہے کہ انصات تو لغت میں سکوت کو کہتے ہیں۔ تو شریعت کے عرف میں بھی اس کا اطلاق، خاموش رہنے اور بولنا بالکل ترک کرنے پر ہی ہوگا۔ جبکہ متعدد صحیح احادیث ایسی موجود ہیں جن سے واضح ہوتا ہے کہ انصات اور سکوت کا مطلب (نماز میں) آواز بلند کرنے کی بجائے پست رکھنا اور باہمی گفتگو کی بجائے دل ہی دل میں ذکر (قرآت) کرنا ہے۔ اس کے دلائل حسب ذیل ہیں:"],[271,"§پہلی دلیل:\n(پہلی سند) ہمیں ابو زکریا بن ابی اسحاق (یحییٰ بن ابراہیم) نے بیان کیا، انھوں نے کہا: ہمیں ابو احمد حمزہ بن عباس بن فضل نے بیان کیا .... ح\nوَأَخْبَرَنَا أَبُو عَلِيٍّ الْحَسَنُ بْنُ أَحْمَدَ بْنِ إِبْرَاهِيمَ بْنِ شَاذَانَ بِبَغْدَادَ، أنا حَمْزَةُ بْنُ مُحَمَّدِ بْنِ الْعَبَّاسِ، نا عَبَّاسُ بْنُ مُحَمَّدٍ الدُّورِيُّ، نا أَحْمَدُ بْنُ إِسْحَاقَ الْحَضْرَمِيُّ، نا عَبْدُ الْوَاحِدِ بْنُ زِيَادٍ، نا عُمَارَةُ بْنُ الْقَعْقَاعِ، ح . . .\n(دوسری سند) ہمیں ابو علی الحسن بن احمد بن ابراہیم بن شاذان نے بغداد میں بیان کیا تھا، انھوں نے کہا: ہمیں حمزہ بن محمد بن عباس نے بیان کیا، انھوں نے کہا: ہمیں عباس بن محمد الدوری نے بیان کیا، انھوں نے کہا: ہمیں احمد بن اسحاق الحضرمی نے بیان کیا، انھوں نے کہا: ہمیں عبد الواحد بن زیاد نے بیان کیا، انھوں نے کہا: ہمیں عمارہ بن قعقاع نے بیان کیا، .... ح\nوَأَخْبَرَنَا أَبُو عَبْدِ اللهِ الْحَافِظُ، أنا أَبُو عَلِيٍّ الْحُسَيْنُ بْنُ عَلِيٍّ الْحَافِظُ، نا عَبْدُ اللهِ بْنُ مُحَمَّدٍ الْأَزْدِيُّ، نا إِسْحَاقُ بْنُ إِبْرَاهِيمَ، أنا جَرِيرٌ، عَنْ عُمَارَةَ بْنِ الْقَعْقَاعِ، عَنْ أَبِي زُرْعَةَ بْنِ عَمْرِو بْنِ جَرِيرٍ، عَنْ أَبِي هُرَيْرَةَ، قَالَ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِذَا كَبَّرَ فِي الصَّلَاةِ سَكَتَ هُنَيْهَةً قَبْلَ أَنْ يَقْرَأَ، فَقُلْتُ: يَا رَسُولَ اللهِ، بِأَبِي أَنْتَ وَأُمِّي، أَرَأَيْتَ سُكُوتَكَ بَيْنَ التَّكْبِيرِ وَالْقِرَاءَةِ، مَا هُوَ؟ قَالَ: أَقُولُ: اللَّهُمَّ بَاعِدْ بَيْنِي وَبَيْنَ خَطَايَايَ كَمَا بَاعَدْتَ بَيْنَ الْمَشْرِقِ وَالْمَغْرِبِ، اللَّهُمَّ نَقِّنِي مِنْ خَطَايَايَ كَمَا يُنَقَّى الثَّوْبُ الْأَبْيَضُ مِنَ الدَّنَسِ، اللَّهُمَّ اغْسِلْنِي مِنْ خَطَايَايَ بِالْمَاءِ وَالثَّلْجِ وَالْبَرَدِ۔\nلَفْظُ حَدِيثِ جَرِيرٍ، وَفِي رِوَايَةِ عَبْدِ الْوَاحِدِ: أَرَأَيْتَ إِسْكَاتَكَ بَيْنَ التَّكْبِيرِ وَالْقِرَاءَةِ مَا تَقُولُ؟\n(تیسری سند) ہمیں ابو عبداللہ الحافظ امام حاکم نے بیان کیا، انھوں نے کہا: ہمیں ابو علی حسین بن علی الحافظ نے بیان کیا، انھوں نے کہا: ہمیں عبداللہ بن محمد الازدی نے بیان کیا، انھوں نے کہا: ہمیں اسحاق بن ابراہیم نے بیان کیا، انھوں نے کہا: ہمیں جریر بن عبدالحمید بن قرط نے بیان کیا، انھوں نے عمارہ بن قعقاع سے روایت کیا، انھوں نے ابو زرعہ بن عمرو بن جریر سے، انھوں نے سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت کیا، انھوں نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم جب نماز میں تکبیر (تحریمہ) کہتے تو قرآت کرنے سے پہلے کچھ دیر سکوت اختیار کرتے (خاموش رہتے)، میں نے عرض کیا: اللہ کے رسول، میرے ماں باپ آپ پر قربان! تکبیر اور قرآت کے درمیان آپ کے سکوت (خاموش رہنے) کی کیا وجہ ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: (سکوت کے دوران) میں پڑھتا ہوں: ’’اللَّهُمَّ بَاعِدْ بَيْنِي وَبَيْنَ خَطَايَايَ كَمَا بَاعَدْتَ بَيْنَ الْمَشْرِقِ وَالْمَغْرِبِ، اللَّهُمَّ نَقِّنِي مِنْ خَطَايَايَ كَمَا يُنَقَّى الثَّوْبُ الْأَبْيَضُ مِنَ الدَّنَسِ، اللَّهُمَّ اغْسِلْنِي مِنْ خَطَايَايَ بِالْمَاءِ وَالثَّلْجِ وَالْبَرَدِ‘‘۔ (1)\nیہ الفاظ جریر کی (یعنی تیسری سند سے مذکور) حدیث کے ہیں۔ اور عبدالواحد بن زیاد کی (یعنی دوسری سند سے مذکور) روایت کے الفاظ یہ ہیں:\n’’أَرَأَيْتَ إِسْكَاتَكَ بَيْنَ التَّكْبِيرِ وَالْقِرَاءَةِ مَا تَقُولُ؟‘‘\n’’اللہ کے رسول! تکبیر اور قرآت کے درمیان آپ کے اسکات (خاموشی) میں آپ کیا پڑھتے ہیں؟‘‘\nاس حدیث کو امام بخاری رحمہ اللہ نے صحیح البخاری میں موسیٰ بن اسماعیل عن عبدالواحد بن زیاد کی سند کے ساتھ روایت کیا ہے۔ (2) اور امام مسلم رحمہ اللہ نے ’’زہیر بن حرب عن جریر‘‘ اور ’’عن ابی کامل عن عبدالواحد بن زیاد‘‘ کی سند کے ساتھ روایت کیا ہے۔ (3)\nحدیث کا واضح مفہوم اور ماہرین لغت کا بیان:\nیہ صحیح حدیث وضاحت کرتی ہے کہ بعض اوقات انصات سے مراد جہر کو ترک کرنا (یعنی آواز پست رکھنا) ہوتا ہے۔ جب جہر سے انصات کرنے والا (یعنی بلند آواز کی بجائے خاموشی اختیار کرنے والا) اللہ تعالیٰ کا ذکر کر رہا ہو یا قرآن مجید کی قرآت کر رہا ہو تو ایسی صورت میں عرب (اہل زبان) کے ہاں، سکوت اور انصات کے معانی میں کوئی فرق نہیں ہے۔ (4)\nسیدنا ابو ہریرہ رضی اللہ عنہ نے نبی کریم صلی اللہ علیہ وسلم سے پوچھا تھا: آپ تکبیر اور قرآت کے درمیان سکوت میں کیا پڑھتے ہیں؟ تو نبی کریم صلی اللہ علیہ وسلم نے یہ نہیں فرمایا تھا کہ میں ساکت نہیں ہوتا (5) بلکہ آپ صلی اللہ علیہ وسلم نے سیدنا ابو ہریرہ رضی اللہ عنہ کو وہ دعا بتائی، جو آپ صلی اللہ علیہ وسلم اس سکوت میں پڑھتے تھے۔","",{"f":"§حواشی\n(1) اسنادہ صحیح۔\n(2) صحیح البخاری، کتاب الاذان، باب ما یقول بعد التکبیر، حدیث، 744۔\n(3) صحیح مسلم، کتاب المساجد و مواضع الصلاۃ، باب ما یقال بین تکبیرۃ الاحرام و القراءۃ، حدیث، 147 - (598)۔\n(4) جیسا کہ اس حدیث کے الفاظ سے واضح ہو رہا ہے کہ سیدنا ابو ہریرہ رضی اللہ عنہ نے رسول اللہ صلی اللہ علیہ وسلم سے پوچھا تھا: اللہ کے رسول! آپ ’’سکوت‘‘ (اور دوسری روایت کے الفاظ کے مطابق) آپ ’’اسکات‘‘ میں کیا پڑھتے ہیں؟ تو نبی کریم صلی اللہ علیہ وسلم نے وہ دعا بیان کی جو آپ صلی اللہ علیہ وسلم پڑھتے تھے۔ یعنی سکوت یا اسکات کا لفظ اس معنی میں استعمال ہوا ہے کہ انسان آواز بلند کیے بغیر کچھ پڑھ رہا ہو۔ اگر سکوت سے مراد: بالکل خاموشی اختیار کرنا اور زبان سے کچھ ادا نہ کرنا ہوتا تو سیدنا ابو ہریرہ رضی اللہ عنہ ان الفاظ کے ساتھ سوال نہ کرتے، اور اگر انھوں نے سوال کر دیا تھا تو پھر نبی کریم صلی اللہ علیہ وسلم دعا بیان کرنے کی بجائے فرماتے کہ میں تو سکوت اختیار کرتا ہوں، زبان کو حرکت نہیں دیتا۔ چونکہ آپ صلی اللہ علیہ وسلم جس دورانیہ میں دعا پڑھتے تھے، اسے آپ صلی اللہ علیہ وسلم نے سکوت قرار دیا ہے تو معلوم ہوا کہ سکوت یا اسکات سے مراد: کچھ بھی نہ بولنا اور زبان بند رکھنا ہی نہیں بلکہ اس سے مراد: آواز بلند کیے بغیر پست آواز سے کچھ پڑھنا، وظیفہ یا قرآت کرنا بھی ہوتا ہے۔\n(5) یعنی آپ صلی اللہ علیہ وسلم نے یہ نہیں فرمایا کہ سکوت کرنا ساکت ہونا تو زبان کی حرکت کو روک لینے اور کچھ بھی نہ بولنے کو کہتے ہیں، اور میں تو سکوت نہیں کرتا، بلکہ میں تو یہ دعا پڑھتا ہوں۔ اور آپ صلی اللہ علیہ وسلم نے سیدنا ابو ہریرہ رضی اللہ عنہ کو یہ بھی نہیں فرمایا تھا کہ تکبیر اور قرآت کے درمیانی وقفے کو سکوت مت کہو۔ کیونکہ اس وقفے میں فلاں فلاں دعا پڑھی جاتی ہے۔ یعنی اس حدیث سے یہ وضاحت ملتی ہے کہ انسان آواز بلند کیے بغیر کچھ پڑھ رہا ہو، تو اسے بھی سکوت کہتے ہیں۔"}],[272,"§دوسری دلیل:\nہمیں ابو عبداللہ الحافظ امام حاکم نے بیان کیا، انھوں نے کہا: ہمیں احمد بن جعفر القطیعی نے بیان کیا، انھوں نے کہا: ہمیں عبداللہ بن احمد بن حنبل نے بیان کیا، انھوں نے کہا: مجھے میرے والد محترم امام احمد بن حنبل نے بیان کیا، انھوں نے کہا: ہمیں اسماعیل بن ابراہیم ابن علیہ نے بیان کیا، انھوں نے محمد بن اسحاق بن یسار سے روایت کیا، انھوں نے کہا: مجھے محمد بن ابراہیم نے بیان کیا، انھوں نے ابو سلمہ بن عبدالرحمن الزہری اور ابو امامہ بن سہل سے روایت کیا، انھوں نے سیدنا ابو ہریرہ اور سیدنا ابو سعید خدری رضی اللہ عنہما سے روایت کیا، ان دونوں نے فرمایا: ہم نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: جس شخص نے جمعہ کے روز غسل کیا، مسواک کی، اگر میسر ہے تو خوشبو لگائی اور اچھا (صاف ستھرا) لباس پہنا، پھر وہ مسجد میں آیا اور اس نے لوگوں کی گردنیں نہ پھلانگیں، پھر جس قدر اللہ نے توفیق دی؛ اس نے نماز (نفل) پڑھی، پھر جب امام آیا تو اس شخص نے انصات کیا (یعنی خاموش رہا) حتیٰ کہ نماز جمعہ ادا کر لی۔ تو یہ جمعہ اس کے لیے گزشتہ جمعہ سے اس جمعہ تک کے گناہوں کا کفارہ بن جاتا ہے۔ پھر سیدنا ابو ہریرہ رضی اللہ عنہ نے فرمایا: اس کے ساتھ مزید تین دن کا کفارہ بھی بن جاتا ہے۔ کیونکہ اللہ تعالیٰ نے ایک نیکی کا بدلہ دس گنا رکھا ہے۔ (1)","",{"f":"§حواشی\n(1) اسنادہ حسن۔ صحیح ابن خزیمہ: حدیث، 1762 - صحیح ابن حبان: 16/7، حدیث، 2778 - مستدرک حاکم: 419/1، حدیث، 1046 - شرح معانی الآثار، للطحاوی: 368/1۔ اس حدیث میں انصات کا دورانیہ نماز مکمل ہونے تک ہے۔ حالانکہ نماز میں تو اس شخص نے زبان کی حرکت بالکل بند نہیں رکھی، اس نے نماز کی قرآت، اذکار اور تسبیحات پڑھی ہیں۔ پھر بھی اس دورانیے کو نبی کریم صلی اللہ علیہ وسلم نے انصات کا نام دیا ہے۔"}],[273,"§تیسری دلیل:\nہمیں ابو طاہر محمد بن محمد الفقیہ نے بیان کیا، انھوں نے کہا: ہمیں ابو حامد احمد بن محمد بن یحییٰ بن بلال نے بیان کیا، انھوں نے کہا: ہمیں ابو الازہر احمد بن ازہر العبدی نے بیان کیا، انھوں نے کہا: ہمیں یعقوب بن ابراہیم بن سعد نے بیان کیا، انھوں نے کہا: ہمیں میرے والد محترم ابراہیم بن سعد نے بیان کیا، انھوں نے محمد بن اسحاق بن یسار سے روایت کیا، انھوں نے کہا: مجھے محمد بن ابراہیم تیمی نے بیان کیا، انھوں نے عمران بن ابی یحییٰ سے، انھوں نے عبداللہ بن کعب بن مالک سے، انھوں نے سیدنا ابو ایوب انصاری رضی اللہ عنہ سے روایت کیا، انھوں نے فرمایا: میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: جس شخص نے جمعہ کے روز غسل کیا اور اگر میسر ہے تو خوشبو لگائی، اور اچھا لباس پہنا، پھر وہ گھر سے نکلا حتیٰ کہ مسجد میں پہنچ گیا، پھر اس نے نوافل پڑھے اور کسی کو اذیت نہیں دی۔ پھر انصات کیا (یعنی خاموشی اختیار کی)، حتیٰ کہ نماز جمعہ ادا کر لی۔ تو اس کا یہ جمعہ، گزشتہ جمعہ سے اس جمعہ کے دوران کیے گئے گناہوں کا کفارہ بن جاتا ہے۔ (1)\nمزید دلائل:\nاور اسی طرح سیدنا سلمان فارسی رضی اللہ عنہ وغیرہ کی حدیث میں بھی مذکور ہے۔ (2)\nبعض روایات میں الفاظ یہ ہیں: «ثُمَّ يُنْصِتُ حَتَّى يَقْضِيَ الْإِمَامُ صَلَاتَهُ» ’’وہ شخص انصات کرے، یعنی: خاموشی اختیار کرے، حتیٰ کہ امام نماز مکمل کر لے۔‘‘ (3)\nدلائل کی رو سے انصات کی وضاحت:\nنبی کریم صلی اللہ علیہ وسلم نے ان احادیث میں جمعہ کے روز امام کے آنے (یعنی خطبہ شروع کرنے) سے نماز مکمل کرنے تک ’’انصات‘‘ کا اجر بیان فرمایا ہے۔ حالانکہ یہ بات معلوم شدہ اور واضح ہے کہ آپ صلی اللہ علیہ وسلم کا مقصد یہ نہیں تھا کہ امام تکبیر تحریمہ، ایک رکن سے دوسرے رکن کی طرف منتقل ہونے کے لیے تکبیرات، رکوع و سجود کی تسبیحات، رکوع سے اٹھ کر ذکر، تشہد، دعائیں اور سلام وغیرہ نہ کہے (زبان بند اور خاموش رہے)۔ بلکہ آپ صلی اللہ علیہ وسلم کا صرف مقصد یہ تھا کہ لوگ گفتگو نہ کریں، آپس میں ایک دوسرے سے بات چیت نہ کریں، حتیٰ کہ امام اپنی نماز مکمل کر لے۔ (4)\nسکوت اور انصات:\nاسی طرح ’’سکوت‘‘ سے آپ صلی اللہ علیہ وسلم کی مراد سورۃ فاتحہ سے مکمل خاموشی (یعنی فاتحہ نہ پڑھنا) نہیں ہے۔ اس میں دلیل ہے کہ ’’انصات‘‘ کا اطلاق بلند آواز اور لوگوں کی بات چیت سے رکنے پر ہوتا ہے۔ اگرچہ وہ انسان سری نماز میں\n⇐⇐ دُهْنِهِ أَوْ يَمَسُّ مِنْ طِيبِ بَيْتِهِ ثُمَّ يَخْرُجُ فَلَا يُفَرِّقُ بَيْنَ اثْنَيْنِ ثُمَّ يُصَلِّي مَا كُتِبَ لَهُ ثُمَّ يُنْصِتُ إِذَا تَكَلَّمَ الْإِمَامُ إِلَّا غُفِرَ لَهُ مَا بَيْنَهُ وَبَيْنَ الْجُمُعَةِ الْأُخْرَى۔ [صحیح البخاری، کتاب الجمعۃ، باب الدہن للجمعۃ، حدیث، 883] 2- حَدَّثَنَا سَلْمَانُ الْفَارِسِيُّ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: مَنِ اغْتَسَلَ يَوْمَ الْجُمُعَةِ وَتَطَهَّرَ بِمَا اسْتَطَاعَ مِنْ طُهْرٍ ثُمَّ ادَّهَنَ أَوْ مَسَّ مِنْ طِيبٍ ثُمَّ رَاحَ فَلَمْ يُفَرِّقْ بَيْنَ اثْنَيْنِ فَصَلَّى مَا كُتِبَ لَهُ ثُمَّ إِذَا خَرَجَ الْإِمَامُ أَنْصَتَ غُفِرَ لَهُ مَا بَيْنَهُ وَبَيْنَ الْجُمُعَةِ الْأُخْرَى۔ [صحیح البخاری، کتاب الجمعۃ، باب لا یفرق بین اثنین یوم الجمعۃ، حدیث، 910]\nقرآت، یا دل ہی دل میں کوئی ذکر کر رہا ہو۔ (5)","",{"f":"§حواشی\n(1) حدیث حسن۔ مسند احمد بن حنبل: 420/5 - صحیح ابن خزیمہ، حدیث، 1775 - المعجم الکبیر للطبرانی: 161/4، حدیث، 4007، 4008 - کتاب الجمعۃ و فضلہا، للمروزی: ص، 63، حدیث، 37۔\n(2) سیدنا سلمان الخیر فارسی رضی اللہ عنہ کی بیان کردہ حدیث مبارکہ صحیح البخاری میں دو مقامات پر مذکور ہے۔ دیکھئے: 1- عَنْ سَلْمَانَ الْفَارِسِيِّ رَضِيَ اللهُ عَنْهُ، قَالَ: قَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: لَا يَغْتَسِلُ رَجُلٌ يَوْمَ الْجُمُعَةِ وَيَتَطَهَّرُ مَا اسْتَطَاعَ مِنْ طُهْرٍ وَيَدَّهِنُ مِنْ ⇐\n(3) یعنی بعض احادیث میں مقتدی کے، نماز پورا کرنے کا ذکر ہے اور بعض میں امام کے، نماز پورا کرنے کا ذکر ہے۔ اور دونوں صورتوں میں آپ صلی اللہ علیہ وسلم نے لفظ ’’انصات‘‘ ہی استعمال فرمایا ہے جو قرآن مجید کی آیت مبارکہ میں استعمال ہوا ہے۔\n(4) اگر قرآن مجید کی آیت میں بیان شدہ لفظ ’’انْصِتُوا‘‘ سے؛ بالکل خاموشی اختیار کرنا اور زبان کو بالکل حرکت نہ دینا، مراد لیا جائے تو اس حدیث مبارکہ میں خطبہ جمعہ شروع ہونے سے نماز مکمل ہونے تک بھی ’’انصات‘‘ ہی کو مشروع کیا گیا ہے۔ تو پھر یہاں بھی کہنا چاہیے کہ کوئی شخص، حتیٰ کہ امام بھی جمعہ کے روز خطبہ جمعہ کے آغاز سے نماز مکمل ہونے تک کوئی بات نہ کریں، کوئی تکبیر نہ بولیں، نماز میں رکوع و سجود کی تسبیحات اور تشہد وغیرہ بھی نہ پڑھیں، بلکہ چپ چاپ، زبان کی حرکت روک کر ساری نماز ادا کریں، کیونکہ انصات کا مطلب تو چپ ہونا، زبان کو بالکل حرکت نہ دینا اور کچھ بھی نہ بولنا ہے۔ جبکہ ایسا وہ احباب بھی نہیں کہتے جو قرآن مجید کے لفظ ’’انصتوا‘‘ کا مطلب ’’چپ رہو، کچھ نہ بولو، زبان کو حرکت نہ دو‘‘ وغیرہ وغیرہ کرتے ہیں۔ معزز قارئین! حدیث مبارکہ سے انصات کا مطلب متعین ہو رہا ہے کہ انصات سے مراد ہے: صرف آواز بلند کرنے سے رکنا، اور پست آواز میں پڑھنا ہے۔\n(5) یعنی: اگر کوئی شخص دل ہی دل میں کوئی ذکر کر رہا ہے، یا آہستہ آواز سے دل ہی دل میں قرآت کر رہا ہے تو اس کا یہ عمل انصات کے منافی نہیں ہے۔ کیونکہ انصات سے مراد بالکل زبان کی حرکت بند کرنا نہیں بلکہ آواز بلند کیے بغیر پڑھنا ہے۔ ظہر و عصر کی نماز، سری (یعنی پست آواز والی) نمازیں ہیں، ان دونوں نمازوں میں امام بلند آواز سے قرآت نہیں کرتا، تو ان نمازوں میں بھی مقتدی کو انصات کا حکم ہے اور اس حکم کی وضاحت اس طرح ہے کہ دل ہی دل میں پڑھیں۔ بالکل خاموشی اور زبان کو بے حرکت کرنا مقصود نہیں ہے۔ جیسا کہ خلیفہ راشد، بدری صحابی سیدنا علی رضی اللہ عنہ نے بیان فرمایا ہے۔ دیکھئے حدیث نمبر: 273۔"}],[274,"ہمیں ابو عبداللہ الحافظ امام حاکم نے بیان کیا، انھیں ابو علی حسین بن علی الحافظ نے بیان کیا، انھوں نے کہا: ہمیں ابو محمد عبداللہ بن محمد دینوری نے بیان کیا، انھوں نے کہا: ہمیں محمد بن مغیرہ بن عبدالرحمن الحرانی نے بیان کیا، انھوں نے کہا: ہمیں حسین بن محمد بن اعین نے بیان کیا، انھوں نے کہا: ہمیں معقل بن عبیداللہ نے بیان کیا، انھوں نے ابن شہاب زہری سے، انھوں نے عبیداللہ بن ابی رافع سے روایت کیا کہ سیدنا علی بن ابی طالب رضی اللہ عنہ نے فرمایا: سنت یہ ہے کہ امام ظہر کی نماز کی پہلی دو رکعات میں سورت فاتحہ اور کوئی دوسری سورت، سری (آہستہ آواز سے) اپنے دل ہی دل میں پڑھے، اور اس کے پیچھے (مقتدی) انصات کریں، اور اپنے اپنے دل میں پڑھیں۔ اور آخری دو رکعات میں امام سورت فاتحہ پڑھے، مغفرت کی دعا کرے اور اللہ تعالیٰ کا ذکر کرے۔ پھر عصر کی نماز میں بھی اسی طرح کرے۔ (1)\nسیدنا علی رضی اللہ عنہ کی زبانی، انصات کی وضاحت:\nسیدنا علی رضی اللہ عنہ کے فرمان: ’’وَيُنْصِتُونَ مَنْ خَلْفَهُ وَيَقْرَأُونَ فِي أَنْفُسِهِم‘‘ (یعنی: امام کے پیچھے مقتدی انصات کریں، اور اپنے اپنے دل میں پڑھیں) میں بھی یہی دلیل ہے کہ انصات سے مراد جہر کو ترک کرنا (یعنی آواز بلند نہ کرنا)۔ یعنی نمازی (مقتدی) قرآت کرے تو اپنی قرآت کو بلند نہ کرے۔\nامام کے سکتہ میں قرآت کرنا:\n(امام بیہقی رحمہ اللہ فرماتے ہیں:) جس شخص نے امام کی قرآت کے وقت خاموش رہنے اور امام کی خاموشی کے وقت قرآت کرنے کو اختیار کیا ہے؛ تاکہ قرآن مجید کی آیت میں، قرآن کی قرآت کے وقت جس انصات کا حکم دیا گیا ہے اس کا حکم بھی بہتر طریقے سے پورا ہو جائے اور انصات و قرآت؛ دونوں کو اپناتے ہوئے کتاب و سنت پر اکٹھا عمل ہو جائے۔ اس شخص پر اعتراض تو نہیں کیا جا سکتا، لیکن اسے یہ بات ذہن نشین رکھنی چاہیے کہ ایسی مثالیں بھی موجود ہیں کہ امام کے سکوت کے دورانیہ میں قرآت کرنا ممکن بھی ہوتا ہے اور ممکن نہیں بھی ہوتا۔ اور اسے یہ بات بھی ذہن نشین رکھنی چاہیے کہ امام کے دو سکتوں کے متعلق مروی روایت؛ دوسری رکعت کے قیام میں سکتہ نہ ہونے کی روایت کے معارض بھی ہے۔ (2) اور تکبیر اولیٰ اور فاتحہ کے درمیان ایک سکتہ کرنے اور پھر (فاتحہ سے پہلے اور اس کے بعد) دو سکتوں والی احادیث، محدثین کے ہاں اس حدیث کی نسبت زیادہ ثابت و صحیح ہیں جس حدیث (یعنی: امام کے پیچھے قرآت سے ممانعت والی) سے استدلال کر کے یہ لوگ تمام نمازوں میں امام کے پیچھے قرآت ترک کرنے کا کہتے ہیں۔ (3)\nامام کے دو سکتے اور مقتدی کی فاتحہ:\nامام کی قرآت کے وقت انصات کرنے اور امام کے سکوت کے وقت فاتحہ پڑھنے کا موقف ان صحابہ کرام رضی اللہ عنہم، تابعین عظام رحمہم اللہ اور ان کے بعد آنے والے (ائمہ کرام رحمہم اللہ) کا ہے، جن کے اسماء گرامی کا ذکر ہم نے اس باب سے پچھلے باب میں کر دیا ہے۔ ان تمام کا موقف یہ ہے کہ اگر امام دوسری رکعت میں سورت فاتحہ شروع کرنے سے پہلے سکتہ نہیں کرتا، بلکہ اسے پڑھ لینے کے بعد سکتہ کرتا ہے تو اس سکتہ میں بھی پڑھنے والے کے لیے سورت فاتحہ پڑھنا ممکن ہے۔ پھر اگر اس کے لیے (اس سکتہ کے دوران) سورت فاتحہ پڑھنا ممکن نہ ہو تو وہ اپنے دل ہی دل میں امام کے ساتھ ہی پڑھ لے، جیسا کہ رسول اللہ صلی اللہ علیہ وسلم نے سیدنا عبادہ بن صامت رضی اللہ عنہ وغیرہ کی حدیث میں حکم دیا ہے۔ (4) اور جن کے نام ہم نے ذکر کیے ہیں ان صحابہ کرام رضی اللہ عنہم نے بھی اسی بات کا حکم دیا ہے۔ (5)\nمقتدی کے انصات کی صورت:\nاور مقتدی کے سورت فاتحہ کو سری (آہستہ آواز سے) پڑھنے سے وہ امام کی قرآت کے سماع کے حکم سے خارج نہیں ہو جائے گا (یعنی فاتحہ پڑھنے کے ساتھ ساتھ وہ امام کی قرآت کا سماع بھی کر رہا ہوگا)۔ اور یہی صورت مقتدی کے انصات کی ہے، جیسا کہ ہم نے اس کی وضاحت کے متعلق دلائل ذکر کر دیے ہیں۔ (6) اور تکبیر اولیٰ اور قرآت کے درمیان سکوت کی حدیث بھی ہم نے بیان کی ہے۔ (7)","",{"f":"§حواشی\n(1) اسنادہ ضعیف۔\n(2) اگر اسے سکتوں میں ہی قرآت کرنی ہے تو دوسری رکعت میں یہ شخص امام کے پیچھے کس طرح قرآت کرے گا؟ کیونکہ رسول اللہ صلی اللہ علیہ وسلم دوسری رکعت کے لیے کھڑے ہوتے تو فاتحہ سے قرآت شروع کر دیتے، سکتہ نہیں کرتے تھے۔ [صحیح مسلم، حدیث 599 - صحیح ابن خزیمہ، حدیث، 1603 - مستدرک حاکم، حدیث، 782] لہذا یہ بات تسلیم کرنی ہی ہوگی اگر سکتہ میں قرآت کرنا ممکن نہ ہو، یا امام سکتہ ہی نہ کرے تو مقتدی کو امام کی قرآت کے ساتھ ساتھ قرآت کر لینی چاہیے یہ عمل ’’انصات‘‘ کے منافی نہیں ہے۔\n(3) یعنی: سکتوں میں قرآت کرنا بھی ثابت اور صحیح ہے، لیکن سکتہ میسر نہ آنے کی صورت میں امام کے ساتھ ساتھ قرآت کرنے میں کوئی حرج نہیں ہے۔\n(4) دیکھئے سابقہ صفحات میں حدیث نمبر: 111، 112۔\n(5) دیکھئے حدیث نمبر: 200۔\n(6) یعنی: جب امام قرآت کر رہا ہو اور اس کے پیچھے مقتدی سورت فاتحہ پڑھ رہا ہو تو اس کا مطلب یہ ہرگز نہیں کہ وہ امام کی قرآت نہیں سن رہا، ظاہر ہے کہ وہ فاتحہ بھی پڑھ رہا ہے اور امام کی قرآت بھی سن رہا ہے۔ ایسی صورت کو ہی انصات کہتے ہیں۔ لہذا قرآن مجید کے الفاظ ’’وَانْصِتُوا‘‘ کو اگر نماز کے ساتھ منسلک کیا جائے تو اس سے مراد یہ نہیں ہوگا کہ مقتدی خود کچھ بھی نہ پڑھے، بلکہ اس سے مراد یہ ہوگا کہ مقتدی امام کی قرآت کو بھی سنے اور جس قرآت، یعنی سورت فاتحہ کا اسے حکم ہے اس قرآت کو بھی ادا کرے۔\n(7) یعنی حدیث میں جس موقع کو سکوت کہا گیا ہے اس میں بھی قرآت ہے۔ تکبیر اولیٰ اور جہری قرآت کے درمیان خاموشی (وقفے) کو سکوت کہا گیا ہے، پھر اسی سکوت کے متعلق وضاحت کی گئی ہے کہ میں اس میں ’’اللَّهُمَّ بَاعِدْ بَيْنِي وَبَيْنَ خَطَايَايَ . . .‘‘ پڑھتا ہوں۔ دیکھئے حدیث نمبر: 270۔ لہذا سکوت اور انصات کا ایک ہی مطلب و مقصد ہو سکتا ہے، کہ انسان بالکل زبان بند نہ رکھے بلکہ آواز بند رکھے، آواز کو پست رکھتے ہوئے کچھ پڑھنا سکوت اور انصات دونوں کے منافی نہیں ہے۔ واللہ اعلم"}],[275,"§امام کے دو سکتوں کی حدیث:\n§دو سکتوں کے بارے میں مندرجہ ذیل حدیث ہے:\nہمیں ابو عبداللہ الحافظ نے بیان کیا، انھوں نے کہا: ہمیں ابو العباس محمد بن یعقوب نے بیان کیا، انھوں نے کہا: ہمیں اسماعیل بن اسحاق القاضی نے بیان کیا، انھوں نے کہا: ہمیں محمد بن منہال نے بیان کیا، انھوں نے کہا: ہمیں یزید بن زریع نے بیان کیا، انھوں نے کہا: ہمیں یونس بن عبید نے بیان کیا، انھوں نے کہا: حسن بصری نے ہمیں بتایا کہ سیدنا سمرہ بن جندب رضی اللہ عنہ جب تکبیر تحریمہ کہتے تو کچھ دیر سکوت (سکتہ) کرتے اور جب سورت کی قرآت کر لیتے تب بھی کچھ دیر سکوت کرتے (خاموشی اختیار کرتے)۔ سیدنا عمران بن حصین رضی اللہ عنہ نے اعتراض کیا تو انھوں نے سیدنا ابی بن کعب رضی اللہ عنہ کو اس کے متعلق (خط) لکھا تو انھوں نے جوابی (خط) لکھ کر سیدنا سمرہ بن جندب رضی اللہ عنہ کے عمل کی تصدیق کی۔ (1)\nاور ہشیم بن بشیر نے بھی یونس بن عبید سے یہی حدیث روایت کی ہے، انھوں نے اس طرح بیان کیا ہے: ’’وَإِذَا قَرَأَ وَلَا الضَّالِّينَ سَكَتَ سَكْتَةً‘‘ (یعنی: جب سیدنا سمرہ بن جندب رضی اللہ عنہ ’’وَلَا الضَّالِّينَ‘‘ کہتے تو سکوت اختیار کرتے) ان پر اعتراض کیا گیا تو انھوں نے سیدنا ابی بن کعب رضی اللہ عنہ کو (خط) لکھا۔ انھوں نے (جواب میں) لکھا کہ حقیقت مسئلہ وہی ہے جس طرح سیدنا سمرہ بن جندب رضی اللہ عنہ نے کیا ہے۔","",{"f":"§حواشی\n(1) اسنادہ صحیح۔"}],[276,"یہ روایت ہمیں ابو بکر بن حارث الفقیہ نے بیان کی، انھوں نے کہا: ہمیں علی بن عمر دارقطنی نے بیان کیا، انھوں نے کہا: ہمیں محمد بن مخلد نے بیان کیا، انھوں نے کہا: ہمیں حسن بن عرفہ نے بیان کیا، انھوں نے کہا: ہمیں ہشیم بن بشیر نے بیان کیا، انھوں یہ حدیث (گذشتہ الفاظ میں) بیان کی۔ (1)","",{"f":"§حواشی\n(1) بالکل متصل گذشتہ سطور میں ہشیم بن بشیر کی بیان کردہ حدیث کے جو الفاظ بیان ہوئے ہیں، یہ ان الفاظ کی سند ہے۔ سنن الدارقطنی: 336/1۔ یہ سند ضعیف ہے۔ البتہ حدیث صحیح ہے۔"}],[277,"§رسول اللہ صلی اللہ علیہ وسلم کے سکتوں میں صحابہ رضی اللہ عنہم کا عمل:\nہمیں امام ابو عثمان الصابونی نے بیان کیا، انھوں نے کہا: ہمیں ابو طاہر محمد بن فضل بن محمد بن اسحاق بن خزیمہ نے بیان کیا، انھوں نے کہا: ہمیں میرے دادا جان (امام محمد بن اسحاق المعروف ابن خزیمہ) نے بیان کیا، انھوں نے کہا: ہمیں محمد بن ابی صفوان ثقفی نے بیان کیا، انھوں نے کہا: ہمیں ابو بکر الحنفی نے بیان کیا، انھوں نے کہا: ہمیں عبدالحمید بن جعفر نے بیان کیا، انھوں نے عمرو بن شعیب سے، انھوں نے اپنے والد محترم سے، انھوں نے اپنے دادا سے روایت کیا کہ وہ رسول اللہ صلی اللہ علیہ وسلم کے پیچھے قرآت کیا کرتے تھے۔ جب رسول اللہ صلی اللہ علیہ وسلم انصات (سکتہ) کرتے۔ جب رسول اللہ صلی اللہ علیہ وسلم قرآت کرتے؛ تب وہ قرآت نہیں کرتے تھے۔ جب رسول اللہ صلی اللہ علیہ وسلم انصات کرتے (خاموش ہوتے) تب وہ قرآت کرتے۔ اور رسول اللہ صلی اللہ علیہ وسلم فرمایا کرتے تھے: ہر وہ نماز جس میں سورت فاتحہ نہیں پڑھی گئی، وہ بے کار ہے۔ (1)","",{"f":"§حواشی\n(1) اسنادہ حسن۔ سنن ابن ماجہ، حدیث: 841 - جزء القراءۃ خلف الامام، للبخاری: ص، 24، حدیث: 15۔"}],[278,"مجھے ابو عبداللہ الحافظ نے بیان کیا کہ انھیں ابو علی حسین علی الحافظ نے بیان کیا، انھوں نے کہا: ہمیں محمد بن اسحاق بن خزیمہ نے بیان کیا، انھوں نے اسی (گذشتہ) سند سے اسی روایت کو بیان کیا۔ (1)\nامام کے دو سکتوں میں مقتدی کی قرآت (امام ابو سلمہ رحمہ اللہ کا فتویٰ):\nامام محمد بن اسحاق بن خزیمہ رحمہ اللہ نے امام کے سکتہ اور اس دوران مقتدی کی قرآت (یعنی انصات اور قرآت کا عمل بیک وقت ہونے) کے بارے میں جس حدیث سے دلیل لی ہے وہ حدیث محمد بن عمرو کی بیان کردہ ہے، انھوں نے عبدالملک بن مغیرہ سے روایت کی ہے کہ سیدنا ابو ہریرہ رضی اللہ عنہ نے فرمایا: ہر وہ نماز جس میں سورت فاتحہ نہیں پڑھی گئی، وہ ادھوری ہے ادھوری ہے (یعنی بے کار ہے)۔ کسی نے پوچھا: جب امام قرآت کر رہا ہو تب کیا کرنا چاہیے؟ ابو سلمہ بن عبدالرحمن (سیدنا ابو ہریرہ رضی اللہ عنہ کے شاگرد) نے کہا: امام دو سکتے کرتا ہے، ان سکتوں کو (سورت فاتحہ پڑھنے کے لیے) غنیمت جانو۔ ایک سکتہ تب ہے جب امام تکبیر تحریمہ کہتا ہے۔ اور ایک سکتہ تب ہے جب امام ﴿غَيْرِ الْمَغْضُوبِ عَلَيْهِمْ وَلَا الضَّالِّينَ﴾ کہتا ہے۔ (2)\nامام ابو بکر (یعنی ابن خزیمہ رحمہ اللہ) کہتے ہیں: ابو سلمہ رحمہ اللہ نے (سکتوں کے بارے میں) وضاحت، سیدنا ابو ہریرہ رضی اللہ عنہ کی موجودگی میں اسی موقع پر ہی بیان کی تھی۔ اگر سیدنا ابو ہریرہ رضی اللہ عنہ ابو سلمہ کی بات کو درست نہ سمجھتے تو ان کی طرف سے انکار ضرور ہوتا۔ لہذا جو روایات ہم بیان کر چکے ہیں ان کی رو سے یقیناً معلوم ہوتا ہے کہ سیدنا ابو ہریرہ رضی اللہ عنہ امام کے پیچھے قرآت کے قائل تھے۔\nامام سعید بن جبیر رحمہ اللہ (تابعی) کا فتویٰ:\nامام بیہقی رحمہ اللہ فرماتے ہیں: جو روایات ہم نے گذشتہ سطور میں بیان کی ہیں؛ ان کی اسناد بھی ذکر کر دی ہیں۔ اور پھر آپ رحمہ اللہ نے ایک حدیث بیان کی ہے کہ جعفر بن محمد ثقفی نے یحییٰ بن سلیم سے روایت کیا، انھوں نے عبداللہ بن عثمان بن خثیم سے روایت کیا، انھوں نے کہا: میں نے امام کے پیچھے قرآت کرنے کے بارے میں امام سعید بن جبیر رحمہ اللہ سے سوال کیا۔ تو انھوں نے فرمایا: اماموں نے ایسا کام شروع کر دیا ہے جو اسلاف نے نہیں کیا تھا۔ (اسلاف کا طریقہ یہ تھا کہ) امام جب تکبیر تحریمہ کہتا تو انصات کرتا (خاموش ہو جاتا)۔ حتیٰ کہ اسے یقین ہو جاتا کہ مقتدیوں نے سورت فاتحہ پڑھ لی ہے۔ میں نے تو حدیث سنی ہے، کیا تم نے نہیں سنا کہ قرآت کے بغیر نماز نہیں ہوتی؟","",{"f":"§حواشی\n(1) اسنادہ حسن۔\n(2) اس حدیث کی تخریج، حدیث نمبر: 218 کے تحت دیکھیں۔"}],[279,"ابو طاہر محمد بن فضل بن محمد بن اسحاق بن خزیمہ کے حوالے سے مجھے بتایا گیا کہ انھوں نے کہا: ہمیں میرے دادا جان (محمد بن اسحاق ابن خزیمہ) نے بیان کیا، انھوں نے کہا ہمیں جعفر بن محمد نے بیان کیا، انھوں نے یہ روایت (گذشتہ سطور میں بیان شدہ، سعید بن جبیر رحمہ اللہ کی روایت) بیان کی۔ (1)\nعروہ بن زبیر (تابعی) رحمہ اللہ کا فتویٰ:\nاور امام محمد بن اسماعیل بخاری رحمہ اللہ اپنی کتاب میں فرماتے ہیں: ہمیں موسیٰ نے حماد کے حوالے سے بیان کیا، انھوں نے ہشام بن عروہ سے، انھوں نے اپنے والد محترم عروہ بن زبیر (تابعی) رحمہ اللہ سے روایت کیا، انھوں نے کہا: اے بیٹا! امام کے سکتہ کے دوران تم قرآت کرو۔ اور جس وقت وہ جہری قرآت کرنے لگے تو تم خاموش ہو جاؤ۔ جس نماز میں سورت فاتحہ اور مزید کچھ قرآت نہ کی جائے، وہ نماز نامکمل ہے، چاہے فرض ہو یا نفل۔ اس روایت کی سند ہم ذکر کر چکے ہیں۔ (2)\nامام عطاء رحمہ اللہ کا فتویٰ:\nامام بخاری رحمہ اللہ بیان کرتے ہیں کہ امام عبدالرزاق صنعانی نے ابن جریج (یعنی: عبدالملک بن عبدالعزیز بن جریج) سے روایت کیا، انھوں نے عطا سے روایت کیا، کہ جب امام جہری قرآت کرے تو مقتدی سورت فاتحہ جلدی پڑھ لے۔ یا امام کی قرآت کے بعد تب پڑھے جب وہ سکتہ کرے۔ جب امام قرآت کرنے لگے تو مقتدی انصات کرے (خاموش ہو جائے)۔ جیسا کہ اللہ تعالیٰ نے فرمایا ہے۔ (3)","",{"f":"§حواشی\n(1) امام بیہقی رحمہ اللہ کے استاذ کا نام مبہم ہونے کی وجہ سے یہ سند ضعیف ہے۔ البتہ اثر صحیح ہے۔\n(2) دیکھئے: حدیث نمبر، 217۔\n(3) مصنف عبدالرزاق: 133/2، حدیث، 2788 - جزء القراءۃ خلف الامام، للبخاری: ص، 77، حدیث، 117۔"}],[280,"ابو طاہر محمد بن فضل بن محمد بن اسحاق بن خزیمہ کے حوالے سے مجھے بتایا گیا کہ انھوں نے کہا: ہمیں میرے دادا جان (محمد بن اسحاق ابن خزیمہ) نے بیان کیا، انھوں نے کہا: ہمیں محمد بن رافع نے بیان کیا، انھوں نے کہا: ہمیں عبدالرزاق صنعانی نے بیان کیا، انھوں نے اپنی سند کے ساتھ اسی طرح روایت کیا۔ (1)","",{"f":"§حواشی\n(1) امام بیہقی رحمہ اللہ کے استاذ کا نام مبہم ہونے کی وجہ سے یہ سند ضعیف ہے۔"}],[281,"§فصل ۲: امام کی قرآت کے وقت انصات (خاموشی اختیار) کرنے کے متعلق احادیث\nیہ باب ان لوگوں کے لیے ہے جنھوں نے امام شافعی رحمہ اللہ کے پرانے قول کو دلیل بنایا ہے۔\n§پہلی حدیث (امام قرآت کرے تو تم خاموش رہو):\nہمیں ابو عبداللہ الحافظ نے بیان کیا، انھوں نے کہا: مجھے ابو علی الحسین بن علی الحافظ نے بیان کیا، انھوں نے کہا: ہمیں ابراہیم بن ابی طالب نے بیان کیا، انھوں نے کہا: ہمیں اسحاق بن ابراہیم نے بیان کیا، انھوں نے کہا: ہمیں جریر نے بیان کیا، انھوں نے سلیمان تیمی سے، انھوں نے قتادہ سے، انھوں نے یونس بن جبیر سے، انھوں نے حطان بن عبداللہ سے، انھوں نے سیدنا ابو موسیٰ اشعری رضی اللہ عنہ سے روایت کیا کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا: جب امام تکبیر کہے تو تم بھی تکبیر کہو، اور جب امام قرآت کرے تو تم خاموش رہو۔ (1)\nیہ کلمات سلیمان تیمی کی طرف سے مدرج ہیں:\nیہ حدیث امام مسلم بن حجاج رحمہ اللہ نے بھی صحیح مسلم میں سعید بن منصور، قتیبہ بن سعید، ابو کامل اور محمد بن عبدالملک اموی سے روایت کی ہے، ان چاروں ائمہ نے (یہ حدیث) امام ابو عوانہ سے روایت کی ہے۔ (2)\nاور (یہی حدیث امام مسلم رحمہ اللہ نے) امام ابو بکر بن ابی شیبہ سے بھی روایت کی ہے، انھوں نے ابو اسامہ سے، انھوں نے سعید بن ابی عروبہ سے بھی روایت کیا ہے۔ اور (اسی طرح یہ حدیث، امام مسلم رحمہ اللہ نے) ابو غسان مسمعی سے بھی روایت کی ہے، انھوں نے معاذ بن ہشام سے، انھوں نے اپنے والد معاذ سے روایت کی ہے۔ اور ان سب راویوں نے قتادہ سے ہی اس حدیث کو مکمل روایت کیا ہے۔ لیکن کسی کی بیان کردہ حدیث میں ’’اور جب امام قرآت کرے تو تم خاموش رہو‘‘ کے الفاظ نہیں ہیں۔ پھر اسی حدیث کو امام اسحاق بن ابراہیم سے بھی روایت کیا ہے، انھوں نے جریر سے، انھوں نے سلیمان تیمی سے، انھوں نے قتادہ سے روایت کی ہے۔ (3)\n⇐ بْنُ عَبْدِ الْمَلِكِ الْأُمَوِيُّ، ...... وَاللَّفْظُ لِأَبِي كَامِلٍ ...... قَالُوا: حَدَّثَنَا أَبُو عَوَانَةَ، عَنْ قَتَادَةَ، عَنْ يُونُسَ بْنِ جُبَيْرٍ، عَنْ حِطَّانَ بْنِ عَبْدِ اللهِ الرَّقَاشِيِّ، قَالَ: صَلَّيْتُ مَعَ أَبِي مُوسَى الْأَشْعَرِيِّ صَلَاةً . . . . ‘‘ یہ حدیث طویل یہ ہے، البتہ محل استشہاد یہ ہے کہ سیدنا ابو موسیٰ اشعری رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: «إِذَا صَلَّيْتُمْ فَأَقِيمُوا صُفُوفَكُمْ ثُمَّ لِيَؤُمَّكُمْ أَحَدُكُمْ فَإِذَا كَبَّرَ فَكَبِّرُوا وَإِذْ قَالَ: ’’غَيْرِ الْمَغْضُوبِ عَلَيْهِمْ وَلَا الضَّالِّينَ‘‘، فَقُولُوا: آمِينَ؛ يُجِبْكُمُ اللهُ - فَإِذَا كَبَّرَ وَرَكَعَ فَكَبِّرُوا وَارْكَعُوا، فَإِنَّ الْإِمَامَ يَرْكَعُ قَبْلَكُمْ وَيَرْفَعُ قَبْلَكُمْ۔» [صحیح مسلم، کتاب الصلاۃ، باب التشہد فی الصلاۃ، حدیث، 62 - (404)] ترجمہ: جب تم نماز پڑھو تو صفیں سیدھی کرو، پھر تم میں سے کوئی ایک شخص جماعت کرائے۔ تو جب وہ تکبیر (تحریمہ) کہے تو تم بھی تکبیر کہو۔ اور جب وہ ’’غَيْرِ الْمَغْضُوبِ عَلَيْهِمْ وَلَا الضَّالِّينَ‘‘ کہے تو تم ’’آمین‘‘ کہو۔ اللہ تعالیٰ قبول کرے گا۔ پھر جب وہ تکبیر کہے اور رکوع کرے تو تم بھی تکبیر کہو اور رکوع کرو۔ امام تم سے پہلے رکوع کرے اور تم سے پہلے ہی (رکوع سے) سر اٹھائے گا۔ امام بیہقی رحمہ اللہ نے اس حدیث کی مختلف سندوں کی طرف اشارہ اس لیے کیا ہے کہ سیدنا ابو موسیٰ اشعری رضی اللہ عنہ کی روایت کردہ جو حدیث بیان کی گئی ہے، جس میں کہا گیا ہے کہ ’’اور جب امام قرآت کرے تو تم خاموش رہو‘‘۔ یہ الفاظ امام قتادہ سے حدیث روایت کرنے والوں میں سے صرف سلیمان تیمی نے بیان کیے ہیں۔ اس کے علاوہ کسی محدث نے یہ اضافہ بیان نہیں کیا۔\nپھر امام مسلم رحمہ اللہ نے جریر کے سلیمان تیمی سے، ان کے قتادہ سے روایت کردہ اضافی الفاظ ’’اور جب امام قرآت کرے تو تم خاموش رہو‘‘ کے بارے میں فرمایا ہے: یہ الفاظ (جریر کی سلیمان سے روایت کردہ حدیث میں ہی ہیں۔ ابو بکر بن ابی شیبہ، ابو غسان مسمعی اور اسحاق بن ابراہیم میں سے) کسی کی حدیث میں یہ الفاظ نہیں ہیں۔\nپھر امام مسلم رحمہ اللہ نے (اسی حدیث کو) اسحاق بن ابراہیم اور ابن ابی عمر کے واسطے سے عبدالرزاق سے روایت کیا ہے، انھوں نے معمر بن راشد سے، انھوں نے قتادہ سے روایت کیا ہے۔ اس حدیث میں بھی (’’اور جب امام قرآت کرے تو تم خاموش رہو‘‘ کے الفاظ کا) اضافہ نہیں ہے۔ (4)","",{"f":"§حواشی\n(1) شاذ ہونے کے باعث یہ روایت ضعیف ہے۔ ’’جب امام قرآت کرے تو تم خاموش رہو‘‘ کا اضافہ قتادہ کے تلامذہ میں سے صرف سلیمان تیمی نے بیان کیا ہے۔ جبکہ سلیمان تیمی کے علاوہ قتادہ کے تمام وہ تلامذہ جنھوں نے اس حدیث کو قتادہ سے روایت کیا ہے، وہ ثقہ اور جلیل القدر راوی ہیں۔ انھوں نے یہ اضافہ بیان نہیں کیا۔ ان راویوں میں: ہشام دستوائی، سعید بن ابی عروبہ، شعبہ بن حجاج، ہمام بن یحییٰ، ابو عوانہ الوضاح، ابان بن سعید، عدی بن ابی عمارہ اور معمر بن راشد وغیرہ شامل ہیں، ان میں سے چند ائمہ کی روایات بطور دلیل اگلے صفحات میں آئیں گی۔ ان شاء اللہ۔ ان سب کی روایت کردہ حدیث کے الفاظ سلیمان تیمی کے بیان کردہ اضافی الفاظ کے بغیر ہیں۔\n(2) امام مسلم نے یہ حدیث چار اساتذہ سے روایت کی ہے اور امام ابو عوانہ نے قتادہ سے روایت کی ہے۔ اس حدیث کی سند اس طرح ہے: ’’حَدَّثَنَا سَعِيدُ بْنُ مَنْصُورٍ وَقُتَيْبَةُ بْنُ سَعِيدٍ وَأَبُو كَامِلٍ الْجَحْدَرِيُّ وَمُحَمَّدُ ⇐\n(3) در اصل امام مسلم نے اس حدیث کو؛ ابو بکر بن ابی شیبہ، ابو غسان مسمعی اور اسحاق بن ابراہیم (تینوں محدثین) کی سند سے روایت کیا ہے، سب کی سند میں مرکزی راوی قتادہ ہی ہے۔ امام مسلم رحمہ اللہ نے تینوں اسناد ذکر کی ہیں، ان کے ساتھ امام مسلم نے اس سند کو بھی بیان کیا ہے، جس میں سلیمان تیمی نے قتادہ سے روایت کی ہے۔ ملاحظہ فرمائیں، تینوں اسناد اور پھر امام مسلم رحمہ اللہ کا تبصرہ: ’’حَدَّثَنَا أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ حَدَّثَنَا أَبُو أُسَامَةَ حَدَّثَنَا سَعِيدُ بْنُ أَبِي عَرُوبَةَ ح، وَحَدَّثَنَا أَبُو غَسَّانَ الْمِسْمَعِيُّ حَدَّثَنَا مُعَاذُ بْنُ هِشَامٍ حَدَّثَنَا أَبِي ح، وَحَدَّثَنَا إِسْحَاقُ بْنُ إِبْرَاهِيمَ أَخْبَرَنَا جَرِيرٌ عَنْ سُلَيْمَانَ التَّيْمِيِّ كُلُّ هَؤُلَاءِ عَنْ قَتَادَةَ فِي هَذَا الْإِسْنَادِ بِمِثْلِهِ وَفِي حَدِيثِ جَرِيرٍ عَنْ سُلَيْمَانَ عَنْ قَتَادَةَ مِنَ الزِّيَادَةِ وَإِذَا قَرَأَ فَأَنْصِتُوا وَلَيْسَ فِي حَدِيثِ أَحَدٍ مِنْهُمْ فَإِنَّ اللهَ قَالَ عَلَى لِسَانِ نَبِيِّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: سَمِعَ اللهُ لِمَنْ حَمِدَهُ إِلَّا فِي رِوَايَةِ أَبِي كَامِلٍ وَحْدَهُ عَنْ أَبِي عَوَانَةَ قَالَ أَبُو إِسْحَاقَ: قَالَ أَبُو بَكْرٍ: ابْنَ أُخْتِ أَبِي النَّضْرِ فِي هَذَا الْحَدِيثِ فَقَالَ مُسْلِمٌ: تُرِيدُ أَحْفَظَ مِنْ سُلَيْمَانَ فَقَالَ لَهُ أَبُو بَكْرٍ: فَحَدِيثُ أَبِي هُرَيْرَةَ فَقَالَ: هُوَ صَحِيحٌ يَعْنِي وَإِذَا قَرَأَ فَأَنْصِتُوا فَقَالَ: هُوَ عِنْدِي صَحِيحٌ فَقَالَ: لِمَ لَمْ تَضَعْهُ هَا هُنَا قَالَ: لَيْسَ كُلُّ شَيْءٍ عِنْدِي صَحِيحٍ وَضَعْتُهُ هَا هُنَا إِنَّمَا وَضَعْتُ هَا هُنَا مَا أَجْمَعُوا عَلَيْهِ [صحیح مسلم، کتاب الصلاۃ، باب التشہد فی الصلاۃ، حدیث، 63 - (404)]\n(4) صحیح مسلم، کتاب الصلاۃ، باب التشہد فی الصلاۃ، حدیث، 64 - (404)۔"}],[282,"§حدیث کا صحیح متن (ابو عوانہ کی سند):\n§ابو عوانہ کی قتادہ بن دعامہ سے روایت کردہ حدیث درج ذیل سند کے ساتھ مروی ہے:\nہمیں ابو عبداللہ محمد بن عبداللہ الحافظ (امام حاکم) نے بیان کیا، انھوں نے کہا: ہمیں احمد بن سلمان الفقیہ نے بیان کیا، انھوں نے کہا: ہمیں جعفر بن محمد الصائغ نے بیان کیا، انھوں نے کہا: ہمیں عفان نے بیان کیا، انھوں نے کہا: ہمیں ابو عوانہ الوضاح بن عبداللہ الیشکری نے بیان کیا۔ (1)","",{"f":"§حواشی\n(1) یہ سند حسن ہے، البتہ حدیث صحیح ہے۔ صحیح مسلم حدیث: 404 - سنن ابی داؤد، حدیث: 972 - مسند البزار: 63/8، حدیث، 3057۔"}],[283,"§ابن ابی عروبہ کی دو سندیں:\n§سعید بن ابی عروبہ کی روایت مندرجہ ذیل اسناد کے ساتھ مروی ہے:\n(پہلی سند) ہمیں ابو عبداللہ الحافظ (امام حاکم) نے بیان کیا، انھوں نے کہا: ہمیں ابو العباس محمد بن یعقوب نے بیان کیا، انھوں نے کہا: ہمیں ابراہیم بن مرزوق البصری نے مصر میں بیان کیا، انھوں نے کہا: ہمیں سعید بن عامر نے بیان کیا، انھوں نے کہا: ہمیں سعید بن ابی عروبہ نے بیان کیا۔\nوَأَخْبَرَنَا أَبُو عَبْدِ اللهِ، أنا بَكْرُ بْنُ مُحَمَّدِ بْنِ حَمْدَانَ، نا عَبْدُ الصَّمَدِ بْنُ الْفَضْلِ، نا مَكِّيُّ بْنُ إِبْرَاهِيمَ، نا سَعِيدُ بْنُ أَبِي عَرُوبَةَ۔\n(دوسری سند) ہمیں ابو عبداللہ نے بیان کیا، انھوں نے کہا: ہمیں بکر بن محمد بن حمدان نے بیان کیا، انھوں نے کہا: ہمیں عبدالصمد بن الفضل نے بیان کیا، انھوں نے کہا: ہمیں مکی بن ابراہیم نے بیان کیا، انھوں نے کہا: ہمیں سعید بن ابی عروبہ نے بیان کیا۔ (1)","",{"f":"§حواشی\n(1) اسنادہ صحیح۔ صحیح مسلم، حدیث: 404 - سنن النسائی، حدیث: 830 - سنن الکبریٰ للنسائی: 291/1، حدیث، 904 - سنن ابن ماجہ، حدیث: 901 - سنن الدارمی: 314/1 - مسند احمد بن حنبل: 401/4 - مصنف ابن ابی شیبہ: 67/5، حدیث، 7235 - صحیح ابن خزیمہ: حدیث، 1584، 1593 - مسند البزار: 63/8، حدیث، 3056 - مسند الرویانی: 373/1، حدیث، 570 - مسند ابی عوانہ: 454/1، حدیث، 1682۔"}],[284,"§ہشام الدستوائی کی سند:\n§ہشام الدستوائی کی روایت مندرجہ ذیل سند کے ساتھ مروی ہے:\nہمیں ابو بکر محمد بن الحسن بن فورک نے بیان کیا، انھوں نے کہا: ہمیں عبداللہ بن جعفر اصبہانی نے بیان کیا، انھوں نے کہا: ہمیں یونس بن حبیب العجلی نے بیان کیا، انھوں نے کہا: ہمیں ابو داؤد الطیالسی نے بیان کیا، انھوں نے کہا: ہمیں ہشام دستوائی نے بیان کیا۔ (1)","",{"f":"§حواشی\n(1) الحدیث صحیح۔ صحیح مسلم، حدیث: 404 - سنن ابی داؤد، حدیث: 972 - سنن النسائی، حدیث: 1172 - سنن الکبریٰ للنسائی: 252/1، حدیث، 760 - مسند احمد بن حنبل: 409/4 - صحیح ابن خزیمہ: حدیث، 1584 - صحیح ابن حبان: 540/5، حدیث، 2167 - مسند الرویانی: 356/1، حدیث، 548۔"}],[285,"§معمر بن راشد کی سند:\n§معمر بن راشد کی روایت مندرجہ ذیل سند کے ساتھ مروی ہے:\nہمیں ابو الحسین علی بن محمد بن عبداللہ بن بشران العدل نے بغداد میں بیان کیا، انھوں نے کہا: ہمیں اسماعیل بن محمد الصفار نے بیان کیا، انھوں نے کہا: ہمیں احمد بن منصور الرمادی نے بیان کیا، انھوں نے کہا: ہمیں عبدالرزاق بن ہمام الصنعانی نے بیان کیا، انھوں نے کہا: ہمیں معمر بن راشد الازدی نے بیان کیا۔ (1)\nابوعوانہ، ابن ابی عروبہ، ہشام اور معمر کی اسناد سے مروی متن:\nكُلَّهُمْ عَنْ قَتَادَةَ، عَنْ يُونُسَ بْنِ جُبَيْرٍ، عَنْ حِطَّانَ بْنِ عَبْدِ اللَّهِ الرَّقَاشِيِّ، أَنَّ أَبَا مُوسَى الْأَشْعَرِيَّ رَضِيَ اللهُ عَنْهُ، صَلَّى بِأَصْحَابِهِ فَلَمَّا جَلَسَ، قَالَ رَجُلٌ: أُقِرَّتِ الصَّلَاةُ بِالْبِرِّ وَالزَّكَاةِ، فَلَمَّا فَرَغَ أَبُو مُوسَى مِنْ صَلَاتِهِ قَالَ: أَيُّكُمُ الْقَائِلُ كَلِمَةَ كَذَا وَكَذَا؟ فَأَرَمَّ الْقَوْمُ، فَقَالَهَا ثَلَاثًا، ثُمَّ قَالَ: يَا حِطَّانُ لَعَلَّكَ قَائِلُهَا؟ قَالَ: مَا قُلْتُهَا وَلَقَدْ خَشِيتُ أَنْ تَبْكَعَنِي۔ قَالَ: فَقَالَ رَجُلٌ مِنَ الْقَوْمِ: أَنَا قَائِلُهَا وَمَا أَرَدْتُ بِهَا إِلَّا الْخَيْرَ، فَقَالَ أَبُو مُوسَى: أَمَا تَعْلَمُونَ مَا تَقُولُونَ فِي صَلَاتِكُمْ؟ إِنَّ رَسُولَ اللَّهِ صلی اللہ علیہ وسلم خَطَبَنَا فَعَلَّمَنَا صَلَاتَنَا وَبَيَّنَ لَنَا سُنَّتَنَا، فَقَالَ: إِذَا قُمْتُمْ فَأَقِيمُوا صُفُوفَكُمْ وَلْيَؤُمَّكُمْ أَحَدُكُمْ، فَإِذَا كَبَّرَ الْإِمَامُ فَكَبِّرُوا، وَإِذَا قَرَأَ ﴿غَيْرِ الْمَغْضُوبِ عَلَيْهِمْ وَلَا الضَّالِّينَ﴾، فَقُولُوا: آمِينَ، يُجِبْكُمُ اللَّهُ، وَإِذَا كَبَّرَ وَرَكَعَ فَكَبِّرُوا وَارْكَعُوا، فَإِنَّ الْإِمَامَ يَرْكَعُ قَبْلَكُمْ وَيَرْفَعُ قَبْلَكُمْ، فَقَالَ نَبِيُّ اللَّهِ صلی اللہ علیہ وسلم: فَتِلْكَ بِتِلْكَ، وَإِذَا قَالَ: سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ، فَقُولُوا: اللَّهُمَّ رَبَّنَا لَكَ الْحَمْدُ، يَسْمَعُ اللَّهُ لَكُمْ فَإِنَّ اللَّهَ تَعَالَى قَالَ عَلَى لِسَانِ نَبِيِّهِ صلی اللہ علیہ وسلم: سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ، فَإِذَا كَبَّرَ وَسَجَدَ فَكَبِّرُوا وَاسْجُدُوا، فَإِنَّ الْإِمَامَ يَسْجُدُ قَبْلَكُمْ وَيَرْفَعُ قَبْلَكُمْ، قَالَ نَبِيُّ اللَّهِ صلی اللہ علیہ وسلم: فَتِلْكَ بِتِلْكَ، وَإِذَا كَانَ عِنْدَ الْقَعْدَةِ فَلْيَكُنْ مِنْ أَوَّلِ قَوْلِ أَحَدِكُمْ: التَّحِيَّاتُ الطَّيِّبَاتُ الصَّلَوَاتُ لِلَّهِ، السَّلَامُ عَلَيْكَ أَيُّهَا النَّبِيُّ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ، السَّلَامُ عَلَيْنَا وَعَلَى عِبَادِ اللَّهِ الصَّالِحِينَ، أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَأَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ، لَفْظُ حَدِيثِ ابْنِ أَبِي عَرُوبَةَ۔\nان سب (یعنی: ابوعوانہ، ابن ابی عروبہ، ہشام دستوائی اور معمر بن راشد) نے قتادہ سے، انھوں نے یونس بن جبیر سے، انھوں نے حطان بن عبداللہ الرقاشی سے روایت کیا کہ سیدنا ابوموسیٰ اشعری رضی اللہ عنہ نے اپنے ساتھیوں کو نماز پڑھائی۔ جب آپ بیٹھے تو ایک آدمی بولا: کیا نماز کو نیکی اور زکوٰۃ کے ساتھ ملایا گیا ہے؟ سیدنا ابوموسیٰ رضی اللہ عنہ جب نماز سے فارغ ہوئے تو فرمایا: یہ بات کس نے کہی؟ لوگوں نے کوئی جواب نہ دیا۔ آپ رضی اللہ عنہ نے تین مرتبہ پوچھا۔ پھر آپ رضی اللہ عنہ نے فرمایا: اے حطان! شائد یہ بات تم نے کہی ہے۔ حطان (تابعی) نے کہا: میں نے یہ بات کہی تو نہیں، البتہ مجھے ڈر پیدا ہو گیا کہ آپ ناراض نہ ہو جائیں۔ پھر ایک آدمی بولا: یہ بات میں نے کہی ہے، اور اس سے میرا مقصد صرف نیکی تھا۔ سیدنا ابوموسیٰ رضی اللہ عنہ نے فرمایا: کیا تم جانتے نہیں کہ تم اپنی نماز میں کیا کہتے ہو؟ رسول اللہ صلی اللہ علیہ وسلم نے ہمیں خطبہ ارشاد فرمایا تھا: آپ صلی اللہ علیہ وسلم نے ہمیں نماز سکھائی اور طریقہ بھی بتایا۔ آپ صلی اللہ علیہ وسلم نے فرمایا: جب تم (نماز کے لیے) کھڑے ہو، تو صفیں سیدھی کرو، پھر تم میں سے کوئی ایک شخص جماعت کرائے۔ جب وہ تکبیر (تحریمہ) کہے تو تم بھی تکبیر کہو۔ اور جب وہ ’’غَيْرِ الْمَغْضُوبِ عَلَيْهِمْ وَلَا الضَّالِّينَ‘‘ کہے تو تم ’’آمین‘‘ کہو۔ اللہ تعالیٰ قبول کرے گا۔ پھر جب وہ تکبیر کہے اور رکوع کرے تو تم بھی تکبیر کہو اور رکوع کرو۔ امام تم سے پہلے رکوع کرے اور تم سے پہلے ہی (رکوع سے) سر اٹھائے گا۔ آپ صلی اللہ علیہ وسلم نے فرمایا: پہلے رکوع کرنا اور پہلے اٹھنا امام کا ہی حق ہے۔ اور جب امام ’’سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ‘‘ کہے تو تم کہو: ’’اللَّهُمَّ رَبَّنَا لَكَ الْحَمْدُ‘‘۔ اللہ تعالیٰ تمہارا حمد بیان کرنا سن لے گا۔ اللہ تعالیٰ نے اپنے نبی کی زبان مبارک سے ’’سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ‘‘ (یعنی: جس نے اللہ کی حمد بیان کی ہے، اللہ تعالیٰ نے اسے سن لیا) کہلوایا ہے۔ اور جب امام تکبیر کہے اور سجدہ کرے تو تم بھی تکبیر کہو اور سجدہ کرو۔ امام تم سے پہلے سجدہ کرے گا اور تم سے پہلے ہی سجدے سے اٹھے گا۔ آپ صلی اللہ علیہ وسلم نے فرمایا: پہلے سجدہ کرنا اور پہلے اٹھنا امام کا ہی حق ہے۔ جب امام قعدہ میں ہو تو تم ان کلمات سے (تشہد کا) آغاز کرو: ’’التَّحِيَّاتُ الطَّيِّبَاتُ الصَّلَوَاتُ لِلَّهِ، السَّلَامُ عَلَيْكَ أَيُّهَا النَّبِيُّ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ، السَّلَامُ عَلَيْنَا وَعَلَى عِبَادِ اللَّهِ الصَّالِحِينَ، أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَأَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ‘‘۔ یہ الفاظ سعید بن ابی عروبہ کی (سند کے ساتھ) بیان کردہ حدیث کے ہیں۔ (2)\nدیگر متعدد محدثین کا بیان کردہ متن:\nاور یزید بن زریع، اسماعیل ابن علیہ، عبدہ بن سلیمان، ابواسامہ حماد بن اسامہ، روح بن عبادہ القیسی، مروان بن معاویہ الفزاری، عباد بن عوام، شعیب بن اسحاق، عبداللہ بن شوذب اور عثمان بن مطر رحمہم اللہ؛ سب نے سعید بن ابی عروبہ سے، انھوں نے قتادہ سے یہ حدیث اسی طرح بیان کی ہے۔ اس میں سے کسی کی بیان کردہ روایت میں ’’وَإِذَا قَرَأَ فَأَنصِتُوا‘‘ (اور جب امام قرآت کرے تو تم خاموش رہو) کے الفاظ نہیں ہیں۔\nسعید بن ابی عروبہ، ہشام دستوائی، معمر بن راشد اور ابوعوانہ کے ساتھ، یہ حدیث؛ ہمام بن یحییٰ، حماد بن سلمہ، ابان بن یزید اور حجاج بن حجاج باہلی وغیرہ نے بھی بیان کی ہے۔ اور ان سب نے یہ حدیث قتادہ ہی سے روایت کی ہے۔ اور ان کی بیان کردہ حدیث میں بھی ’’وَإِذَا قَرَأَ فَأَنصِتُوا‘‘ (اور جب امام قرآت کرے تو تم خاموش رہو) کے الفاظ نہیں ہیں۔\nدوسری حدیث (امام قرآت کرے تو تم خاموش رہو):\nاور یہی حدیث؛ سالم بن نوح نے، عمر بن عامر اور سعید بن ابی عروبہ (دونوں) سے روایت کی ہے، انھوں نے قتادہ کے واسطے سے، ان کی سند کے ساتھ روایت کی ہے، کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا: «إِذَا كَبَّرَ الْإِمَامُ فَكَبِّرُوا وَإِذَا قَرَأَ فَأَنصِتُوا»، یعنی: جب امام تکبیر کہے تو تم بھی تکبیر کہو، اور جب وہ قرآت کرے تو تم خاموش رہو۔ [اسناد کی تفصیل حسب ذیل ہے]","",{"f":"§حواشی\n(1) مصنف عبدالرزاق: 201/2، حدیث، 3065 - صحیح مسلم، حدیث: 404 - السنن الکبریٰ للبیہقی: 96/2۔\n(2) اسنادہ صحیح۔"}],[286,"یہ روایت ہمیں ابوعبداللہ الحافظ (امام حاکم) نے بیان کی، انھوں نے کہا: ہمیں ابوعلی الحافظ نے بیان کیا، انھوں نے کہا: ہمیں ابراہیم بن ابی طالب نے بیان کیا، انھوں نے کہا: ہمیں محمد بن یحییٰ القطعی نے بیان کیا، انھوں نے کہا: ہمیں سالم بن نوح نے بیان کیا، انھوں نے اپنی سند سے یہ روایت بیان کی۔ (1)\nامام بیہقی رحمہ اللہ فرماتے ہیں: یہ اضافہ (یعنی: ’’جب امام قرآت کرے تو تم خاموش رہو‘‘ کے الفاظ) سلیمان تیمی کا وہم ہیں، اور پھر سالم بن نوح کو بھی وہم ہو گیا (غلطی لگ گئی)۔","",{"f":"§حواشی\n(1) شذوذ کی وجہ سے ضعیف ہے۔ سنن الدارقطنی: 330/1، حدیث، 16 - السنن الکبریٰ للبیہقی: 156/2 - مسند البزار: 66/8، حدیث، 3060۔"}],[287,"§امام ابوداؤد رحمہ اللہ کی وضاحت:\nہمیں ابوعلی الحسین بن محمد الروذباری نے بیان کیا، انھوں نے کہا: ہمیں ابوبکر بن داسہ نے بیان کیا، انھوں نے کہا: ہمیں ابوداؤد سلیمان بن اشعث السجستانی نے بیان کیا، انھوں نے کہا: ’’جب امام قرآت کرے تو تم خاموش رہو‘‘ کے الفاظ کی کوئی حقیقت نہیں ہے۔ (1)","",{"f":"§حواشی\n(1) ابوداؤد تک سند صحیح ہے۔ السنن الکبریٰ للبیہقی: 155/2 - الجوہر النقی، لابن الترکمانی: 155/2 - نصب الرأیۃ، للزیلعی: 15/2 - امام ابوداؤد رحمہ اللہ نے سنن ابی داؤد میں سلیمان تیمی کی بیان کردہ روایت کو نقل کرنے کے بعد وضاحت کی ہے کہ اس حدیث میں ’’جب امام قرآت کرے تو تم خاموش رہو‘‘ کے الفاظ؛ صرف سلیمان تیمی نے ہی بیان کیے ہیں۔ [دیکھئے: سنن ابی داؤد، کتاب الصلاۃ، باب التشہد، حدیث، 973۔"}],[288,"§امام حاکم رحمہ اللہ کے استاذ، امام ابوعلی نیساپوری رحمہ اللہ کی وضاحت:\nاور ہمیں ابوعبداللہ الحافظ (امام حاکم) نے بیان کیا، انھوں نے کہا: میں نے ابوعلی الحسین بن علی الحافظ کو فرماتے ہوئے سنا، انھوں نے فرمایا: اس حدیث کو روایت کرنے میں سلیمان تیمی نے قتادہ کے تمام اصحاب (شاگردوں) کی مخالفت کی ہے۔ میرے نزدیک یہ الفاظ ’’وہم‘‘ ہیں۔ جبکہ ہشام دستوائی، ہمام، سعید بن ابی عروبہ، معمر بن راشد، ابوعوانہ اور حجاج بن حجاج کی، قتادہ سے روایت کردہ حدیث محفوظ (صحیح) ہے۔ (1)\nالحافظ ابوعلی الحسین بن علی نے مزید فرمایا: سالم بن نوح نے جو حدیث بیان کی ہے (جس کی سند 285 نمبر پر اور اس کا متن اس سے بالکل متصل سابقہ سطور میں بیان ہوا ہے) وہ حدیث عمر بن عامر سے روایت کرنے میں سالم بن نوح سے غلطی خطا (الفاظ میں غلطی) ہو گئی ہے جس طرح سعید بن ابی عروبہ سے روایت کرنے میں اس سے غلطی ہو گئی۔ کیونکہ سعید بن ابی عروبہ کی حدیث، یحییٰ بن سعید، یزید بن زریع، اسماعیل ابن علیہ اور ابن ابی عدی وغیرہ نے بھی بیان کی ہے۔ جب ایک طرف یہ تمام راوی ہیں، تو ان کے مقابل سالم بن نوح کم درجے کا راوی ہے۔ (2)","",{"f":"§حواشی\n(1) اسنادہ صحیح۔\n(2) یعنی: جب ان تمام کی بیان کردہ احادیث آگئیں تو پھر اکیلے سالم بن نوح کی بیان کردہ روایت کے الفاظ کی کچھ اہمیت نہیں رہتی۔"}],[289,"§سالم بن نوح البصری ضعیف راوی ہے:\nہمیں ابوعبدالرحمن السلمی نے بیان کیا، انھوں نے کہا: علی بن عمر الحافظ دارقطنی نے فرمایا: سالم بن نوح، ’’لَيْسَ بِالْقَوِيِّ‘‘ (یعنی: یہ ثقہ راوی نہیں ہے)۔ (1)\nامام دارقطنی رحمہ اللہ کی وضاحت:\nامام دارقطنی رحمہ اللہ نے سلیمان تیمی کی (حدیث نمبر: 280) حدیث کے برعکس مروی؛ ہشام دستوائی، سعید بن ابی عروبہ، شعبہ، ہمام بن یحییٰ، ابوعوانہ، ابان بن سعید اور عدی کی روایت کردہ حدیث کے بارے میں فرمایا ہے کہ ان تمام نے قتادہ سے یہ حدیث روایت کی ہے، لیکن ان میں سے کسی نے بھی ’’وَإِذَا قَرَأَ فَأَنصِتُوا‘‘ کے الفاظ بیان نہیں کیے۔ حالانکہ قتادہ کے یہ تمام اصحاب (تلامذہ)، سلیمان تیمی کی نسبت زیادہ اعلیٰ درجہ کے حفاظ (حفظ وضبط والے، زیادہ معتبر راوی) ہیں۔\nامام بخاری اور امام ابن خزیمہ رحمہما اللہ کا قول:\nامام ابوعبداللہ محمد بن اسماعیل البخاری اور ابوبکر محمد بن اسحاق بن خزیمہ رحمہما اللہ نے اس حدیث میں اس اضافے (یعنی: جب امام قرآت کرے تو تم خاموش رہو) کو کمزور قرار دیا ہے۔\nتیسری حدیث (امام قرآت کرے تو تم خاموش رہو):\nاور یہی الفاظ محمد بن عجلان سے بھی مروی ہیں، انھوں نے زید بن اسلم سے، انھوں نے ابوصالح سے، انھوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے، انھوں نے نبی کریم صلی اللہ علیہ وسلم سے روایت کیے ہیں۔ [اس کی مکمل سند مع متن حسب ذیل ہے:]","",{"f":"§حواشی\n(1) یہ سند ضعیف ہے، کیونکہ ابوعبدالرحمن متکلم فیہ راوی ہے۔ البتہ یہ قول امام دارقطنی نے ثابت ہے۔ دیکھئے: سنن الدارقطنی: 330/1 - العلل للدارقطنی: 254/7۔"}],[290,"ہمیں ابوعبداللہ الحافظ نے بیان کیا، انھوں نے کہا: ہمیں ابوبکر بن اسحاق الفقیہ نے بیان کیا، انھوں نے کہا: ہمیں موسیٰ بن اسحاق القاضی نے بیان کیا، انھوں نے کہا: ہمیں عبداللہ بن ابی شیبہ نے بیان کیا، انھوں نے کہا: ہمیں ابوخالد الاحمر نے بیان کیا، انھوں نے محمد بن عجلان القرشی سے، انھوں نے زید بن اسلم سے، انھوں نے ابوصالح ذکوان سے روایت کیا کہ سیدنا ابوہریرہ رضی اللہ عنہ نے بیان کیا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: امام تو اسی لیے مقرر کیا گیا ہے کہ اس کی اقتدا کی جائے۔ لہذا جب وہ تکبیر کہے تو تم بھی تکبیر کہو، جب وہ قرآت کرے تو تم خاموش رہو۔ (1)\nیہ حدیث أَبُو خَالِدٍ الْأَحْمَرُ عَنْ مُحَمَّدِ بْنِ عَجْلَانَ کی سند معروف ہے۔ (2)\nابوخالد نا قابل حجت راوی:\nامام بخاری رحمہ اللہ فرماتے ہیں: یہ معلوم نہیں کہ یہ ابوخالد الاحمر کی (بیان کردہ) صحیح حدیث ہے۔ (3) امام احمد بن حنبل رحمہ اللہ فرماتے ہیں: میرا خیال ہے کہ ابوخالد تدلیس کرتا (یعنی مدلس روایات بیان کرتا) تھا۔ (4)\nیحییٰ بن معین رحمہ اللہ کہتے ہیں: ابوخالد الاحمر، صدوق راوی ہے لیکن قابل حجت نہیں ہے۔ (5)\nدوسری سند اور امام بیہقی رحمہ اللہ کا تبصرہ:\nامام بیہقی رحمہ اللہ فرماتے ہیں: یہ روایت حسان بن ابراہیم الکرمانی اور اسماعیل بن ابان الغنوی سے بھی مروی ہے، انھوں نے بھی محمد بن عجلان سے روایت کی ہے۔ اور اسماعیل بن ابان الغنوی ضعیف راوی ہے۔ (6) اور حسان بن ابراہیم الکرمانی کی بعض روایات منکر ہیں۔","",{"f":"§حواشی\n(1) یہ سند حسن درجہ کی ہے۔ البتہ حدیث، ’’وَإِذَا قَرَأَ فَأَنصِتُوا‘‘ کے الفاظ کے علاوہ صحیح ہے۔ کیونکہ یہ الفاظ شاذ ہیں۔\n(2) سنن ابی داؤد، حدیث: 604 - سنن ابن ماجۃ، حدیث: 846 - سنن الدارقطنی: 227/1 - العلل، للدارقطنی: 187/8 - الأوسط، لابن المنذر: 105/3، حدیث، 1319۔ اس حدیث کو امام ابن ابی شیبہ رحمہ اللہ نے اپنی کتاب میں متعدد مقامات پر ذکر کیا ہے۔ دیکھئے: مصنف ابن ابی شیبہ: (458/2، حدیث، 2611) (281/3، حدیث، 3820) (61/5، حدیث، 8214) (85/20، حدیث، 37290)۔\n(3) جزء القراءۃ خلف الامام، للبخاری: ص، 147۔\n(4) جزء القراءۃ خلف الامام، للبخاری: ص، 147۔\n(5) الکامل فی ضعفاء الرجال، لابن عدی: 281/3 - میزان الاعتدال، للذہبی: 200/2 - سیر أعلام النبلاء، للذہبی: 20/9 - تہذیب الکمال، للمزی: 296/11۔\n(6) سنن الدارقطنی: 329/1، حدیث، 12 - السنن الکبریٰ للبیہقی: 156/2۔"}],[291,"§امام یحییٰ بن معین رحمہ اللہ کا تبصرہ:\nہمیں ابوعبداللہ الحافظ نے بیان کیا، انھوں نے کہا: ہمیں ابوالعباس محمد بن یعقوب نے بیان کیا، انھوں نے کہا: ہمیں عباس بن محمد نے بیان کیا، انھوں نے کہا: میں نے یحییٰ بن معین کو محمد بن عجلان کی روایت: ’’جب امام قرآت کرے تو تم خاموش رہو‘‘ کے بارے میں فرماتے ہوئے سنا، کہ اس کی کوئی حیثیت نہیں ہے۔ (1)\nیحییٰ بن علاء ضعیف راوی:\nامام بیہقی رحمہ اللہ فرماتے ہیں: اس روایت کو یحییٰ بن علاء الرازی نے بھی زید بن اسلم سے روایت کیا ہے۔ (2) اور یحییٰ بن علاء الرازی متروک راوی ہے۔ امام یحییٰ بن معین اور دیگر ائمہ نے اس پر جرح کی ہے۔ (3) اور یہ روایت عمر بن ہارون سے بھی ضعیف سند کے ساتھ مروی ہے، اس نے خارجہ بن مصعب سے، اس نے زید بن اسلم سے روایت کی ہے۔ لہذا ثقہ اور حفاظ (معتبر) راویوں کے مقابل ان (ضعیف اور مجروح) راویوں کی متابعت کچھ حیثیت نہیں رکھتی۔","",{"f":"§حواشی\n(1) اسنادہ صحیح۔ تاریخ ابن معین، بروایۃ الدوری: 455/3، حدیث، 2236۔\n(2) العلل، للدارقطنی: 187/8۔\n(3) امام یحییٰ بن معین رحمہ اللہ کہتے ہیں: یحییٰ بن علاء، ثقہ راوی نہیں ہے۔ دیکھئے: تاریخ ابن معین، بروایۃ الدوری: 369/4، رقم، 4829 - الضعفاء، للعقیلی: 437/4 - الکامل فی ضعفاء الرجال، لابن عدی: 198/7۔"}],[292,"§امام ابن ابی حاتم رحمہ اللہ کا تبصرہ:\nہمیں ابوبکر بن حارث نے بیان کیا، انھوں نے کہا: ہمیں ابومحمد بن حیان نے بیان کیا، انھوں نے کہا: ہمیں ابن ابی حاتم نے بیان کیا، انھوں نے کہا: میں نے اپنے والد محترم ابوحاتم رازی کو فرماتے ہوئے سنا: ...... ابن ابی حاتم نے ابوخالد الاحمر کی محمد بن عجلان سے روایت کردہ حدیث کا ذکر کیا، اور کہا...... میرے ابا جان نے فرمایا: یہ الفاظ (یعنی: ’’امام قرآت کرے تو تم خاموش رہو‘‘ کے الفاظ) محفوظ (صحیح) نہیں ہیں۔ (1) یہ روایت ان روایات میں سے جن میں محمد بن عجلان اختلاط کا شکار ہو گئے تھے۔ خارجہ بن مصعب نے بھی یہ حدیث روایت کی ہے۔ اور خارجہ بن مصعب بھی قوی راوی نہیں ہے۔ (2)","",{"f":"§حواشی\n(1) اسنادہ صحیح۔ دو روایتیں ایسی ہوں کہ وہ دونوں صحیح یا حسن ہوں، لیکن ان میں سے ایک روایت کے راوی؛ دوسری روایت کے راویوں کی نسبت زیادہ معتبر، زیادہ مضبوط حافظے والے اور زیادہ ثقہ ہوں، تو اس روایت کو محفوظ کہا جاتا ہے۔ اور ان دونوں روایتوں میں سے جس کے راوی کم درجے کے ہوں اس روایت کو شاذ کہا جاتا ہے۔ ایسی صورت میں محفوظ روایت ہی قابل قبول ہوتی ہے۔ تفصیل کے لیے دیکھئے: نزہۃ النظر فی توضیح نخبۃ الفکر: ص، 84 - اشراق الفجر اردو ترجمہ شرح نخبۃ الفکر (ترجمہ از: امان اللہ عاصم): ص، 80۔\n(2) العلل لابن ابی حاتم: 395/2۔"}],[293,"§چوتھی حدیث (امام قرآت کرے تو تم خاموش رہو):\nہمیں ابوسعد احمد بن محمد المالینی نے بیان کیا، انھوں نے کہا: ہمیں ابواحمد عبداللہ بن عدی الحافظ نے بیان کیا، انھوں نے کہا: ہمیں محمد بن حسین بن مکرم نے بیان کیا، انھوں نے کہا: ہمیں احمد بن منیع نے بیان کیا، انھوں نے کہا: ہمیں ابوسعد محمد بن میسر الصاغانی نے بیان کیا، انھوں نے کہا: ہمیں محمد بن عجلان نے بیان کیا، انھوں نے اپنے والد (عجلان) سے، انھوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کیا کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا: جب امام قرآت کرے تو تم خاموش رہو۔ (1)\nسند اور متن، دونوں میں خرابی:\n(ابوسعد الصاغانی کی روایت کردہ) یہ باطل روایت ہے۔ ابوسعد محمد بن میسر الصاغانی نے اس روایت کو محمد بن عجلان کے واسطے سے غلط (الفاظ میں) روایت کیا ہے۔ اس کی سند تبدیل کر دی اور اس کے متن میں بھی اضافہ کر دیا۔ اور محمد بن عجلان سے روایت کرنے والے ثقہ راویوں کے (بیان کردہ الفاظ کے) مخالف روایت بیان کی۔ ابوسعد محمد بن میسر الصاغانی پر امام یحییٰ بن معین اور دیگر ائمہ نے جرح کی ہے۔ (2)\nمتن میں خرابی:\nامام محمد بن اسماعیل البخاری رحمہ اللہ فرماتے ہیں: عبداللہ بن یوسف تنیسی نے لیث بن سعد سے روایت کیا، انھوں نے محمد بن عجلان سے، انھوں نے ابوالزناد سے، انھوں نے اعرج سے، انھوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے اس حدیث کو روایت کیا ہے۔\nاور محمد بن عجلان نے سعید سے بھی روایت کی ہے، انھوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے اس حدیث کو روایت کیا۔\nاور محمد بن عجلان نے مصعب بن محمد، قعقاع بن حکیم الکنانی اور زید بن اسلم سے بھی یہ حدیث روایت کی ہے، انھوں نے ابوصالح سے، انھوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے، انھوں نے نبی کریم صلی اللہ علیہ وسلم سے روایت کی ہے۔\nامام بخاری رحمہ اللہ نے مزید فرمایا: بکر بن مضر نے ابن عجلان سے اسی حدیث کو روایت کیا ہے، انھوں نے ابوالزناد سے، انھوں نے اعرج سے، انھوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے، انھوں نے نبی کریم صلی اللہ علیہ وسلم سے روایت کیا۔ لیکن (بکر بن مضر نے بھی) یہ الفاظ نہیں کہے کہ ’’جب امام قرآت کرے تو تم خاموش رہو‘‘۔ (3)\nامام بخاری رحمہ اللہ مزید فرماتے ہیں: سہیل بن ابی صالح نے اپنے والد محترم سے روایت کیا ہے، انھوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے، انھوں نے نبی کریم صلی اللہ علیہ وسلم سے حدیث روایت کی ہے۔ سہیل بن ابی صالح نے بھی وہ اضافہ بیان نہیں کیا، جو ابوخالد الاحمر نے محمد بن عجلان کے واسطے سے بیان کیا ہے۔ اسی طرح ابوسلمہ، ہمام، ابویونس اور دیگر متعدد راویوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے یہ حدیث روایت کی ہے۔ لیکن کسی نے بھی اس اضافے (یعنی: جب امام قرآت کرے تو تم خاموش رہو، کے الفاظ) کو بیان کرنے میں ابوخالد الاحمر کی متابعت (تائید) نہیں کی۔ (4)\nامام بخاری رحمہ اللہ نے مزید فرمایا: ابوسائب نے سیدنا ابوہریرہ رضی اللہ عنہ سے یہ الفاظ روایت کیے ہیں کہ ’’اسے (یعنی سورت فاتحہ کو) اپنے دل ہی دل میں پڑھ لیا کرو‘‘۔ (یعنی: سیدنا ابوہریرہ رضی اللہ عنہ تو سورت فاتحہ پڑھنے کے قائل تھے اور اس کی تعلیم بھی دیتے تھے اور مقتدی کو بھی لازمی پڑھنے کی تاکید فرماتے تھے۔) (5)\nاگر یہ روایت صحیح ہو تو...!\nامام بخاری رحمہ اللہ فرماتے ہیں: اگر یہ (ابوخالد الاحمر کی روایت) صحیح بھی ہو تو اسے فاتحہ کے علاوہ پر محمول کیا جائے گا اور (کہا جائے گا کہ) مقتدی تب قرآت کرے جب امام سکتہ کرتا ہے۔ اس حدیث سے سورت فاتحہ ترک کرنا ثابت نہیں ہوتا۔ (6)\nاور امام بخاری رحمہ اللہ نے یہ بھی بیان کیا ہے کہ سیدنا ابوہریرہ رضی اللہ عنہ فرماتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم تکبیر تحریمہ اور قرآت کے درمیان سکتہ کیا کرتے تھے۔ (7) اور امام بیہقی رحمہ اللہ فرماتے ہیں: سیدنا سمرہ بن جندب رضی اللہ عنہ کی حدیث میں مذکور ہے کہ آپ صلی اللہ علیہ وسلم قرآت سے پہلے بھی اور بعد میں بھی سکتہ کرتے تھے۔ (8)\nامام بخاری رحمہ اللہ فرماتے ہیں: جب مقتدی، امام کے سکتہ میں (سورت فاتحہ کی) قرآت کرے گا تو ابوخالد الاحمر کی حدیث: ’’جب امام قرآت کرے تو خاموش رہو‘‘ کی مخالفت نہیں ہوگی۔ کیونکہ مقتدی نے امام کی خاموشی میں قرآت کی ہے اور امام کی قرآت کے وقت خاموش رہا ہے۔ (9)\nلیث بن سعد رحمہ اللہ کی روایت:\nابوبکر محمد بن اسحاق بن خزیمہ فرماتے ہیں: اس حدیث (یعنی: ابوخالد الاحمر کی بیان کردہ حدیث) میں ’’جب امام قرآت کرے تو تم خاموش رہو‘‘ کے الفاظ وہم ہیں۔ امام لیث بن سعد نے بھی یہ حدیث روایت کی ہے، اور وہ مصر کے جید عالم اور جلیل القدر فقیہ اور بلاشبہ اپنے دور کے بہت بڑے عالم، مضبوط حافظے والے، صاحب اتقان و کتاب تھے۔ انھوں نے بھی یہ حدیث محمد بن عجلان سے روایت کی ہے۔ انھوں نے بھی اسی طرح روایت ذکر کی ہے جس طرح امام بخاری نے بیان کی ہے۔ ان میں سے ’’جب امام قرآت کرے تو تم خاموش رہو‘‘ کے الفاظ نہیں ہیں۔\nامام محمد بن یحییٰ الزہلی رحمہ اللہ کا فیصلہ کن تبصرہ:\nامام ابن خزیمہ رحمہ اللہ فرماتے ہیں: امام محمد بن یحییٰ الزہلی نے فرمایا: لیث بن سعد کی محمد بن عجلان سے روایت کردہ حدیث کا متن، ابوخالد الاحمر کی روایت کے متن کے مقابلے میں زیادہ صحیح ہے۔ (حدیث میں جس واقعہ کی طرف اشارہ ہے) اس واقعہ میں ’’جب امام قرآت کرے تو تم خاموش رہو‘‘ کے الفاظ نبی کریم صلی اللہ علیہ وسلم ثابت ہی نہیں ہیں۔ کیونکہ یہ حدیث سیدنا ابوہریرہ رضی اللہ عنہ سے یہ قصہ صحیح اور متصل اسناد کے ساتھ ثابت شدہ متواتر احادیث میں بیان ہوا ہے۔ اور ان میں سے کسی بھی (صحیح و متصل) حدیث میں ’’جب امام قرآت کرے تو تم خاموش رہو‘‘ کے الفاظ نہیں ہیں۔ یہ الفاظ صرف ابوخالد الاحمر اور ان راویوں کی روایت میں ہیں، جن کی محدثین کے ہاں کوئی اہمیت نہیں ہے۔\nاس روایت کے صحیح متن کی دیگر اسناد:\nپھر امام ابن خزیمہ رحمہ اللہ نے اس حدیث کو محمد بن عمرو کے واسطے سے ذکر کیا ہے، انھوں نے ابوسلمہ سے، انھوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کیا ہے۔\nاور اعمش کی سند سے بھی روایت کیا ہے، کہ اعمش نے ابوصالح سے، انھوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے یہ حدیث روایت کی ہے۔\nاور سہیل بن ابی صالح کی سند سے بھی روایت کیا ہے کہ سہیل بن ابی صالح نے اپنے والد محترم ابوصالح سے، انھوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے یہ حدیث روایت کی ہے۔\nان میں سے کسی بھی حدیث میں ’’جب امام قرآت کرے تو تم خاموش رہو‘‘ کے الفاظ کا اضافہ نہیں ہیں۔\nاور یہ حدیث صحیح بخاری میں بھی مذکور ہے کہ اعمش نے ابوصالح سے، انھوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی ہے۔\nاور سہیل بن ابی صالح نے اپنے والد محترم سے، انھوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی ہے، ابوالزناد نے اعرج سے، انھوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی ہے۔ (10)\nاور ہمام بن منبہ، ابوعلقمہ الہاشمی اور سیدنا ابوہریرہ رضی اللہ عنہ کے غلام ابویونس نے بھی یہ حدیث روایت کی ہے۔ (11)\nان سب نے سیدنا ابوہریرہ رضی اللہ عنہ سے ہی اس حدیث کو روایت کیا ہے۔ اور ان میں سے کسی کی حدیث میں ’’جب امام قرآت کرے تو تم خاموش رہو‘‘ کے الفاظ نہیں ہیں۔\nاور یہ حدیث صحیح بخاری میں ہشام بن عروہ سے بھی مروی ہے، انھوں نے اپنے والد محترم عروہ بن زبیر سے، انھوں نے ام المومنین سیدہ عائشہ صدیقہ رضی اللہ عنہا اس حدیث کو روایت کیا ہے۔ (12)\nابوالزبیر نے بھی یہی حدیث سیدنا جابر رضی اللہ عنہ سے روایت کی ہے۔ اس میں بھی ’’جب امام قرآت کرے تو تم خاموش رہو‘‘ کے الفاظ کا اضافہ نہیں ہے۔\nیہی حدیث صحیح بخاری میں امام مالک بن انس، معمر بن راشد، لیث بن سعد، یونس بن یزید اور سفیان بن عیینہ نے امام ابن شہاب زہری سے روایت کی ہے، انھوں نے سیدنا انس بن مالک رضی اللہ عنہ سے روایت کیا ہے۔ اس میں بھی ’’جب امام قرآت کرے تو تم خاموش رہو‘‘ کے الفاظ کا اضافہ نہیں ہے۔ (13)\nپانچویں حدیث (امام قرآت کرے تو تم خاموش رہو):\nاس حدیث کو محمد بن عبدالرحمن الطفاوی نے بھی روایت کیا ہے، انھوں نے ایوب سختیانی سے، انھوں نے زہری سے، انھوں نے سیدنا انس بن مالک رضی اللہ عنہ سے یہ حدیث ’’جب امام قرآت کرے تو تم خاموش رہو‘‘ کے الفاظ کے اضافہ کے بغیر روایت کی ہے۔ صرف اس میں حسن بن علی بن شبیب المعمری نے غلطی کی ہے۔ اور اس کی ایسی بہت سی منکر تفردات موجود ہیں۔ [تفصیل کے لیے ملاحظہ فرمائیں:]","",{"f":"§حواشی\n(1) اسنادہ ضعیف۔ ابوسعد محمد بن میسر ضعیف راوی ہے۔ مسند احمد بن حنبل: 376/2 - سنن الدارقطنی: 329/1۔\n(2) تاریخ ابن معین، بروایۃ الدوری: 366/4، حدیث، 4788 - امام یحییٰ بن معین رحمہ اللہ فرماتے ہیں: ابوسعد متہم اور غیر معتبر تھا، شیاطین میں سے ایک شیطان تھا۔ بقول معاویہ بن صالح، امام یحییٰ بن معین کہتے ہیں کہ ابوسعد ضعیف راوی تھا۔ (تاریخ بغداد: 455/4)\n(3) جزء القراءۃ خلف الامام، للبخاری: ص، 146، 147۔\n(4) جزء القراءۃ خلف الامام، للبخاری: ص، 148۔\n(5) جزء القراءۃ خلف الامام، للبخاری: ص، 147۔\n(6) جزء القراءۃ خلف الامام، للبخاری: ص، 146۔\n(7) جزء القراءۃ خلف الامام، للبخاری: ص، 147۔\n(8) دیکھئے: حدیث نمبر: 274۔\n(9) جزء القراءۃ خلف الامام، للبخاری: ص، 148۔\n(10) ابوالزناد کی اعرج سے بیان کردہ حدیث مع سند اس طرح ہے: ’’حَدَّثَنَا أَبُو الْيَمَانِ، قَالَ: أَخْبَرَنَا شُعَيْبٌ، قَالَ: حَدَّثَنِي أَبُو الزِّنَادِ، عَنِ الْأَعْرَجِ، عَنْ أَبِي هُرَيْرَةَ، قَالَ: قَالَ النَّبِيُّ صلی اللہ علیہ وسلم: إِنَّمَا جُعِلَ الْإِمَامُ لِيُؤْتَمَّ بِهِ، فَإِذَا كَبَّرَ فَكَبِّرُوا، وَإِذَا رَكَعَ فَارْكَعُوا، وَإِذَا قَالَ: سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ؛ فَقُولُوا: رَبَّنَا وَلَكَ الْحَمْدُ، وَإِذَا سَجَدَ فَاسْجُدُوا، وَإِذَا صَلَّى جَالِسًا فَصَلُّوا جُلُوسًا أَجْمَعُونَ‘‘ [صحیح البخاری، کتاب الاذان، باب ایجاب التکبیر وافتتاح الصلاۃ، حدیث، 734]\n(11) ہمام بن منبہ کی بیان کردہ حدیث مع سند اس طرح ہے: ’’حَدَّثَنَا عَبْدُ اللَّهِ بْنُ مُحَمَّدٍ، قَالَ: حَدَّثَنَا عَبْدُ الرَّزَّاقِ قَالَ: أَخْبَرَنَا مَعْمَرٌ، عَنْ هَمَّامِ بْنِ مُنَبِّهٍ، عَنْ أَبِي هُرَيْرَةَ، عَنِ النَّبِيِّ صلی اللہ علیہ وسلم، أَنَّهُ قَالَ: إِنَّمَا جُعِلَ الْإِمَامُ لِيُؤْتَمَّ بِهِ، فَلَا تَخْتَلِفُوا عَلَيْهِ، فَإِذَا رَكَعَ فَارْكَعُوا، وَإِذَا قَالَ: سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ؛ فَقُولُوا: رَبَّنَا لَكَ الْحَمْدُ، وَإِذَا سَجَدَ فَاسْجُدُوا، ⇐ ⇐\n(12) صحیح البخاری، حدیث: 688 - صحیح مسلم، حدیث: 412۔\n(13) امام مالک کی روایت صحیح البخاری، 689 - لیث بن سعد کی روایت، صحیح البخاری، 733 - سفیان بن عیینہ کی روایت، صحیح البخاری، 805، 1114 - صحیح مسلم، 411، 413۔"}],[294,"ہمیں ابوعبداللہ الحافظ (امام حاکم) نے بیان کیا، انھوں نے کہا: ہمیں جعفر الخلدی نے بیان کیا، انھوں نے کہا: ہمیں حسن بن علی بن شبیب المعمری نے بیان کیا، انھوں نے کہا: ہمیں احمد بن المقدام ابوالاشعث نے بیان کیا، انھوں نے کہا: ہمیں محمد بن عبدالرحمن الطفاوی نے بیان کیا، انھوں نے کہا: ہمیں ایوب سختیانی نے بیان کیا، انھوں نے زہری سے، انھوں نے\n⇐ ⇐ وَإِذَا صَلَّى جَالِسًا فَصَلُّوا جُلُوسًا أَجْمَعُونَ، وَأَقِيمُوا الصَّفَّ فِي الصَّلَاةِ، فَإِنَّ إِقَامَةَ الصَّفِّ مِنْ حُسْنِ الصَّلَاةِ‘‘ [صحیح البخاری، کتاب الاذان، باب اقامۃ الصف من تمام الصلاۃ، حدیث، 722]\nسیدنا انس بن مالک رضی اللہ عنہ سے روایت کیا کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا: جب امام قرآت کرے تو تم خاموش رہو۔ (1)","",{"f":"§حواشی\n(1) شذوذ کی وجہ سے ضعیف ہے۔ السنن الکبریٰ للنسائی، حدیث: 360/4، حدیث، 7515 - الکامل فی ضعفاء الرجال، لابن عدی: 194/6۔ [اس روایت کی علتیں اور خرابیاں حسب ذیل ہیں:]"}],[295,"§حسن بن علی معمری نے متن میں غلط بیان کی ہے:\nہمیں ابوسعد المالینی نے بیان کیا، انھوں نے کہا: ہمیں ابواحمد عبداللہ بن عدی الحافظ نے بیان کیا، انھوں نے کہا: یہ حدیث محمد بن عبدالرحمن الطفاوی کے علاوہ کسی نے بھی ایوب سختیانی سے بیان نہیں کی۔ جبکہ حسن بن علی بن شبیب المعمری نے ابوالاشعث احمد بن المقدام کے واسطے سے بیان کی ہے کہ انھوں نے محمد بن عبدالرحمن الطفاوی سے روایت کی ہے۔ اس نے اس حدیث میں ان الفاظ کا اضافہ کر دیا کہ ’’جب امام قرآت کرے تو تم خاموش رہو‘‘۔ اسی وجہ سے علماء نے اس پر جرح کی ہے۔ (1)\nغلط بیانی کی وضاحت:\nامام ابواحمد عبداللہ ابن عدی کہتے ہیں: ہمیں عبدان الاہوازی الحافظ نے بیان کیا: جب معمری نے اس حدیث کو ابوالاشعث احمد بن مقدام کے واسطے سے (’’جب امام قرآت کرے تو تم خاموش رہو‘‘ کے) اضافے کے ساتھ بیان کیا، تو بغداد سے لوگوں نے مجھے خط لکھا۔ تو میں نے انھیں جوابی خط میں لکھا کہ محمد بن بکار، اسماعیل بن سیف اور ابوالاشعث احمد بن مقدام، تینوں نے ہمیں یہ حدیث محمد بن عبدالرحمن الطفاوی سے بیان کی ہے۔ اس میں تو یہ اضافہ نہیں ہے۔ (2)\nچھٹی حدیث (امام قرآت کرے تو تم خاموش رہو):\nامام بیہقی رحمہ اللہ فرماتے ہیں: سلیمان بن ارقم سے بھی یہ حدیث مروی ہے۔ انھوں نے حسن بصری اور ابن شہاب زہری سے، انھوں نے سیدنا انس بن مالک رضی اللہ عنہ سے روایت کی ہے کہ نبی کریم صلی اللہ علیہ وسلم ایک گھوڑے پر سوار ہوئے۔ تو اس سے گر گئے۔ آپ صلی اللہ علیہ وسلم کے قدم مبارک کو موچ آ گئی۔ صحابہ کرام رضی اللہ عنہم آپ صلی اللہ علیہ وسلم کے پاس تیمارداری کے لیے آئے ہوئے تھے، کہ نماز کا وقت ہو گیا۔ آپ صلی اللہ علیہ وسلم صحابہ کرام رضی اللہ عنہم کو نماز پڑھانے لگے تو آپ صلی اللہ علیہ وسلم بیٹھ گئے، لیکن صحابہ کرام رضی اللہ عنہم کھڑے ہو گئے۔ آپ صلی اللہ علیہ وسلم نے صحابہ کو اشارہ کیا کہ بیٹھ جاؤ، تو وہ سب بھی بیٹھ گئے۔ جب آپ صلی اللہ علیہ وسلم نماز سے فارغ ہوئے تو فرمایا: «إِنَّمَا جُعِلَ الْإِمَامُ لِيُؤْتَمَّ بِهِ فَإِذَا كَبَّرَ فَكَبِّرُوا وَإِذَا قَرَأَ فَأَنصِتُوا» یعنی: امام اس لیے مقرر کیا گیا ہے کہ تم اس کی اقتدا کرو۔ جب وہ تکبیر کہے تو تم بھی تکبیر کہو، جب وہ قرآت کرے تو تم خاموش رہو۔ [اس حدیث کی سند حسب ذیل ہے:]","",{"f":"§حواشی\n(1) اسنادہ صحیح۔ الکامل، لابن عدی: 194/6۔ یہ حدیث محمد بن عبدالرحمن الطفاوی نے بھی روایت کی ہے، اس میں بھی ’’جب امام قرآت کرے تو تم خاموش رہو‘‘ کے الفاظ نہیں ہیں۔ اور حقیقت یہ ہے کہ محمد بن عبدالرحمن الطفاوی سے اس حدیث کو روایت کرنے والے صرف ایوب سختیانی ہیں۔ لیکن جب یہ حدیث حسن بن علی بن شبیب المعمری نے بیان کی تو کہا کہ یہ حدیث احمد بن مقدام ابوالاشعث نے محمد بن عبدالرحمن الطفاوی سے روایت کی ہے۔ یعنی حسن بن علی بن شبیب المعمری نے غلط اور خود ساختہ سند کے ساتھ اس حدیث کو روایت کیا۔ یہیں پر بس نہیں، اس نے متن میں بھی خرابی کی، متن میں یہ الفاظ اضافی بیان کیے کہ ’’جب امام قرآت کرے تو تم خاموش رہو‘‘۔ یہ روایت حسن بن علی المعمری کی انہی خرابیوں کی وجہ سے ناقابل قبول اور ناقابل حجت ہے۔ یہ وضاحت جرح و تعدیل اور علم اسماء الرجال کے امام، علامہ ابن عدی نے بیان کی ہے۔\n(2) الکامل، لابن عدی: 337/2۔"}],[296,"یہ حدیث ہمیں ابوالحسین بن بشران نے بیان کی، انھوں نے کہا: ہمیں ابوجعفر الرزاز سے بیان کیا، انھوں نے کہا: ہمیں محمد بن سلیمان بن حارث نے بیان کیا، انھوں نے کہا: ہمیں ابوہشام الضبی نے بیان کیا، انھوں نے کہا: ہمیں سلیمان بن ارقم البصری نے بیان کیا، .... (1) (سند کا اگلا حصہ مع متن بالکل متصل سابقہ سطور میں دیکھیں)\nسلیمان بن ارقم مجروح راوی:\nیہ روایت سلیمان بن ارقم کی متفرد روایات میں سے ہے۔ اور سلیمان بن ارقم متروک راوی ہے۔ امام احمد بن حنبل اور امام یحییٰ بن معین رحمہما اللہ اور دیگر ائمہ نے اس پر جرح کی ہے۔ (2)","",{"f":"§حواشی\n(1) سلیمان بن ارقم متروک راوی ہے۔ سند ضعیف ہے۔ البتہ ’’وَإِذَا قَرَأَ فَأَنصِتُوا‘‘ کے علاوہ حدیث صحیح ہے۔\n(2) امام احمد بن حنبل رحمہ اللہ کی جرح کے لیے دیکھئے: العلل ومعرفۃ الرجال لعبداللہ بن احمد: 67/2 - الجرح والتعدیل، لابن ابی حاتم: 100/4 - الکامل فی ضعفاء الرجال لابن عدی: 250/3 - امام یحییٰ بن معین رحمہ اللہ کی جرح کے لیے دیکھئے: تاریخ ابن معین، بروایۃ الدوری: 527/3 - الجرح والتعدیل، لابن ابی حاتم: 100/4 - الکامل فی ضعفاء الرجال، لابن عدی: 250/3۔"}],[297,"اور ہمیں ابوسعد المالینی نے بیان کیا، انھوں نے کہا: ہمیں ابواحمد بن عدی نے بیان کیا، انھوں نے کہا: ہمیں محمد بن عبداللہ جنیدی نے بیان کیا، انھوں نے کہا: امام بخاری نے فرمایا: سلیمان بن ارقم قریظہ اور نضیر کا غلام تھا، اس کی حسن بصری اور ابن شہاب زہری سے بیان کردہ روایت کو محدثین نے ترک کیا (متروک قرار دیا) ہے۔ (1)","",{"f":"§حواشی\n(1) التاریخ الکبیر، للبخاری: 2/4 - التاریخ الصغیر، للبخاری: 180/2 - الکامل فی ضعفاء الرجال، لابن عدی: 250/3۔"}],[298,"§ساتویں حدیث (امام قرآت کرے تو تم خاموش رہو):\nبعض الناس نے اپنی سند سے عبدالمنعم بن بشیر کی روایت بیان کی ہے کہ انھوں نے عبدالرحمن بن زید بن اسلم سے، انھوں نے اپنے والد (زید بن اسلم) سے، انھوں نے اپنے دادا سے، انھوں نے سیدنا عمر بن خطاب رضی اللہ عنہ سے روایت کیا ہے کہ انھوں نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم نے ایک روز ظہر کی نماز پڑھائی۔ تو ایک آدمی نے آپ کے ساتھ، اپنے دل ہی دل میں قرآت کی۔ جب آپ صلی اللہ علیہ وسلم نے نماز مکمل کر لی تو فرمایا: کیا تم میں سے کسی نے میرے ساتھ ساتھ قرآت کی ہے؟ اس شخص نے عرض کیا: جی ہاں، اللہ کے رسول! میں ﴿سَبِّحِ اسْمَ رَبِّكَ الْأَعْلَى﴾ (سورۃ الاعلیٰ) پڑھ رہا تھا۔ آپ صلی اللہ علیہ وسلم نے فرمایا: میں بھی کہوں، کہ کیا ہو گیا ہے، قرآن پڑھنے میں مجھے الجھن ہو رہی ہے؟ کیا تمھارے لیے امام کی قرآت کافی نہیں؟ امام تو مقرر ہی اس لیے کیا گیا ہے کہ اس کی اقتدا کی جائے۔ جب وہ قرآت کرے تو تم خاموش رہو۔ (1)\nیہ متن صحیح حدیث کے متن کے مخالف ہے:\nیہ قصہ سیدنا عمران بن حصین رضی اللہ عنہ کے نبی کریم صلی اللہ علیہ وسلم سے بیان کردہ قصہ کے مخالف ہے۔ اس روایت میں ہے کہ اس آدمی نے آپ صلی اللہ علیہ وسلم کے ساتھ، اپنے دل ہی دل میں قرآت کی۔ جبکہ سیدنا عمران بن حصین رضی اللہ عنہ کی روایت میں ’’اپنے دل ہی دل میں‘‘ کے الفاظ نہیں ہیں۔ اس روایت میں ہے کہ اس آدمی نے کہا تھا کہ میں ﴿سَبِّحِ اسْمَ رَبِّكَ الْأَعْلَى﴾ پڑھ رہا تھا۔ جبکہ سیدنا عمران بن حصین رضی اللہ عنہ کی بیان کردہ روایت میں ہے کہ نبی کریم صلی اللہ علیہ وسلم نے پوچھا تھا کہ تم میں سے کس نے ﴿سَبِّحِ اسْمَ رَبِّكَ الْأَعْلَى﴾ پڑھی؟ ان الفاظ سے ثابت ہوتا ہے کہ آپ صلی اللہ علیہ وسلم نے اس آدمی کی قرآت کی آواز خود سنی تھی۔ پھر آپ صلی اللہ علیہ وسلم نے فرمایا: مجھے معلوم ہو گیا تھا کہ تم میں سے کوئی شخص (قرآت کرنے میں) مجھے پریشان کر رہا ہے۔\nاگر وہ آدمی قرآت بلند آواز سے نہ کرتا تو نبی کریم صلی اللہ علیہ وسلم کو اس کی قرآت سے پریشانی نہ ہوتی۔ (2)\nاس روایت کی سند بھی ضعیف ہے:\nاور سیدنا عمران بن حصین رضی اللہ عنہ کی روایت میں وہ اضافہ (یعنی: جب امام قرآت کرے تو تم خاموش رہو) بھی نہیں ہے جو عبدالمنعم بن بشیر نے (بالکل متصل گزشتہ سطور میں سیدنا عمر رضی اللہ عنہ سے مروی) اس حدیث (نمبر: 297) میں بیان کیا ہے۔ عبدالمنعم بن بشیر کو امام ابواحمد بن عدی الحافظ نے کتاب ’’الضعفاء‘‘ میں ذکر کیا ہے۔ اور فرمایا ہے کہ اس کی روایات منکر ہیں، ان کی متابعت موجود نہیں ہے۔ (3)\nاور (حدیث نمبر: 297 کو عبدالمنعم بن بشیر، ضعیف راوی سے روایت کرنے والا) عبدالرحمن بن زید بن اسلم، ان مشہور و معروف ضعیف راویوں میں سے ہے جن پر امام مالک بن انس رحمہ اللہ اور ان کے بعد دیگر ائمہ نے جرح کی ہے۔ (4)\nصحیح حدیث کے الفاظ:\nعبدالرحمن بن زید بن اسلم کے والد سے ہی روایت کرنے والے دیگر راویوں نے اس کی بیان کردہ روایت کی مخالفت کی ہے۔ عبداللہ بن عامر اسلمی نے (عبدالرحمن بن زید بن اسلم کے والد) زید بن اسلم سے روایت کیا، انھوں نے اپنے والد محترم سے روایت کیا ہے کہ سیدنا ابوہریرہ رضی اللہ عنہ نے اللہ تعالیٰ کے فرمان ﴿وَإِذَا قُرِئَ الْقُرْآنُ فَاسْتَمِعُوا لَهُ وَأَنصِتُوا لَعَلَّكُمْ تُرْحَمُونَ﴾ کے متعلق فرمایا: یہ آیت تب نازل ہوئی جب صحابہ رضی اللہ عنہم رسول اللہ صلی اللہ علیہ وسلم کے پیچھے نماز اونچی آواز نکالتے تھے۔ (5)\nآیت کا مقصود:\nاور اس آیت کے متعلق صحیح سند کے ساتھ عبدالعزیز بن محمد سے صحیح روایت مروی ہے کہ زید بن اسلم نے کہا: جو شخص امام کے پیچھے ہے اس کے لیے اللہ تعالیٰ نے فرمایا ہے: ﴿وَاذْكُرْ رَبَّكَ فِي نَفْسِكَ﴾ (یعنی اپنے دل ہی دل میں اپنے رب کو یاد کرو)۔ اللہ تعالیٰ فرما رہے ہیں: اپنے رب کو یاد کرو اور اپنے دل میں انصات (خاموشی) بھی اختیار کرو۔ (6) اس آیت میں اللہ تعالیٰ نے حکم دیا ہے کہ انسان اسے آواز بلند کیے بغیر اپنے دل میں ہی یاد بھی کرے اور انصات (خاموشی) بھی اختیار کرے۔\nقرآت اور انصات، بیک وقت کیسے؟\nہم ذکر کر چکے ہیں کہ ان دونوں (یعنی: قرآت اور انصات) کو بیک وقت انجام دینا ممکن ہے۔ وہ اس طرح کہ، مقتدی پست آواز سے قرآت کرے تو وہ اپنے امام کی قرآت کے لیے انصات پر عمل پیرا بھی ہوگا اور اپنے دل ہی دل میں قرآت بھی کرتا رہے گا۔ جس طرح نبی کریم صلی اللہ علیہ وسلم تکبیر اولیٰ اور قرآت کے درمیانی وقفہ میں کیا کرتے تھے۔ آپ صلی اللہ علیہ وسلم بظاہر خاموش ہوتے تھے لیکن پست آواز میں دعا پڑھ رہے ہوتے تھے۔ آپ صلی اللہ علیہ وسلم کی زبان مبارک تو بول رہی ہوتی تھی لیکن آپ صلی اللہ علیہ وسلم آواز بلند نہیں کرتے تھے بلکہ اپنے دل ہی دل میں ذکر کر رہے ہوتے تھے۔\nحدیث بیان کرنے میں خیانت:\nمیں نے دیکھا ہے کہ بعض لوگ اس آیت مبارکہ کے متعلق زید بن اسلم کا قول بیان کرتے ہیں، لیکن اس کا مکمل سیاق و سباق ذکر نہیں کرتے۔ (7) دراصل ان لوگوں کا حدیث بیان کرتے ہوئے ایسا ہی وطیرہ ہوتا ہے۔ حدیث کا صرف اتنا حصہ بیان کرتے ہیں جس سے ان کی بات کا تعلق ہوتا ہے۔ اور باقی حصہ چھوڑ دیتے ہیں۔ تاکہ پڑھنے والے کو یہی وہم رہے کہ یہ حدیث اس کے موقف کی دلیل ہے۔ اسے ذرہ برابر یہ خیال نہیں آتا کہ جو تمام تر خفیہ اور پوشیدہ باتوں کا جاننے والا ہے (یعنی اللہ تعالیٰ)، وہ اس کے کرتوت کو خوب جانتا ہے۔ اور حقیقت یہ ہے کہ ایسے (خائن) شخص کی کتاب (دلائل) کو جب کوئی عالم دیکھتا ہے تو وہ (عالم) اس شخص کی تلبیس (خیانت) کو بھانپ لیتا ہے۔ اللہ تعالیٰ ہمیں ایسے شخص کی مکاریوں سے محفوظ رکھے۔\nآٹھویں حدیث (امام قرآت کرے تو تم خاموش رہو):\nاسی طرح یہ شخص مغیرہ بن مسلم کی عطاء الخراسانی کے واسطے سے بیان کردہ روایت بھی بطور دلیل پیش کرتا ہے، کہ سیدنا عثمان رضی اللہ عنہ نے سیدنا معاویہ رضی اللہ عنہ کو خط لکھا تھا کہ جب آپ لوگ نماز کے لیے کھڑے ہوں تو امام کو بغور سنو اور انصات (خاموشی) اختیار کرو۔ میں نے رسول اللہ صلی اللہ علیہ وسلم کو سنا تھا، آپ صلی اللہ علیہ وسلم نے فرمایا تھا کہ جو شخص انصات کرتا ہے، (یعنی خاموش رہتا ہے) اور سنتا نہیں، اسے بھی اس شخص کے برابر اجر ملتا ہے جو خاموش رہتا اور سنتا بھی ہے۔ (8) دوسری روایت میں ہے کہ اپنے مقتدیوں کو حکم دیں کہ وہ اپنی صفیں برابر رکھیں، کندھے ملائیں، انصات کریں اور توجہ سے قرآت سنیں۔ (9)\nاس روایت کی علتیں:\nجبکہ یہ روایت منقطع ہے، اس کے راوی ایسے ہیں، جن سے دلیل لینا درست نہیں۔ درست بات یہ ہے کہ یہ روایت موقوف ہے۔ یہ بات سیدنا عثمان بن عفان رضی اللہ عنہ نے خطبہ میں کہی تھی۔ [ملاحظہ کیجئے]","",{"f":"§حواشی\n(1) اسنادہ ضعیف جدًا۔ عبدالمنعم بن بشیر متہم بالوضع راوی ہے۔ یہ سند تاریک ترین سند ہے۔ عبدالمنعم بن بشیر کو امام یحییٰ بن معین اور امام احمد بن حنبل رحمہما اللہ نے جھوٹا قرار دیا ہے۔ امام یحییٰ بن معین رحمہ اللہ فرماتے ہیں: میں عبدالمنعم بن بشیر کے پاس آیا، اس نے میرے سامنے ابومودود کی تقریباً دو سو احادیث رکھیں، میں نے پوچھا: کیا تم نے یہ تمام روایات ابومودود سے خود سنی ہیں؟ اس نے کہا: جی ہاں۔ میں نے کہا: اللہ سے ڈرو۔ تم جھوٹ بول رہے ہو۔ پھر میں اٹھ کر آ گیا۔ اور اس سے کوئی روایت کبھی نقل نہیں کی۔ امام احمد بن حنبل رحمہ اللہ کے صاحبزادے امام عبداللہ بن احمد رحمہ اللہ فرماتے ہیں کہ میں نے اپنے ابا جان سے کہا کہ میں نے عبدالمنعم بن بشیر کو بازار میں دیکھا، تو ابا جان نے فرمایا: میرے بیٹے! وہ کذاب شخص ہے۔ خلیلی نے اسے ائمہ سے منسوب موضوع روایات بیان کرنے والا قرار دیا ہے۔ اسی طرح ابن یونس اور ابن حبان نے اسے منکر الحدیث قرار دیا ہے۔ مزید دیکھئے: [لسان المیزان، 74/4]\n(2) یعنی اس روایت (حدیث نمبر: 297) میں واضح الفاظ میں مذکور ہے کہ مقتدی صحابی نے دل ہی دل میں قرآت کی تھی۔ اگر ایسا ہی تھا تو نبی کریم صلی اللہ علیہ وسلم کو اس صحابی کی قرآت سے الجھن کس طرح ہو سکتی تھی؟ کیونکہ اس صحابی کی قرآت بلند آواز سے تھی ہی نہیں۔\n(3) الکامل فی ضعفاء الرجال، لابن عدی: 36/7۔\n(4) الضعفاء للعقیلی: 331/2۔\n(5) دیکھئے، حدیث نمبر: 257۔\n(6) دیکھئے: حدیث، 269۔\n(7) زید بن اسلم کی روایت، 289 اور 297 نمبر پر دیکھیں۔\n(8) سیدنا عثمان رضی اللہ عنہ کی طرف منسوب کر کے یہ بات رسول اللہ صلی اللہ علیہ وسلم کی حدیث کے طور پر بیان کرنے والے کو ہی امام بیہقی رحمہ اللہ نے خائن کہا ہے۔ کیونکہ اس نے اس روایت کو بیان کرنے میں دو خیانتیں کی ہیں: پہلی خیانت یہ ہے کہ وہ شخص اپنے موقف کی تائید میں دلائل حاصل کرنے کے لیے اس قدر بے باک ہے کہ اس روایت کو رسول اللہ صلی اللہ علیہ وسلم کے فرمان یعنی مرفوع حدیث کے طور پر بیان کرتا ہے۔ جبکہ یہ روایت رسول اللہ صلی اللہ علیہ وسلم کی مرفوع حدیث نہیں بلکہ سیدنا عثمان رضی اللہ عنہ کا قول ہے۔ دوسری خیانت یہ ہے کہ اس نے اس روایت کا سیاق و سباق بیان نہیں کیا، جیسا کہ امام بیہقی رحمہ اللہ نے گزشتہ سطور میں اس خیانت کی طرف اشارہ بھی دیا ہے۔ حقیقت یہ ہے کہ یہ بات سیدنا عثمان رضی اللہ عنہ نے نماز کے متعلق نہیں بلکہ خطبہ جمعہ کے متعلق فرمائی تھی۔ جیسا کہ حدیث نمبر: 298 میں مذکور ہے۔\n(9) حوالہ کے لیے اگلی حدیث، نمبر: 298، دیکھئے۔"}],[299,"§اس روایت کا صحیح متن:\nہمیں ابوزکریا بن ابی اسحاق نے بیان کیا، انھوں نے کہا: ہمیں ابوالحسن الطرائفی نے بیان کیا، انھوں نے کہا: ہمیں\nعثمان بن سعید نے بیان کیا، انھوں نے کہا: ہمیں ابن بکیر نے بیان کیا، انھوں نے کہا: ہمیں مالک بن انس نے بیان کیا، اور عثمان بن سعید دارمی کہتے ہیں کہ ہمیں عبداللہ بن مسلمہ قعنبی نے بھی امام مالک کے سامنے قرآت کرتے ہوئے بیان کیا، امام مالک نے ابوالنضر مولیٰ عمر بن عبیداللہ سے، انھوں نے مالک بن ابی عامر سے روایت کیا، کہ سیدنا عثمان بن عفان رضی اللہ عنہ اپنے خطبہ میں فرمایا کرتے تھے ...... اور بہت کم خطبات میں آپ نے یہ بات نہ کہی ہوگی، (اکثر خطبات میں کہا کرتے تھے) ...... جب امام جمعہ کے روز (خطبہ کے لیے) کھڑا ہوتا ہے۔ تو اس کی بات غور سے سنو، خاموشی اختیار کرو۔ جو خاموش رہتا ہے، اگرچہ خطبہ سنتا نہیں، اس شخص کو بھی اُس کے برابر اجر ملتا ہے جو خاموش رہتا اور توجہ سے خطبہ سنتا ہے۔ جب نماز کھڑی ہو جائے تو صفیں برابر کرو۔ کندھے برابر کرو۔ کیونکہ صفیں درست کرنا نماز کے مکمل ہونے کے لیے ضروری ہے۔ (1)","",{"f":"§حواشی\n(1) اسنادہ حسن موقوفا۔ موطأ امام مالک، بروایۃ القعنبی، حدیث: 234 - مصنف عبدالرزاق: 132/2، حدیث، 2780 - مصنف ابن ابی شیبہ: 214/3، حدیث، 3552 - مسند الشافعی: حدیث، 293 - الأوسط، لابن المنذر: 69/4، حدیث، 1881 - السنن الکبریٰ، للبیہقی: 220/3۔"}]])